import { useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { useT } from '../../../i18n/index.js';
import { deriveAboutUpdateControl, isAboutUpdateActionDisabled } from '../../rules.js';
import type { AboutUpdateControl, AboutUpdatePrimaryAction, AppVersionInfo, UpdaterModel } from '../../types.js';
import { useSilentUpdatesToggle } from '../hooks/useSilentUpdatesToggle.js';
import type { UseSilentUpdatesToggleResult } from '../hooks/useSilentUpdatesToggle.js';

/**
 * Superset of this feature's own `AppVersionInfo` (`../../types.js`) with
 * plain desktop-build facts that carry no branching logic of their own —
 * `channel`/`platform`/`arch` are rendered verbatim and never inspected, so
 * they don't belong in that type's pure state machine (see
 * `deriveAboutUpdateControl`, which only reads `version`/`packaged`). All
 * three are optional: a host with nothing to report for one just omits that
 * row.
 */
export interface AboutAppVersionInfo extends AppVersionInfo {
  channel?: string;
  platform?: string;
  arch?: string;
}

export interface AboutTabLabels {
  versionLabel?: string;
  runtimeLabel?: string;
  packagedLabel?: string;
  developmentLabel?: string;
  channelLabel?: string;
  platformLabel?: string;
  archLabel?: string;
  releaseLinkLabel?: string;
  actionFailedLabel?: string;
  versionUnavailableLabel?: string;
  silentUpdatesLabel?: string;
  silentUpdatesHint?: string;
}

export interface AboutTabProps {
  /** `null` while version info hasn't loaded (or isn't obtainable) — renders
   *  an empty-state card with nothing else, same as the origin. */
  appVersionInfo: AboutAppVersionInfo | null;
  /** Kept host-side (e.g. behind the host's own subscription to platform
   *  update events) and passed down as a controlled prop; this tab never
   *  mutates it directly. */
  updaterModel: UpdaterModel;
  /**
   * Performs whichever action `deriveAboutUpdateControl` currently offers
   * (check/download/install/quit). The host owns the real platform bridge
   * and is responsible for advancing `updaterModel` afterward (its own
   * subscription is the natural place); this tab only tracks the in-flight
   * promise to disable the button and surface a generic failure.
   */
  onPerformUpdateAction: (action: AboutUpdatePrimaryAction) => Promise<void>;
  /** Opens the release notes / changelog link. Origin hardcoded this to
   *  Open Design's own GitHub releases page — host-supplied here instead,
   *  same convention as `ProviderPreset`/`LocaleOption`. */
  onOpenReleaseLink: () => void;
  /** Seed value for the "allow silent updates" toggle. Ignored (and the
   *  toggle itself not rendered) when `onSilentUpdatePreferenceChange` is
   *  omitted. Defaults to `false` if the handler is present but this isn't. */
  allowSilentUpdates?: boolean;
  /** Persists the "allow silent updates" preference. The toggle is absent
   *  entirely — not merely disabled — when this is omitted, since there is
   *  nothing for it to write through. See `useSilentUpdatesToggle` for the
   *  optimistic-write/rollback/race-safety behaviour behind it. */
  onSilentUpdatePreferenceChange?: (allow: boolean) => Promise<void>;
  labels?: AboutTabLabels;
}

type Translate = ReturnType<typeof useT>;
type ResolvedAboutTabLabels = Required<AboutTabLabels>;

/** Built-in (untranslated) copy for every label a host may override. */
const DEFAULT_LABELS: ResolvedAboutTabLabels = {
  versionLabel: 'Version',
  runtimeLabel: 'Runtime',
  packagedLabel: 'Packaged',
  developmentLabel: 'Development build',
  channelLabel: 'Channel',
  platformLabel: 'Platform',
  archLabel: 'Architecture',
  releaseLinkLabel: 'View releases',
  actionFailedLabel: 'Something went wrong. Try again.',
  versionUnavailableLabel: 'Version information is unavailable.',
  silentUpdatesLabel: 'Install updates automatically',
  silentUpdatesHint: 'Apply updates in the background without asking first.',
};

const LABEL_KEYS = Object.keys(DEFAULT_LABELS) as Array<keyof AboutTabLabels>;

/** Each label is the host override when given, else the translated default. */
function resolveLabels({ t }: { t: Translate }, { labels }: { labels?: AboutTabLabels | undefined }): ResolvedAboutTabLabels {
  const resolved = { ...DEFAULT_LABELS };
  for (const key of LABEL_KEYS) resolved[key] = labels?.[key] ?? t(DEFAULT_LABELS[key]);
  return resolved;
}

/**
 * The one thing that's genuinely render-local: whether an update action this
 * tab itself kicked off is still in flight, and whether the last one failed.
 */
function useUpdateActionRunner({
  onPerformUpdateAction,
}: Pick<AboutTabProps, 'onPerformUpdateAction'>) {
  const [actionBusy, setActionBusy] = useState(false);
  const [actionFailed, setActionFailed] = useState(false);
  const run = (action: AboutUpdatePrimaryAction) => {
    setActionBusy(true);
    setActionFailed(false);
    void onPerformUpdateAction(action).then(
      () => setActionBusy(false),
      () => {
        setActionBusy(false);
        setActionFailed(true);
      },
    );
  };
  return { actionBusy, actionFailed, run };
}

interface UpdateActionsProps {
  control: AboutUpdateControl;
  primaryLabel: string | null;
  actionDisabled: boolean;
  onPrimaryAction: (() => void) | undefined;
  onOpenReleaseLink: () => void;
  releaseLinkLabel: string;
}

function UpdateActions({
  control,
  primaryLabel,
  actionDisabled,
  onPrimaryAction,
  onOpenReleaseLink,
  releaseLinkLabel,
}: UpdateActionsProps) {
  // Origin styled 'download'/'install'/'quit' as primary and left 'check'
  // plain; simplified to "any actionable state reads as primary, any inert
  // one reads as ghost" — same visual intent, one fewer hardcoded branch,
  // and it falls straight out of a field `deriveAboutUpdateControl` already
  // computes rather than re-deriving OD's three-way action match.
  const primaryButtonClassName = `jini-button${control.primaryAction ? ' jini-button-primary' : ' jini-button-ghost'}`;
  return (
    <div className="jini-settings-about-actions">
      {primaryLabel ? (
        <button
          type="button"
          className={primaryButtonClassName}
          disabled={actionDisabled}
          onClick={onPrimaryAction}
          data-testid="about-update-action"
        >
          {primaryLabel}
        </button>
      ) : null}
      {control.showReleaseLink ? (
        <button
          type="button"
          className="jini-button jini-button-ghost"
          onClick={onOpenReleaseLink}
          data-testid="about-release-link"
        >
          {releaseLinkLabel}
        </button>
      ) : null}
    </div>
  );
}

/** A `<dt>/<dd>` row rendered only when the host supplied a value for it. */
function OptionalFactRow({ label, value }: { label: string; value: string | undefined }) {
  return value ? (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  ) : null;
}

interface VersionDetailsProps {
  appVersionInfo: AboutAppVersionInfo;
  labels: ResolvedAboutTabLabels;
  statusTone: AboutUpdateControl['statusTone'];
  statusText: string;
  actions: ReactNode;
  actionFailed: boolean;
}

function VersionDetails({ appVersionInfo, labels, statusTone, statusText, actions, actionFailed }: VersionDetailsProps) {
  return (
    <dl className="jini-settings-about-list">
      <div className="jini-settings-about-version-row">
        <div className="jini-settings-about-version-copy">
          <dt>{labels.versionLabel}</dt>
          <span className="jini-settings-about-version-num">{appVersionInfo.version}</span>
          <dd aria-live="polite" className={`jini-settings-about-status jini-settings-about-status--${statusTone}`}>
            {statusText}
          </dd>
        </div>
        {actions}
      </div>

      {actionFailed ? (
        <p className="jini-hint jini-settings-about-error" role="status">
          {labels.actionFailedLabel}
        </p>
      ) : null}

      <div>
        <dt>{labels.runtimeLabel}</dt>
        <dd>{appVersionInfo.packaged === false ? labels.developmentLabel : labels.packagedLabel}</dd>
      </div>
      <OptionalFactRow label={labels.channelLabel} value={appVersionInfo.channel} />
      <OptionalFactRow label={labels.platformLabel} value={appVersionInfo.platform} />
      <OptionalFactRow label={labels.archLabel} value={appVersionInfo.arch} />
    </dl>
  );
}

function SilentUpdatesToggle({
  silentUpdates,
  labels,
}: {
  silentUpdates: UseSilentUpdatesToggleResult;
  labels: ResolvedAboutTabLabels;
}) {
  return (
    <div className="jini-settings-subsection jini-settings-about-silent-updates">
      <label className="jini-settings-about-toggle">
        <input
          type="checkbox"
          checked={silentUpdates.allowSilentUpdates}
          disabled={silentUpdates.busy}
          onChange={(event) => silentUpdates.toggle(event.currentTarget.checked)}
          data-testid="about-silent-updates-toggle"
        />
        <span className="jini-settings-about-toggle-copy">
          <span>{labels.silentUpdatesLabel}</span>
          <span className="jini-hint">{labels.silentUpdatesHint}</span>
        </span>
      </label>
    </div>
  );
}

/**
 * App version + auto-update panel, plus the "allow silent updates"
 * preference. Origin: the `activeSection === 'about'` block in
 * `SettingsDialog.tsx` (~5509-5644) — everything up through the silent-
 * updates toggle (see this feature's `types.ts`/`rules.ts` for what "already
 * ported" means here). Diagnostics export and the onboarding-reset button
 * that OD's dialog stacks below this are separate, single-callback concerns
 * with no state machine of their own — left for whoever mounts this tab to
 * compose in (diagnostics export already exists generically as
 * `ExportDiagnosticsButton`).
 *
 * Update-control derivation is this feature's own `deriveAboutUpdateControl`/
 * `isAboutUpdateActionDisabled`; the silent-updates toggle's optimistic-
 * write/rollback/race-safety is `useSilentUpdatesToggle`. This component
 * only renders their results and owns the one thing that's genuinely
 * render-local: whether an update action this tab itself kicked off is
 * still in flight.
 *
 * @complexity O(1) — fixed-shape render, no iteration.
 */
export function AboutTab({
  appVersionInfo,
  updaterModel,
  onPerformUpdateAction,
  onOpenReleaseLink,
  allowSilentUpdates = false,
  onSilentUpdatePreferenceChange,
  labels,
}: AboutTabProps) {
  const t = useT();
  const { actionBusy, actionFailed, run } = useUpdateActionRunner({ onPerformUpdateAction });
  const silentUpdates = useSilentUpdatesToggle({ allowSilentUpdates, onSilentUpdatePreferenceChange });

  const control = useMemo(
    () => deriveAboutUpdateControl(updaterModel, appVersionInfo),
    [updaterModel, appVersionInfo],
  );
  const actionDisabled = isAboutUpdateActionDisabled(control, updaterModel, actionBusy);
  const resolvedLabels = resolveLabels({ t }, { labels });

  // `handlePrimaryAction` only exists when there is an action to run — it is
  // `undefined` in every state that renders the button disabled-and-inert
  // (e.g. "downloading"), so there is no dead "disabled but somehow clicked"
  // branch to guard against inside the handler itself.
  const { primaryAction } = control;
  const handlePrimaryAction = primaryAction == null ? undefined : () => run(primaryAction);

  return (
    <section className="jini-settings-section jini-settings-about">
      {appVersionInfo ? (
        <VersionDetails
          appVersionInfo={appVersionInfo}
          labels={resolvedLabels}
          statusTone={control.statusTone}
          statusText={t(control.statusKey, control.statusVars)}
          actionFailed={actionFailed}
          actions={
            <UpdateActions
              control={control}
              primaryLabel={control.primaryLabelKey ? t(control.primaryLabelKey) : null}
              actionDisabled={actionDisabled}
              onPrimaryAction={handlePrimaryAction}
              onOpenReleaseLink={onOpenReleaseLink}
              releaseLinkLabel={resolvedLabels.releaseLinkLabel}
            />
          }
        />
      ) : (
        <div className="jini-empty-card">{resolvedLabels.versionUnavailableLabel}</div>
      )}

      {onSilentUpdatePreferenceChange ? <SilentUpdatesToggle silentUpdates={silentUpdates} labels={resolvedLabels} /> : null}
    </section>
  );
}

import { useId, type ReactNode } from "react";

import { Icon } from "../../../../react/components/Icon.js";
import { LIGHTBOX_DISMISS_ATTR, useLightbox } from "./Lightbox.hooks.js";

type LightboxPart = "dialog" | "close" | "previous" | "next";

export interface LightboxProps {
  open: boolean;
  /** Shown above the media (usually the file name) and used as the dialog's accessible name. */
  title: string;
  onClose: () => void;
  /** The media itself. `img`/`video` children are contain-fit to the viewport and never upscaled. */
  children?: ReactNode;
  /** Zero-based position and set size; with `onNavigate` and `count > 1` the arrow pair renders. */
  index?: number | undefined;
  count?: number | undefined;
  onNavigate?: ((index: number) => void) | undefined;
  /** Caller-specific controls (download, copy, metadata), placed bottom-left opposite the arrows. */
  actions?: ReactNode;
  /** No locale is owned here; a translated caller passes its own accessible labels. */
  labels?: Partial<Record<"close" | "previous" | "next", string>> | undefined;
  /** Extra class on the `<dialog>` so a caller can scope its own media rules. */
  className?: string | undefined;
  /** Per-part attributes (agent handles, `data-jini-part` markers) without the shell knowing them. */
  partAttrs?: Partial<Record<LightboxPart, Record<string, string>>> | undefined;
  /** A fake controller can exercise rendering without a real native-dialog lifecycle. */
  useLightboxHook?: typeof useLightbox | undefined;
}

const DEFAULT_LABELS = { close: "Close preview", previous: "Previous", next: "Next" } as const;

// Native dialog supplies the focus trap, Escape and top-layer stacking, so there is no hand-built
// overlay or z-index policy. The dialog itself fills the viewport as the dark gray stage (rather
// than a card over a dim backdrop) so the media can take nearly all of the screen.
/** Full-viewport media lightbox: title and counter top-left, close top-right, the media as large
 *  as fits, caller actions bottom-left and the previous/next pair together bottom-right. */
export function Lightbox(props: LightboxProps) {
  const { open, title, children, actions, className, partAttrs = {}, useLightboxHook = useLightbox } = props;
  const labels = { ...DEFAULT_LABELS, ...props.labels };
  const titleId = useId();
  const vm = useLightboxHook({ open, onClose: props.onClose, index: props.index, count: props.count, onNavigate: props.onNavigate });

  return (
    <dialog
      ref={vm.dialogRef}
      className={className ? `jini-lightbox ${className}` : "jini-lightbox"}
      aria-labelledby={open ? titleId : undefined}
      onCancel={vm.handleCancel}
      onClick={vm.handleClick}
      {...partAttrs.dialog}
    >
      {open ? (
        <>
          <header className="jini-lightbox-header">
            <h2 id={titleId} className="jini-lightbox-title" title={title}>{title}</h2>
            {vm.counter ? <span className="jini-lightbox-counter">{vm.counter}</span> : null}
            <button type="button" ref={vm.closeRef} className="jini-lightbox-button jini-lightbox-close" aria-label={labels.close} onClick={props.onClose} {...partAttrs.close}>
              <Icon name="close" size={16} strokeWidth={1.8} />
            </button>
          </header>
          <div className="jini-lightbox-stage" {...{ [LIGHTBOX_DISMISS_ATTR]: "" }}>{children}</div>
          {actions || vm.navigable ? (
            <footer className="jini-lightbox-footer">
              <div className="jini-lightbox-actions">{actions}</div>
              {vm.navigable ? (
                <div className="jini-lightbox-nav">
                  <button type="button" ref={vm.prevRef} className="jini-lightbox-button" aria-label={labels.previous} disabled={!vm.hasPrev} onClick={vm.previous} {...partAttrs.previous}>
                    <Icon name="chevron-left" size={18} strokeWidth={1.8} />
                  </button>
                  <button type="button" ref={vm.nextRef} className="jini-lightbox-button" aria-label={labels.next} disabled={!vm.hasNext} onClick={vm.next} {...partAttrs.next}>
                    <Icon name="chevron-right" size={18} strokeWidth={1.8} />
                  </button>
                </div>
              ) : null}
            </footer>
          ) : null}
        </>
      ) : null}
    </dialog>
  );
}

/**
 * Keep state/effects and DOM helpers separate from JSX so the dropdown hook can be
 * injected through useDropdown and exercised directly without driving a portaled tree.
 * Compose the smaller hooks unconditionally in their original relative order to obey
 * React hook ordering. Extracting the live DOM key handling from pure highlight decisions
 * reduces the review burden without changing focus or event-order contracts.
 */
import { useSelectPopover, useSelectPopoverPosition, repositionSelectPopover, openSelectOnKey, applySelectNavigationKey } from '../../../../react/components/select-popover.js';
export { focusableInDomOrder, resolveTabTarget } from '../../../../react/components/select-popover.js';
import { useEffect, useId, useMemo, useRef, useState } from "react";

// Below eight options, a search field adds clutter to a list that is already easy to scan.
const SEARCH_VISIBILITY_THRESHOLD = 8;

// 280px is only a placement heuristic; the panel actual maxHeight and scroll limit use
// the remaining viewport space so a low trigger does not open a mostly off-screen panel.
const ESTIMATED_PANEL_HEIGHT = 280;

export interface SelectOption {
  value: string;
  label: string;
  /** Heading shown above the first option of each run with this value (e.g. "Pages", "Posts").
   *  Callers pass options already ordered by group; search narrows rows, headings follow. */
  group?: string | undefined;
  /** Short state shown as a muted pill after the label (e.g. "draft"); omit for the normal state. */
  badge?: string | undefined;
  /** Muted secondary text after the label, e.g. a slug telling two same-titled rows apart.
   *  Search matches it too. */
  detail?: string | undefined;
}

/** The group heading to paint before `options[index]`, or null when it continues the previous run. */
export function groupHeadingAt({ options, index }: { options: readonly SelectOption[]; index: number }): string | null {
  const group = options[index]?.group;
  return group && group !== options[index - 1]?.group ? group : null;
}

export interface PanelPosition {
  top?: number | undefined;
  bottom?: number | undefined;
  left: number;
  width: number;
  maxHeight: number;
}

/**
 * Use fixed viewport-relative coordinates to escape scrolling/overflow-hidden ancestors
 * without coupling to their layout. maxHeight uses actual remaining space, not the estimate,
 * so the panel scroll area clips options before the viewport edge does.
 */
export function computePosition({ trigger }: { trigger: HTMLElement }): PanelPosition {
  const rect = trigger.getBoundingClientRect();
  const gap = 4;
  const viewportHeight = window.innerHeight;
  const spaceBelow = viewportHeight - rect.bottom;
  // Space above ends at the trigger's scrolling pane, not the viewport: an app bar above that pane
  // is not room for the panel (owner, 2026-10-15: on a short phone the list flipped up and covered
  // the top bar). With nothing scrolling but the page this is 0 and placement is unchanged.
  const spaceAbove = rect.top - scrollPaneTop({ trigger });
  const openUpward = spaceBelow < ESTIMATED_PANEL_HEIGHT && spaceAbove > spaceBelow;
  if (openUpward) {
    return { bottom: viewportHeight - rect.top + gap, left: rect.left, width: rect.width, maxHeight: Math.max(120, spaceAbove - gap * 2) };
  }
  return { top: rect.bottom + gap, left: rect.left, width: rect.width, maxHeight: Math.max(120, spaceBelow - gap * 2) };
}

/** Top edge (viewport px, never negative) of the nearest scrollable PANE around the trigger, or 0.
 * A pane is an `overflow-y: auto|scroll` ancestor at least half the viewport tall — whether or not
 * it currently overflows (a short form still sits under the app bar), while a small scrolling
 * wrapper such as a table or chip strip does not count and leaves placement as it was.
 * @complexity O(depth) computed-style reads per measurement. */
export function scrollPaneTop({ trigger }: { trigger: HTMLElement }, _optional: Record<string, never> = {}): number {
  for (let el = trigger.parentElement; el && el !== document.body && el !== document.documentElement; el = el.parentElement) {
    const overflowY = getComputedStyle(el).overflowY;
    if ((overflowY === "auto" || overflowY === "scroll") && el.clientHeight * 2 >= window.innerHeight) {
      return Math.max(0, el.getBoundingClientRect().top);
    }
  }
  return 0;
}

export function buildOptionId({ listboxId, index }: { listboxId: string; index: number }): string {
  return `${listboxId}-option-${index}`;
}

/**
 * Positioning reports a clipped or obscured trigger through onOutOfView; deciding whether
 * to close belongs to the dropdown lifecycle rather than this reusable measurement hook.
 */
export function usePanelPosition({
  open,
  triggerRef,
  panelRef,
  searchInputRef,
  showSearch,
  onOutOfView,
}: {
  open: boolean;
  triggerRef: React.RefObject<HTMLButtonElement | null>;
  panelRef: React.RefObject<HTMLDivElement | null>;
  searchInputRef: React.RefObject<HTMLInputElement | null>;
  showSearch: boolean;
  onOutOfView: () => void;
}, _optional: Record<string, never> = {}) {
  return useSelectPopoverPosition({ open, triggerRef, panelRef, measurePosition: computePosition }, {
    focusInitial: ({ panel }) => (showSearch ? searchInputRef.current : panel)?.focus(), onOutOfView,
  });
}

/** Compatibility geometry seam; lifecycle decisions are owned by the shared popover. */
export function repositionOrClose({ trigger, onOutOfView, setPosition }: { trigger: HTMLElement; onOutOfView: () => void; setPosition: (position: PanelPosition) => void }, _optional: Record<string, never> = {}) {
  repositionSelectPopover({ trigger, measurePosition: computePosition, setPosition }, { onOutOfView });
}

// A search can remove the previously highlighted option; re-anchor to the first match
// rather than keep a stale index outside the narrowed list.
function useResetHighlightOnQueryChange({
  open,
  query,
  hasMatches,
  setHighlightedIndex,
}: {
  open: boolean;
  query: string;
  hasMatches: boolean;
  setHighlightedIndex: (index: number) => void;
}) {
  useEffect(() => {
    if (!open) return;
    setHighlightedIndex(hasMatches ? 0 : -1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query]);
}

/**
 * Keyboard highlight used to move logically past the visible fold without scrolling its
 * row into view. nearest scrolls only what is needed instead of recentering the list and
 * fighting a user who has already scrolled it manually.
 */
function useScrollHighlightedIntoView({
  open,
  highlightedIndex,
  optionRefs,
}: {
  open: boolean;
  highlightedIndex: number;
  optionRefs: React.RefObject<Map<number, HTMLLIElement>>;
}) {
  useEffect(() => {
    if (!open || highlightedIndex < 0) return;
    const el = optionRefs.current.get(highlightedIndex);
    // Guarded the same way as `document.elementFromPoint` above — this app's own jsdom test
    // harness doesn't implement `scrollIntoView` at all (not even as a no-op), so an unguarded call
    // throws inside the effect on every highlight change.
    if (el && typeof el.scrollIntoView === "function") el.scrollIntoView({ block: "nearest" });
  }, [open, highlightedIndex]);
}

export function edgeHighlightIndex({ filteredLength, edge }: { filteredLength: number; edge: "first" | "last" }): number {
  if (filteredLength === 0) return -1;
  return edge === "first" ? 0 : filteredLength - 1;
}

export function highlightedOptionOrNull({ filtered, highlightedIndex }: { filtered: SelectOption[]; highlightedIndex: number }): SelectOption | null {
  return highlightedIndex >= 0 ? (filtered[highlightedIndex] ?? null) : null;
}

export function applyHighlightKey({ key, filtered, highlightedIndex, actions }: { key: string; filtered: SelectOption[]; highlightedIndex: number; actions: {
    preventDefault: () => void;
    moveHighlight: (delta: 1 | -1) => void;
    setHighlightedIndex: (index: number) => void;
    selectOption: (option: SelectOption) => void;
  } }
): boolean {
  return applySelectNavigationKey({ key, actions: {
    preventDefault: actions.preventDefault, move: actions.moveHighlight,
    edge: (edge) => actions.setHighlightedIndex(edgeHighlightIndex({ filteredLength: filtered.length, edge })),
    choose: () => {
      const option = highlightedOptionOrNull({ filtered, highlightedIndex });
      if (option) actions.selectOption(option);
    },
  } });
}

// Keep live event/focus effects in the key handler; move the trigger-neighbour calculation
// out so changing the DOM effects does not bury the independently testable focus decision.
/**
 * Separate hook state from rendering so search visibility, wraparound, placement and
 * out-of-view closing can be asserted directly without coupling every case to portal DOM.
 */
export function useSelectDropdown({
  value,
  onChange,
  options,
}: {
  value: string;
  onChange: (value: string) => void;
  options: SelectOption[];
}, { disabled }: { disabled?: boolean | undefined } = {}) {
  const [query, setQuery] = useState("");
  const [highlightedIndex, setHighlightedIndex] = useState(-1);

  const searchInputRef = useRef<HTMLInputElement | null>(null);
  // Index -> `<li>` node, so the highlight-follow effect below can scroll the right row into view
  // without an id-based `querySelector` (this component's ids come from `useId()`, which can
  // contain characters — `:`, in React's own scheme — that need escaping in a CSS selector; a
  // direct ref avoids that entirely). Populated by each option's own ref callback below.
  const optionRefs = useRef<Map<number, HTMLLIElement>>(new Map());

  const listboxId = useId();

  const showSearch = options.length >= SEARCH_VISIBILITY_THRESHOLD;
  const popover = useSelectPopover({ measurePosition: computePosition }, {
    disabled, dismissWhenHidden: true,
    focusInitial: ({ panel }) => (showSearch ? searchInputRef.current : panel)?.focus(),
  });
  const { open, position, triggerRef, panelRef, closePanel } = popover;
  const filtered = useMemo(() => {
    if (!showSearch || !query.trim()) return options;
    const q = query.trim().toLowerCase();
    return options.filter((o) => o.label.toLowerCase().includes(q) || Boolean(o.detail?.toLowerCase().includes(q)));
  }, [options, query, showSearch]);

  const selectedOption = options.find((o) => o.value === value) ?? null;

  function openPanel() {
    if (disabled) return;
    const initialIndex = options.findIndex((o) => o.value === value);
    setQuery("");
    popover.openPanel();
    const firstIndex = options.length ? 0 : -1;
    setHighlightedIndex(initialIndex >= 0 ? initialIndex : firstIndex);
  }

  function selectOption(option: SelectOption) {
    onChange(option.value);
    closePanel({ refocusTrigger: true });
  }

  function moveHighlight(delta: 1 | -1) {
    setHighlightedIndex((current) => {
      if (filtered.length === 0) return -1;
      return (current + delta + filtered.length) % filtered.length;
    });
  }

  useResetHighlightOnQueryChange({ open, query, hasMatches: filtered.length > 0, setHighlightedIndex });
  useScrollHighlightedIntoView({ open, highlightedIndex, optionRefs });

  function handleTriggerKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    openSelectOnKey({ event, open, openPanel }, { disabled });
  }
  // Escape/Tab need live propagation and focus effects. Highlight/selection keys delegate
  // to the pure helper; preventDefault is injected to preserve its order before each action.
  function handlePanelKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (popover.handleDismissKey(event)) return;
    applyHighlightKey({ key: event.key, filtered, highlightedIndex, actions: {
      preventDefault: () => event.preventDefault(), moveHighlight, setHighlightedIndex, selectOption,
    } });
  }

  const optionId = (index: number) => buildOptionId({ listboxId: listboxId, index: index });

  return {
    open,
    query,
    setQuery,
    highlightedIndex,
    setHighlightedIndex,
    position,
    triggerRef,
    panelRef,
    searchInputRef,
    optionRefs,
    listboxId,
    showSearch,
    filtered,
    selectedOption,
    openPanel,
    closePanel,
    selectOption,
    handleTriggerKeyDown,
    handlePanelKeyDown,
    optionId,
  };
}

import { useOverlayContainer } from '@jini-ai/ui-kit/react';
import { useAgentHandle } from '../../../../react/hooks/useAgentHandle.js';
import { resolveSelectPortalContainer, resolveSelectOriginPage } from '../../../../react/components/select-popover.js';
import { createPortal } from "react-dom";
import { agentHandle } from "@jini-ai/agentic";
import { agentHandleSegment } from "@jini-ai/agentic";
import type { Translate } from "../../../i18n/dictionary-translator.js";
import { Fragment } from "react";
import { useSelectDropdown, groupHeadingAt, type PanelPosition, type SelectOption } from "./Select.hooks.js";

export type { SelectOption };
/** Use this custom listbox when in-panel search is needed: a native OS option list cannot host it.
 * Native selects otherwise avoid the accessibility/behavior tradeoffs of a simulated listbox.
 * JSX stays separate from dropdown state/DOM effects so injected useDropdown can render against a
 * fake without geometry or listeners. The body portal escapes clipping/stacking ancestors;
 * inside a native dialog, a dialog-local portal also keeps options in its top layer and out of
 * the inert page. Hosts can supply a container outside their own clipping regions.
 * Agent selection uses trigger/option clicks rather than native select_option; the -option namespace
 * keeps caller values from colliding with literal segments. Explicit base handles are not silently
 * sanitized: invalid caller choices should fail rather than publish a different handle. */

export interface SelectProps {
  value: string;
  onChange: (value: string) => void;
  options: SelectOption[];
  placeholder?: string | undefined;
  id?: string | undefined;
  "aria-label"?: string | undefined;
  "aria-labelledby"?: string | undefined;
  disabled?: boolean | undefined;
  /** Injectable state/effect seam; rendering tests need not drive portal positioning or listeners. */
  useDropdown?: typeof useSelectDropdown | undefined;
  agentHandle?: string | false | undefined;
  /** Host-owned portal destination. Defaults to the nearest dialog, kit overlay, then document.body.
   * Within a modal dialog, supply a descendant of that dialog so the panel remains interactive.
   * Keep this container outside scrolling/clipping regions and free of transforms that establish
   * a fixed-position containing block; panel coordinates are viewport-relative.
   * @example <Select {...selectionProps} portalContainer={dialogOverlayElement} /> */
  portalContainer?: Element | DocumentFragment | null | undefined;

  /** Caller-bound translation function; source copy is the default. */
  translate?: Translate | undefined;
  /** Legacy alias for callers porting the original select. */
  t?: Translate | undefined;
}

function SelectOptionRow({
  option,
  index,
  isSelected,
  isHighlighted,
  optionId,
  setOptionRef,
  onHighlight,
  onSelect,
  agentHandle: optionHandle,
}: {
  option: SelectOption;
  index: number;
  isSelected: boolean;
  isHighlighted: boolean;
  optionId: string;
  setOptionRef: (index: number, el: HTMLLIElement | null) => void;
  onHighlight: (index: number) => void;
  onSelect: (option: SelectOption) => void;
  agentHandle?: string | false | undefined;
}) {
  return (
    <li
      ref={(el) => setOptionRef(index, el)}
      id={optionId}
      role="option"
      aria-selected={isSelected}
      className={`select-option${isSelected ? " is-selected" : ""}${isHighlighted ? " is-highlighted" : ""}`}
      onMouseEnter={() => onHighlight(index)}
      onClick={() => onSelect(option)}
      {...(optionHandle ? agentHandle({ handle: optionHandle }, { role: "button", label: option.label }) : {})}
    >
      <span className="select-option-label">{option.label}</span>
      {option.detail ? <span className="select-option-detail">{option.detail}</span> : null}
      {option.badge ? <span className="select-option-badge">{option.badge}</span> : null}
      {isSelected ? (
        <svg className="select-option-check" viewBox="0 0 16 16" fill="none" aria-hidden="true">
          <path d="M3.5 8.5 6.5 11.5 12.5 4.5" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      ) : null}
    </li>
  );
}

function SelectPanel({
  panelRef,
  page,
  position,
  showSearch,
  searchInputRef,
  query,
  setQuery,
  filtered,
  value,
  highlightedIndex,
  listboxId,
  optionId,
  setOptionRef,
  onHighlight,
  onSelect,
  onKeyDown,
  searchHandle,
  optionHandles,
  t,
}: {
  panelRef: React.RefObject<HTMLDivElement | null>;
  page?: string | undefined;
  position: PanelPosition;
  showSearch: boolean;
  searchInputRef: React.RefObject<HTMLInputElement | null>;
  query: string;
  setQuery: (query: string) => void;
  filtered: SelectOption[];
  value: string;
  highlightedIndex: number;
  listboxId: string;
  optionId: (index: number) => string;
  setOptionRef: (index: number, el: HTMLLIElement | null) => void;
  onHighlight: (index: number) => void;
  onSelect: (option: SelectOption) => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLDivElement>) => void;
  searchHandle?: string | undefined;
  optionHandles?: readonly string[] | undefined;
  t: Translate;
}) {
  const searchHandleProps = searchHandle ? agentHandle({ handle: searchHandle }, { role: "field", label: "Search the option list" }) : {};
  return (
    <div
      ref={panelRef}
      data-agent-page={page}
      className="select-panel"
      style={{ left: position.left, width: position.width, top: position.top, bottom: position.bottom, maxHeight: position.maxHeight }}
      tabIndex={-1}
      onKeyDown={onKeyDown}
    >
      {showSearch ? (
        <input
          ref={searchInputRef}
          type="text"
          className="select-search"
          aria-label={t("Search options")}
          placeholder={t("Search…")}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          {...searchHandleProps}
        />
      ) : null}
      <ul className="select-list" role="listbox" id={listboxId}>
        {filtered.length === 0 ? (
          <li className="select-empty" role="presentation">
            {t("No matches")}
          </li>
        ) : (
          filtered.map((option, index) => (
            <Fragment key={option.value}>
              {groupHeadingAt({ options: filtered, index }) ? (
                <li className="select-group-label" role="presentation">{option.group}</li>
              ) : null}
              <SelectOptionRow
                option={option}
                index={index}
                isSelected={option.value === value}
                isHighlighted={index === highlightedIndex}
                optionId={optionId(index)}
                setOptionRef={setOptionRef}
                onHighlight={onHighlight}
                onSelect={onSelect}
                agentHandle={optionHandles?.[index]}
              />
            </Fragment>
          ))
        )}
      </ul>
    </div>
  );
}

export function resolveSelectTriggerLabel({ selectedOption, placeholder }: { selectedOption: SelectOption | null; placeholder: string | undefined }, { t = (key) => key }: { t?: Translate | undefined } = {}
): { text: string; className: string } {
  if (selectedOption) return { text: selectedOption.label, className: "select-trigger-label" };
  return { text: placeholder ?? t("Select…"), className: "select-trigger-label is-placeholder" };
}

function resolveSelectTriggerActiveDescendant(
  open: boolean,
  highlightedIndex: number,
  optionId: (index: number) => string,
): string | undefined {
  return open && highlightedIndex >= 0 ? optionId(highlightedIndex) : undefined;
}

function resolveSelectTriggerHandleProps(
  base: string | undefined,
  ariaLabel: string | undefined,
  placeholder: string | undefined,
): Record<string, unknown> {
  return base ? agentHandle({ handle: base }, { role: "button", label: ariaLabel ?? placeholder ?? "Select an option" }) : {};
}

/** Controlled searchable listbox with viewport positioning, dialog-local portals and keyboard navigation. */
export function Select(props: SelectProps, _optional: Record<string, never> = {}) {
  const { value, onChange, options, placeholder, id, disabled, useDropdown = useSelectDropdown, agentHandle: suppliedBase, translate, t = translate ?? ((key: string) => key) } = props;
  const base = useAgentHandle({ agentHandle: suppliedBase });
  const overlayContainer = useOverlayContainer({});
  const ariaLabel = props["aria-label"];
  const ariaLabelledBy = props["aria-labelledby"];

  const {
    open,
    highlightedIndex,
    setHighlightedIndex,
    position,
    triggerRef,
    panelRef,
    searchInputRef,
    optionRefs,
    listboxId,
    showSearch,
    filtered,
    selectedOption,
    openPanel,
    closePanel,
    selectOption,
    handleTriggerKeyDown,
    handlePanelKeyDown,
    optionId,
    query,
    setQuery,
  } = useDropdown({ value, onChange, options }, { disabled });

  function setOptionRef(index: number, el: HTMLLIElement | null) {
    if (el) optionRefs.current.set(index, el);
    else optionRefs.current.delete(index);
  }

  const triggerLabel = resolveSelectTriggerLabel({ selectedOption: selectedOption, placeholder: placeholder }, { t: t });
  const activeDescendant = resolveSelectTriggerActiveDescendant(open, highlightedIndex, optionId);
  // One handle per FILTERED option, recomputed as the search query narrows the list — an option
  // dropped by the current query has no rendered row to attach a handle to, so it is simply absent
  // this render rather than holding a handle nothing resolves to. `undefined` (not an empty array)
  // when `base` is explicitly opted out, so `SelectPanel` can tell "opted out" apart from "no options match".
  const optionHandles = base ? filtered.map((option) => `${base}-option-${agentHandleSegment({ value: option.value })}`) : undefined;

  return (
    <>
      <button
        type="button"
        ref={triggerRef}
        id={id}
        className="select-trigger"
        role="combobox"
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-controls={open ? listboxId : undefined}
        aria-activedescendant={activeDescendant}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
        disabled={disabled}
        onClick={() => (open ? closePanel({ refocusTrigger: false }) : openPanel())}
        onKeyDown={handleTriggerKeyDown}
        {...resolveSelectTriggerHandleProps(base, ariaLabel, placeholder)}
      >
        <span className={triggerLabel.className}>{triggerLabel.text}</span>
        <span className="select-trigger-chevron" aria-hidden="true" />
      </button>

      {open && position
        ? createPortal(
            <SelectPanel
              panelRef={panelRef}
              page={resolveSelectOriginPage({ trigger: triggerRef.current })}
              position={position}
              showSearch={showSearch}
              searchInputRef={searchInputRef}
              query={query}
              setQuery={setQuery}
              filtered={filtered}
              value={value}
              highlightedIndex={highlightedIndex}
              listboxId={listboxId}
              optionId={optionId}
              setOptionRef={setOptionRef}
              onHighlight={setHighlightedIndex}
              onSelect={selectOption}
              onKeyDown={handlePanelKeyDown}
              searchHandle={base ? `${base}-search` : undefined}
              optionHandles={optionHandles}
              t={t}
            />,
            resolveSelectPortalContainer({ trigger: triggerRef.current }, { container: props.portalContainer, fallbackContainer: overlayContainer })
          )
        : null}
    </>
  );
}

import type { ReactNode } from 'react';
import { useT } from '../../../i18n/index.js';
import { dayHeadingResult, groupByDay } from '../../rules.js';
import type { AssetGridItem, AssetGridViewMode } from '../../types.js';

export interface AssetGridBodyProps<TAsset extends AssetGridItem> {
  viewMode: AssetGridViewMode;
  assets: TAsset[];
  getDayKey: (asset: TAsset) => string;
  containerRef: React.RefObject<HTMLDivElement | null>;
  onMouseDown: (e: React.MouseEvent) => void;
  selecting: boolean;
  renderCard: (asset: TAsset, index: number) => ReactNode;
}

/**
 * Grid mode is one flat card grid; timeline mode groups the SAME cards into
 * day-bucketed sections (newest day first), each with a heading + count.
 * Both share `renderCard` and the caller's flat `index`, so shift-range /
 * rubber-band selection stays consistent whichever mode is active.
 */
export function AssetGridBody<TAsset extends AssetGridItem>({
  viewMode,
  assets,
  getDayKey,
  containerRef,
  onMouseDown,
  selecting,
  renderCard,
}: AssetGridBodyProps<TAsset>) {
  const t = useT();

  if (viewMode === 'timeline') {
    const groups = groupByDay(assets, getDayKey);
    return (
      <div
        className="asset-grid-timeline"
        ref={containerRef}
        onMouseDown={onMouseDown}
        data-selecting={selecting ? 'true' : 'false'}
      >
        {groups.map((group) => {
          const heading = dayHeadingResult(group.key);
          return (
            <section key={group.key} className="asset-grid-timeline-day">
              <div className="asset-grid-timeline-head">
                <span className="asset-grid-timeline-dot" aria-hidden />
                <h2 className="asset-grid-timeline-date">{heading.translatable ? t(heading.label) : heading.label}</h2>
                <span className="asset-grid-timeline-count">{group.items.length}</span>
              </div>
              <div className="asset-grid-timeline-grid">
                {group.items.map(({ asset, index }) => renderCard(asset, index))}
              </div>
            </section>
          );
        })}
      </div>
    );
  }

  return (
    <div className="asset-grid-grid" ref={containerRef} onMouseDown={onMouseDown} data-selecting={selecting ? 'true' : 'false'}>
      {assets.map((asset, index) => renderCard(asset, index))}
    </div>
  );
}

import { useRef, type KeyboardEvent, type MouseEvent } from 'react';
import { useT } from '../../../i18n/index.js';
import { humanBytes, isDoubleActivation, relativeTimeResult, type MenuAnchorRect } from '../../rules.js';
import type { AssetTreeRenameState } from '../../types.js';

export interface AssetTreeFileRowProps {
  path: string;
  /** Basename relative to the current directory (see `basenameForRename`) — what's actually shown/edited. */
  displayName: string;
  active: boolean;
  selected: boolean;
  kindLabel: string;
  kindGlyph: string;
  size: number;
  modifiedAt: number;
  /** Set only when THIS row is the one being renamed. */
  renaming: AssetTreeRenameState | null;
  onSelectPreview: (path: string) => void;
  onOpen: (path: string) => void;
  onToggleSelect: (path: string) => void;
  onOpenMenu: (path: string, anchor: MenuAnchorRect) => void;
  onRenameDraftChange: (draft: string) => void;
  onCommitRename: () => void;
  onCancelRename: () => void;
}

/**
 * One file row: hover-revealed checkbox + `⋯` menu trigger, a kind glyph
 * that opens the preview pane on single click and the file itself on double
 * click, an inline rename input when active, and size/modified-time cells.
 * Keyboard parity with the mouse: Enter/Space on the name previews on the
 * first press and opens on a second press within
 * `DOUBLE_ACTIVATION_WINDOW_MS` (mirrors a double-click for keyboard-only
 * navigation — ported from the origin `DesignFilesPanel`'s row name button).
 */
export function AssetTreeFileRow({
  path,
  displayName,
  active,
  selected,
  kindLabel,
  kindGlyph,
  size,
  modifiedAt,
  renaming,
  onSelectPreview,
  onOpen,
  onToggleSelect,
  onOpenMenu,
  onRenameDraftChange,
  onCommitRename,
  onCancelRename,
}: AssetTreeFileRowProps) {
  const t = useT();
  const lastActivationRef = useRef<number | undefined>(undefined);
  const relativeTime = relativeTimeResult(modifiedAt);
  const timeLabel = relativeTime.translatable ? t(relativeTime.label, relativeTime.params) : relativeTime.label;

  function handleNameKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    event.preventDefault();
    const now = Date.now();
    if (isDoubleActivation(lastActivationRef.current, now)) {
      lastActivationRef.current = undefined;
      onOpen(path);
    } else {
      lastActivationRef.current = now;
      onSelectPreview(path);
    }
  }

  function handleMenuTrigger(event: MouseEvent<HTMLSpanElement> | KeyboardEvent<HTMLSpanElement>) {
    event.stopPropagation();
    onOpenMenu(path, event.currentTarget.getBoundingClientRect());
  }

  return (
    <div
      data-testid={`asset-tree-file-row-${path}`}
      className={`asset-tree-row asset-tree-file-row${active ? ' active' : ''}${selected ? ' selected' : ''}`}
    >
      <span
        className="asset-tree-row-check"
        role="checkbox"
        aria-checked={selected}
        aria-label={selected ? t('Deselect {name}', { name: displayName }) : t('Select {name}', { name: displayName })}
        tabIndex={0}
        onClick={(event) => {
          event.stopPropagation();
          onToggleSelect(path);
        }}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            event.stopPropagation();
            onToggleSelect(path);
          }
        }}
      >
        {selected ? (
          <span className="asset-tree-row-check-mark" aria-hidden>
            ✓
          </span>
        ) : null}
      </span>
      <span
        className="asset-tree-row-icon"
        aria-hidden
        onClick={() => onSelectPreview(path)}
        onDoubleClick={() => onOpen(path)}
      >
        {kindGlyph}
      </span>
      <div className="asset-tree-row-name-wrap">
        {renaming ? (
          <input
            autoFocus
            className="asset-tree-rename-input"
            aria-label={t('Rename {name}', { name: displayName })}
            value={renaming.draft}
            disabled={renaming.saving}
            onChange={(event) => onRenameDraftChange(event.target.value)}
            onClick={(event) => event.stopPropagation()}
            onDoubleClick={(event) => event.stopPropagation()}
            onBlur={(event) => {
              if (event.currentTarget.dataset.skipRenameCommit === '1') return;
              onCommitRename();
            }}
            onKeyDown={(event) => {
              if (event.key !== 'Enter' && event.key !== 'Escape') return;
              event.preventDefault();
              event.currentTarget.dataset.skipRenameCommit = '1';
              if (event.key === 'Enter') onCommitRename();
              else onCancelRename();
            }}
          />
        ) : (
          <button
            type="button"
            className="asset-tree-row-name-btn"
            onClick={() => onSelectPreview(path)}
            onDoubleClick={() => onOpen(path)}
            onKeyDown={handleNameKeyDown}
          >
            <span className="asset-tree-row-name-wrap">
              <span className="asset-tree-row-name" title={displayName}>
                {displayName}
              </span>
              <span className="asset-tree-row-sub">{kindLabel}</span>
            </span>
          </button>
        )}
      </div>
      <span className="asset-tree-row-size" onClick={() => onSelectPreview(path)} onDoubleClick={() => onOpen(path)}>
        {humanBytes(size)}
      </span>
      <span className="asset-tree-row-time" onClick={() => onSelectPreview(path)} onDoubleClick={() => onOpen(path)}>
        {timeLabel}
      </span>
      <span
        data-testid={`asset-tree-file-menu-${path}`}
        className="asset-tree-row-menu"
        role="button"
        tabIndex={0}
        aria-label={t('Row actions for {name}', { name: displayName })}
        onClick={handleMenuTrigger}
        onKeyDown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            handleMenuTrigger(event);
          }
        }}
      >
        ⋯
      </span>
    </div>
  );
}

import { useT } from '../../../i18n/index.js';

export interface AssetTreeFolderRowProps {
  /** The folder's basename at this level (not the full path). */
  name: string;
  /** Full path from the tree root — what `onNavigate` receives. */
  path: string;
  /** Total files under this folder at every depth (see `countFilesUnderDir`). */
  fileCount: number;
  onNavigate: (path: string) => void;
}

/** One subdirectory row: navigates into the folder on click (both the row itself and its name button — matches the origin `DesignFilesPanel`'s doubled click targets). */
export function AssetTreeFolderRow({ name, path, fileCount, onNavigate }: AssetTreeFolderRowProps) {
  const t = useT();

  return (
    <div
      data-testid={`asset-tree-dir-row-${path}`}
      className="asset-tree-row asset-tree-dir-row"
      onClick={() => onNavigate(path)}
    >
      <span className="asset-tree-row-check" aria-hidden />
      <span className="asset-tree-row-icon" data-kind="folder" aria-hidden>
        ▸
      </span>
      <div className="asset-tree-row-name-wrap">
        <button type="button" className="asset-tree-row-name-btn" onClick={() => onNavigate(path)}>
          <span className="asset-tree-row-name-wrap">
            <span className="asset-tree-row-name" title={name}>
              {name}
            </span>
            <span className="asset-tree-row-sub">{t('{n} files', { n: fileCount })}</span>
          </span>
        </button>
      </div>
      <span className="asset-tree-row-size" />
      <span className="asset-tree-row-time" />
      <span className="asset-tree-row-menu asset-tree-row-menu-placeholder" aria-hidden />
    </div>
  );
}

import type { RefObject } from 'react';
import { useT } from '../../../i18n/index.js';

export interface AssetTreeRowMenuDownload {
  href: string;
  /** Called when the download link is clicked — the orchestrator wires this to close the popover (the download itself happens natively via `href`/`download`). */
  onClick: () => void;
}

export interface AssetTreeRowMenuProps {
  path: string;
  displayName: string;
  top: number;
  left: number;
  /** Attach to this popover's root — the outside-dismiss containment box (see `useAssetTreeRowMenu`). */
  containerRef: RefObject<HTMLDivElement | null>;
  canCopyLocalPath: boolean;
  /** True while this path's "Copied" confirmation is showing. */
  copied: boolean;
  /** Omit to hide the Download action entirely (no `getFileUrl` was supplied to `AssetTreeBrowser`). */
  download?: AssetTreeRowMenuDownload | undefined;
  onOpen: () => void;
  onRename: () => void;
  onCopyLocalPath: () => void;
  onDelete: () => void;
}

/**
 * The row `⋯` context menu popover: open in tab / rename / copy local path
 * (disabled unless the host's `getLocalPath` selector resolves one) /
 * download (hidden unless the host supplies `getFileUrl`) / delete.
 * Positioning (`top`/`left`) is computed upstream by
 * `useAssetTreeRowMenu`/`computeMenuPosition`; this component is purely
 * presentational.
 */
export function AssetTreeRowMenu({
  path,
  displayName,
  top,
  left,
  containerRef,
  canCopyLocalPath,
  copied,
  download,
  onOpen,
  onRename,
  onCopyLocalPath,
  onDelete,
}: AssetTreeRowMenuProps) {
  const t = useT();

  return (
    <div
      ref={containerRef}
      data-testid="asset-tree-row-menu-popover"
      className="asset-tree-row-popover"
      style={{ top, left }}
      onMouseDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
    >
      <button type="button" onClick={onOpen}>
        {t('Open')}
      </button>
      <button type="button" onClick={onRename}>
        {t('Rename')}
      </button>
      <button type="button" disabled={!canCopyLocalPath} onClick={onCopyLocalPath}>
        {copied ? t('Copied') : t('Copy local path')}
      </button>
      {download ? (
        <a href={download.href} download={displayName} style={{ textDecoration: 'none' }}>
          <button type="button" onClick={download.onClick}>
            {t('Download')}
          </button>
        </a>
      ) : null}
      <button type="button" className="danger" data-testid={`asset-tree-row-delete-${path}`} onClick={onDelete}>
        {t('Delete')}
      </button>
    </div>
  );
}

import { useCallback, useEffect, useRef } from 'react';
import { useT } from '../../../i18n/index.js';
import type { CommandPaletteItem } from '../../types.js';
import { useWiredCommandPalette } from '../hooks/useCommandPalette.js';
import { CommandPaletteRow } from './CommandPaletteRow.js';

export interface CommandPaletteProps {
  items: readonly CommandPaletteItem[];
  onSelect: (item: CommandPaletteItem) => void;
  onClose: () => void;
  scopeKey?: string | undefined;
  placeholder?: string | undefined;
  /** Custom hook override for dependency injection / testing. */
  useWiredCommandPalette?: typeof useWiredCommandPalette;
}

/**
 * A full-screen Cmd/Ctrl+P-style palette: a single search input over a
 * ranked, keyboard-navigable result list (arrow keys + wraparound, Enter to
 * select, Escape to close), with still-extant recents surfaced first for an
 * empty query. The host owns opening/closing it (there's no built-in
 * keybinding) and supplies the searchable `items`.
 *
 * Origin: `QuickSwitcher.tsx` — the origin's `ProjectFile`/`WorkspaceContextItem`
 * split (files vs. tabs, two different shapes) is replaced by one generic
 * `CommandPaletteItem`; see `packages/ui/source-map.md` for the full
 * genericization writeup, including why this is a distinct primitive from
 * `features/mention-autocomplete/`.
 */
export function CommandPalette({
  items,
  onSelect,
  onClose,
  scopeKey,
  placeholder,
  useWiredCommandPalette: useWiredCommandPaletteHook = useWiredCommandPalette,
}: CommandPaletteProps) {
  const t = useT();
  const palette = useWiredCommandPaletteHook({ items, onSelect, onClose, scopeKey });
  const listRef = useRef<HTMLDivElement | null>(null);
  const setInputRef = useCallback((node: HTMLInputElement | null) => {
    node?.focus();
  }, []);

  useEffect(() => {
    const el = listRef.current?.querySelector<HTMLDivElement>(`[data-idx="${palette.cursor}"]`);
    el?.scrollIntoView({ block: 'nearest' });
  }, [palette.cursor]);

  const hasQuery = palette.query.trim().length > 0;
  const emptyLabel = hasQuery ? t('No matches') : t('No items');
  const resolvedPlaceholder = placeholder ?? t('Search…');

  return (
    <div className="jini-command-palette-overlay" onMouseDown={onClose} role="dialog" aria-modal="true">
      <div className="jini-command-palette" onMouseDown={(event) => event.stopPropagation()}>
        <input
          ref={setInputRef}
          className="jini-command-palette__input"
          value={palette.query}
          onChange={(event) => palette.setQuery(event.target.value)}
          onKeyDown={palette.handleKeyDown}
          placeholder={resolvedPlaceholder}
          spellCheck={false}
          aria-label={resolvedPlaceholder}
        />
        <div className="jini-command-palette__list" ref={listRef} role="listbox">
          {palette.results.length === 0 ? (
            <div className="jini-command-palette__empty">{emptyLabel}</div>
          ) : (
            palette.results.map((result, index) => (
              <CommandPaletteRow
                key={result.item.id}
                result={result}
                index={index}
                active={index === palette.cursor}
                onHover={palette.setCursorTo}
                onSelect={palette.selectResult}
              />
            ))
          )}
        </div>
        <div className="jini-command-palette__footer">
          <span><kbd>↑</kbd><kbd>↓</kbd> {t('Navigate')}</span>
          <span><kbd>↵</kbd> {t('Select')}</span>
          <span><kbd>esc</kbd> {t('Close')}</span>
        </div>
      </div>
    </div>
  );
}

import type { CommandPaletteResult } from '../../types.js';

export interface CommandPaletteRowProps {
  result: CommandPaletteResult;
  index: number;
  active: boolean;
  onHover: (index: number) => void;
  onSelect: (result: CommandPaletteResult) => void;
}

export function CommandPaletteRow({ result, index, active, onHover, onSelect }: CommandPaletteRowProps) {
  const { item } = result;
  return (
    <div
      data-idx={index}
      role="option"
      aria-selected={active}
      className={`jini-command-palette-row${active ? ' jini-command-palette-row--active' : ''}`}
      onMouseEnter={() => onHover(index)}
      onClick={() => onSelect(result)}
    >
      <span className="jini-command-palette-row__name" title={item.title ?? item.name}>
        {item.name}
      </span>
      {item.path ? <span className="jini-command-palette-row__path">{item.path}</span> : null}
      <span className="jini-command-palette-row__kind">{item.kind.toUpperCase()}</span>
    </div>
  );
}

import type { KeyboardEvent as ReactKeyboardEvent, SyntheticEvent } from 'react';
import { agentHandleProps } from '@jini-ai/agentic';
import { useT } from '../../i18n/index.js';
import { connectorActionFlags, getConnectorDisplayToolCount, statusLabel, toolsBadgeTranslation } from '../rules.js';
import type { Connector, ConnectorAction, ConnectorActionFlags, ConnectorAuthorizationPending } from '../types.js';
import { Icon } from '../../../react/components/Icon.js';
import { ConnectorLogo } from './ConnectorLogo.js';

export interface ConnectorCardProps {
  connector: Connector;
  disabled?: boolean;
  pendingAction: ConnectorAction | null;
  authorizationPending?: ConnectorAuthorizationPending | undefined;
  authorizationCancelFailed: boolean;
  toolsLoaded: boolean;
  onConnect: (connectorId: string) => void;
  onDisconnect: (connectorId: string) => void;
  onCancelAuthorization: (connectorId: string) => void;
  onOpenDetails: (connectorId: string) => void;
  getCategoryLabel?: (category: string) => string;
  cancelFailedMessage?: string;
  continueInBrowserLabel?: string;
  onOpenExternalUrl?: (url: string) => void;
  /** This card's own agent handle — see `ConnectorsBrowser`'s `agentHandle` doc; `ConnectorGrid`
   *  derives one distinct handle per connector and passes it here. */
  agentHandle?: string;
}

type ConnectorStatusValue = Connector['status'];

function stopPropagation(event: SyntheticEvent) {
  event.stopPropagation();
}

/** Click handler for a card action: stops the click from also opening the card's details, then acts. */
function stopThen(onActivate: () => void) {
  return (event: SyntheticEvent) => {
    stopPropagation(event);
    onActivate();
  };
}

function ConnectorCardTitleDot({ status, isAuthorizationPending }: { status: ConnectorStatusValue; isAuthorizationPending: boolean }) {
  const t = useT();
  if (status === 'connected') {
    return (
      <span
        className={`connector-status-dot connector-card-title-dot status-${status}`}
        aria-label={t(statusLabel(status))}
        title={t(statusLabel(status))}
        role="img"
      />
    );
  }
  if (!isAuthorizationPending) return null;
  return (
    <span
      className="connector-status-dot connector-card-title-dot status-pending"
      aria-label={t('Authorization pending')}
      title={t('Authorization pending')}
      role="img"
    />
  );
}

function ConnectorCardToolsBadge({ connector, toolsLoaded }: { connector: Connector; toolsLoaded: boolean }) {
  const t = useT();
  const showToolsBadge = connector.toolCount !== undefined || connector.tools.length > 0 || toolsLoaded;
  const toolsBadge = toolsBadgeTranslation(getConnectorDisplayToolCount(connector));
  const toolsBadgeLabel = t(toolsBadge.key, toolsBadge.vars);
  return (
    <span className="connector-meta-tools" aria-hidden={!showToolsBadge}>
      {showToolsBadge ? (
        <span className="connector-tools-badge is-ready" title={toolsBadgeLabel}>
          <span>{toolsBadgeLabel}</span>
        </span>
      ) : null}
    </span>
  );
}

interface ConnectorCardActionButtonProps {
  flags: ConnectorActionFlags;
  disabled: boolean;
  agentHandle: string | undefined;
  onActivate: () => void;
}

function ConnectorDisconnectButton({ flags, disabled, agentHandle, onActivate }: ConnectorCardActionButtonProps) {
  const t = useT();
  const { isDisconnecting } = flags;
  return (
    <button
      type="button"
      className={`icon-only connector-action is-disconnect${isDisconnecting ? ' is-loading' : ''}`}
      disabled={!flags.canDisconnect}
      aria-busy={isDisconnecting || undefined}
      aria-label={t('Disconnect')}
      title={t('Disconnect')}
      tabIndex={disabled ? -1 : undefined}
      onMouseDown={stopPropagation}
      onKeyDown={stopPropagation}
      onClick={stopThen(onActivate)}
      {...agentHandleProps({}, { base: agentHandle, action: 'disconnect', role: 'button', label: t('Disconnect') })}
    >
      <Icon name={isDisconnecting ? 'spinner' : 'close'} size={12} />
    </button>
  );
}

function ConnectorConnectButton({ flags, disabled, agentHandle, onActivate }: ConnectorCardActionButtonProps) {
  const t = useT();
  const { isAuthorizationPending } = flags;
  const isBusy = flags.isConnecting || isAuthorizationPending;
  return (
    <button
      type="button"
      className={`icon-only connector-action is-connect${isBusy ? ' is-loading' : ''}`}
      disabled={!flags.canConnect}
      aria-busy={isBusy || undefined}
      aria-label={isAuthorizationPending ? t('Authorization pending') : t('Connect')}
      title={isAuthorizationPending ? t('Authorization in progress') : t('Connect')}
      tabIndex={disabled ? -1 : undefined}
      onMouseDown={stopPropagation}
      onKeyDown={stopPropagation}
      onClick={stopThen(onActivate)}
      {...agentHandleProps({}, { base: agentHandle, action: 'connect', role: 'button', label: t('Connect') })}
    >
      <Icon name={isBusy ? 'spinner' : 'plus'} size={12} />
    </button>
  );
}

function ConnectorCancelAuthorizationButton({ onActivate }: { onActivate: () => void }) {
  const t = useT();
  return (
    <button
      type="button"
      className="icon-only connector-action is-cancel-authorization"
      aria-label={t('Cancel authorization')}
      title={t('Cancel authorization')}
      onMouseDown={stopPropagation}
      onKeyDown={stopPropagation}
      onClick={stopThen(onActivate)}
    >
      <Icon name="close" size={12} />
    </button>
  );
}

function ConnectorStatusPill({ status }: { status: ConnectorStatusValue }) {
  const t = useT();
  if (status !== 'error' && status !== 'disabled') return null;
  return <span className={`connector-status-pill status-${status}`}>{t(statusLabel(status))}</span>;
}

interface ConnectorCardHintsProps {
  authorizationCancelFailed: boolean;
  redirectUrl: string | undefined;
  cancelFailedMessage: string | undefined;
  continueInBrowserLabel: string | undefined;
  onOpenExternalUrl: ((url: string) => void) | undefined;
}

/** The cancel-failed alert and the continue-in-browser link under the card body. */
function ConnectorCardHints({
  authorizationCancelFailed,
  redirectUrl,
  cancelFailedMessage,
  continueInBrowserLabel,
  onOpenExternalUrl,
}: ConnectorCardHintsProps) {
  const t = useT();

  function continueAuthorization(event: SyntheticEvent) {
    stopPropagation(event);
    // `continueAuthorization`'s only call site (the "continue in browser"
    // button below) only ever renders while
    // `isAuthorizationPending && authorizationPending.redirectUrl` already
    // holds in that same render, and React re-binds this closure fresh on
    // every render — so a re-check here was dead code for every real
    // click, removed rather than tested around (see
    // packages/ui/source-map.md's 2026-07-22 dated entry).
    onOpenExternalUrl?.(redirectUrl!);
  }

  return (
    <>
      {authorizationCancelFailed ? (
        <p className="connector-authorization-hint connector-authorization-error" role="alert">
          {cancelFailedMessage ?? t("Couldn't cancel authorization. Try again.")}
        </p>
      ) : null}
      {redirectUrl ? (
        <button type="button" className="connector-authorization-link" title={t('Authorization in progress')} onClick={continueAuthorization}>
          {continueInBrowserLabel ?? t('Continue in browser')}
        </button>
      ) : null}
    </>
  );
}

export function ConnectorCard({
  connector,
  disabled = false,
  pendingAction,
  authorizationPending,
  authorizationCancelFailed,
  toolsLoaded,
  onConnect,
  onDisconnect,
  onCancelAuthorization,
  onOpenDetails,
  getCategoryLabel = (category) => category,
  cancelFailedMessage,
  continueInBrowserLabel,
  onOpenExternalUrl,
  agentHandle,
}: ConnectorCardProps) {
  const t = useT();
  const flags = connectorActionFlags({ connector, pendingAction, authorizationPending, disabled });
  const categoryLabel = getCategoryLabel(connector.category);
  const actionProps = { flags, disabled, agentHandle };

  function openDetails() {
    if (disabled) return;
    onOpenDetails(connector.id);
  }

  function onKeyActivate(event: ReactKeyboardEvent<HTMLElement>) {
    if (event.key !== 'Enter' && event.key !== ' ') return;
    if (event.target !== event.currentTarget) return;
    event.preventDefault();
    openDetails();
  }

  return (
    <article
      className={`connector-card status-${connector.status}${disabled ? ' is-locked' : ''}`}
      data-connector-id={connector.id}
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || undefined}
      aria-label={t('Open details for {name}', { name: connector.name })}
      onClick={openDetails}
      onKeyDown={onKeyActivate}
      {...agentHandleProps({}, { base: agentHandle, role: 'button', label: connector.name })}
    >
      <div className="connector-card-top">
        <ConnectorLogo connectorId={connector.id} connectorName={connector.name} logoUrl={connector.logoUrl} size="sm" />
        <div className="connector-card-head">
          <h3 className="connector-card-title">
            <span className="connector-card-title-name">{connector.name}</span>
            <ConnectorCardTitleDot status={connector.status} isAuthorizationPending={flags.isAuthorizationPending} />
          </h3>
          <div className="connector-meta">
            <span className="connector-meta-item connector-meta-category" title={categoryLabel}>
              {categoryLabel}
            </span>
            <ConnectorCardToolsBadge connector={connector} toolsLoaded={toolsLoaded} />
          </div>
        </div>
        <div className="connector-card-actions">
          {flags.isConnected ? (
            <ConnectorDisconnectButton {...actionProps} onActivate={() => onDisconnect(connector.id)} />
          ) : (
            <ConnectorConnectButton {...actionProps} onActivate={() => onConnect(connector.id)} />
          )}
          {flags.isAuthorizationPending ? (
            <ConnectorCancelAuthorizationButton onActivate={() => onCancelAuthorization(connector.id)} />
          ) : null}
          <ConnectorStatusPill status={connector.status} />
        </div>
      </div>
      <ConnectorCardHints
        authorizationCancelFailed={authorizationCancelFailed}
        redirectUrl={flags.redirectUrl}
        cancelFailedMessage={cancelFailedMessage}
        continueInBrowserLabel={continueInBrowserLabel}
        onOpenExternalUrl={onOpenExternalUrl}
      />
    </article>
  );
}

