}

function ConnectorDrawerFoot({ connectorId, flags, onConnect, onCancelAuthorization, agentHandle }: ConnectorDrawerFootProps) {
  const t = useT();
  const { isAuthorizationPending } = flags;
  const isBusy = flags.isConnecting || isAuthorizationPending;
  return (
    <footer className="connector-drawer-foot">
      <button
        type="button"
        className={`primary connector-action is-connect${isBusy ? ' is-loading' : ''}`}
        disabled={!flags.canConnect}
        aria-busy={isBusy || undefined}
        onClick={() => onConnect(connectorId)}
        {...agentHandleProps({}, { base: agentHandle, action: 'connect', role: 'button', label: t('Connect') })}
      >
        {isBusy ? <Icon name="spinner" size={12} /> : null}
        <span>{isAuthorizationPending ? t('Authorization pending') : t('Connect')}</span>
      </button>
      {isAuthorizationPending ? (
        <button
          type="button"
          className="ghost connector-action is-cancel-authorization"
          onClick={() => onCancelAuthorization(connectorId)}
          {...agentHandleProps({}, { base: agentHandle, action: 'cancel-authorization', role: 'button', label: t('Cancel authorization') })}
        >
          <span>{t('Cancel authorization')}</span>
        </button>
      ) : null}
    </footer>
  );
}

/** Escape-to-close, initial focus on the close button, and body-scroll lock for the drawer's lifetime. */
function useDrawerModalBehavior({
  onClose,
  closeBtnRef,
}: {
  onClose: () => void;
  closeBtnRef: RefObject<HTMLButtonElement | null>;
}) {
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape') {
        e.stopPropagation();
        onClose();
      }
    }
    document.addEventListener('keydown', onKey);
    closeBtnRef.current?.focus();
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = previousOverflow;
    };
  }, [onClose]);
}

/**
 * Modal detail drawer with a paginated tool list. Keeps its own
 * escape-key-to-close and body-scroll-lock behavior inline (standard modal
 * a11y idioms, not business/transport logic) — see
 * `packages/ui/source-map.md`'s purity-check note for why these two
 * `document`/`window` touches were kept here rather than routed through
 * `dependencies.ts`.
 */
export function ConnectorDetailDrawer({
  connector,
  disabled,
  pendingAction,
  authorizationPending,
  authorizationCancelFailed,
  authorizationError,
  toolsPreviewLoading,
  toolsLoaded,
  onClose,
  onConnect,
  onDisconnect,
  onCancelAuthorization,
  onLoadMoreTools,
  onOpenExternalUrl,
  getCategoryLabel = (category) => category,
  getDisplayableAccountLabel = getDisplayableConnectorAccountLabel,
  cancelFailedMessage,
  continueInBrowserLabel,
  agentHandle,
}: ConnectorDetailDrawerProps) {
  const t = useT();
  const flags = connectorActionFlags({ connector, pendingAction, authorizationPending, disabled });
  const closeBtnRef = useRef<HTMLButtonElement | null>(null);
  const categoryLabel = getCategoryLabel(connector.category);
  useDrawerModalBehavior({ onClose, closeBtnRef });

  return (
    <div
      className="connector-drawer-backdrop"
      role="presentation"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <aside
        className="connector-drawer"
        role="dialog"
        aria-modal="true"
        aria-labelledby="connector-drawer-title"
        data-testid="connector-drawer"
        onClick={(e) => e.stopPropagation()}
        {...agentHandleProps({}, { base: agentHandle, role: 'region', label: connector.name })}
      >
        <ConnectorDrawerHead
          connector={connector}
          categoryLabel={categoryLabel}
          isAuthorizationPending={flags.isAuthorizationPending}
          toolsLoaded={toolsLoaded}
          closeBtnRef={closeBtnRef}
          onClose={onClose}
          agentHandle={agentHandle}
        />

        <div className="connector-drawer-body">
          {connector.description ? (
            <ConnectorDrawerAbout
              description={connector.description}
              isAuthorizationPending={flags.isAuthorizationPending}
              redirectUrl={flags.redirectUrl}
              continueInBrowserLabel={continueInBrowserLabel}
              onOpenExternalUrl={onOpenExternalUrl}
            />
          ) : null}
          {authorizationError ? <ConnectorDrawerAlert message={authorizationError} /> : null}
          {authorizationCancelFailed ? (
            <ConnectorDrawerAlert message={cancelFailedMessage ?? t("Couldn't cancel authorization. Try again.")} />
          ) : null}

          <ConnectorDrawerDetails
            connector={connector}
            categoryLabel={categoryLabel}
            accountLabel={getDisplayableAccountLabel(connector)}
            flags={flags}
            onDisconnect={onDisconnect}
            agentHandle={agentHandle}
          />

          <section className="connector-drawer-section">
            <h3 className="connector-drawer-section-title">
              {t('Tools')} <span className="connector-drawer-count">{getConnectorDisplayToolCount(connector)}</span>
            </h3>
            <ConnectorDrawerToolsBody
              connector={connector}
              toolsPreviewLoading={toolsPreviewLoading}
              toolsLoaded={toolsLoaded}
              onLoadMoreTools={onLoadMoreTools}
            />
          </section>
        </div>

        {!flags.isConnected ? (
          <ConnectorDrawerFoot
            connectorId={connector.id}
            flags={flags}
            onConnect={onConnect}
            onCancelAuthorization={onCancelAuthorization}
            agentHandle={agentHandle}
          />
        ) : null}
      </aside>
    </div>
  );
}

import { useEffect, type CSSProperties, type ReactNode } from 'react';
import { agentHandleProps, agentSubHandle } from '@jini-ai/agentic';
import { useT } from '../../../i18n/index.js';
import { DEFAULT_AGENT_CLI_ENV_FIELDS } from '../../constants.js';
import type { ExecutionPort } from '../../ports.js';
import {
  groupPresets,
  isProviderConfigured,
  nextConfigForAgentCliEnvChange,
  nextConfigForAgentModel,
  nextConfigForAgentReasoning,
  nextConfigForAgentSelect,
  nextConfigForModeChange,
  nextConfigForPresetSelect,
  resolveSelectedPreset,
  selectedAgentModel,
} from '../../rules.js';
import type {
  AgentCliEnvFieldSpec,
  DetectedAgent,
  ExecutionConfig,
  ExecutionMode,
  ProviderPreset,
} from '../../types.js';
import { useExecutionTab } from '../hooks/useExecutionTab.js';
import { ByokProviderForm } from './ByokProviderForm.js';
import { LocalCliAgentList } from './LocalCliAgentList.js';
import { ProviderChipGroup } from './ProviderChipGroup.js';

export interface ExecutionTabProps {
  config: ExecutionConfig;
  onConfigChange: (config: ExecutionConfig) => void;
  port: ExecutionPort;
  /** Host-owned endpoint catalog. Omitted means manual endpoint entry. */
  presets?: readonly ProviderPreset[];
  /** Per-agent CLI env-var catalog (proxy URLs, custom config dirs, a
   *  binary-path override). Defaults to this package's starter set for the
   *  CLIs it already knows about — a host with a different/larger agent
   *  roster passes its own, same convention as `presets`. */
  cliEnvFields?: readonly AgentCliEnvFieldSpec[];
  /** Disables Local CLI with an explanatory title, for hosts that cannot run
   *  local subprocesses (e.g. a hosted deployment). */
  localCliUnavailableReason?: string;
  /** Rendered in each agent card's icon slot — vendor marks are the host's to
   *  supply, since this package ships no logo set. */
  renderAgentIcon?: (agent: DetectedAgent) => ReactNode;
  /** Where local-CLI detection actually runs, in the host's words. See
   *  `LocalCliAgentListProps.scopeLabel` — a hosted deployment must not tell
   *  the operator these are the CLIs "on this machine". */
  localCliScopeLabel?: string;
  autoDetect?: boolean;
  ariaLabel?: string;
  /**
   * Pass-throughs to the internal `ByokProviderForm`'s identically-named props — see that
   * component's own doc comments for the full contract (write-only credential display, the
   * placeholder-never-a-value safety property, and the footer slot).
   *
   * Added here rather than only on `ByokProviderForm` because a host whose BYOK config is
   * ALSO offering Local CLI (the common case — see `types.ts`'s `ExecutionMode`) has no way to
   * reach `ByokProviderForm` directly: it is `ExecutionTab` that owns the mode switch and
   * renders the BYOK section conditionally. Without these, a host storing its admin's own key
   * server-side (as opposed to the visitor-key screen, which renders `ByokProviderForm` on its
   * own because it has no Local CLI option to switch away from) would have to fork this
   * component to add write-only display — exactly the mistake one host integration already made
   * and reverted. Omitted by every existing caller, so the rendered output is byte-identical
   * without them.
   */
  apiKeyFooter?: ReactNode;
  formFooter?: ReactNode;
  apiKeyStoredExternally?: boolean;
  apiKeyPlaceholder?: string;
  /**
   * Whether the tab may run model discovery right now. Defaults to `true`.
   *
   * For a host that holds a key the browser cannot read and knows that key cannot be used at the
   * selected endpoint, e.g. a key its backend saved for another provider and refuses to send anywhere
   * else. With nothing typed, discovery then has nothing it may send, so the tab stays idle instead of
   * showing that refusal.
   *
   * Read when discovery would run anyway (an endpoint change, a key typed or cleared, Test connection)
   * and deliberately NOT a trigger of its own. A host flips it to `true` when its stored key is
   * re-pointed at the selected endpoint, and probing on that flip alone would send the key there
   * without the operator asking. Turning it `false` only resets discovery to idle and discards any
   * response still in flight, which sends nothing.
   */
  canDiscoverModels?: boolean;
  /** Pass-through to `useExecutionTab`'s `describeProbeError` — see that option's doc. Words a failed
   *  model discovery and a failed Test connection. */
  describeProbeError?: (error: unknown) => string;
  /**
   * This tab's own agent handle, published by the host. Every interactive control below — the mode
   * switch, every provider chip, the whole BYOK card, and every detected-CLI card — derives its own
   * `data-agent-*` handle from this ONE base via `agentHandleProps`/`agentSubHandle`. Omit and no
   * `data-agent-*` markup is emitted anywhere in this tab — additive, never a behavior change.
   */
  agentHandle?: string;
}

/**
 * "Execution mode" — the Local CLI ↔ bring-your-own-key switch, its provider
 * and gateway chip rows, and the BYOK credential form.
 *
 * Controlled: the host owns `config` and persists it however it likes (in the
 * canary host that is a settings ledger). The tab owns only the async edges,
 * via `ExecutionPort`.
 *
 * Origin: `SettingsDialog.tsx` lines 4080-5336. The origin's managed-runtime
 * wallet — balance polling, top-up, sign-in coachmarks — is deliberately not
 * ported; it is product-bound, not generic.
 */
export function ExecutionTab({
  config,
  onConfigChange,
  port,
  presets = [],
  cliEnvFields = DEFAULT_AGENT_CLI_ENV_FIELDS,
  localCliUnavailableReason,
  renderAgentIcon,
  localCliScopeLabel,
  autoDetect = true,
  ariaLabel,
  apiKeyFooter,
  formFooter,
  apiKeyStoredExternally,
  apiKeyPlaceholder,
  canDiscoverModels = true,
  describeProbeError,
  agentHandle,
}: ExecutionTabProps) {
  const t = useT();
  const tab = useExecutionTab({
    port,
    autoDetect: autoDetect && config.mode === 'local-cli',
    ...(describeProbeError ? { describeProbeError } : {}),
  });
  const { loadModels, resetModelDiscovery } = tab;

  const selectedPreset = resolveSelectedPreset(presets, config.byok);

  /**
   * Whether a key EXISTS, never what it is. Keyed on the boolean specifically so the effect below
   * re-runs exactly once on the `false -> true` transition — a saved key hydrating from storage
   * after first paint, or an operator finishing entry — and NOT once per character, which is what
   * keying on `apiKey` itself would have done.
   */
  const hasApiKey = config.byok.apiKey.trim().length > 0;

  // Re-discover models whenever the selected endpoint changes (preset pick,
  // manual protocol switch, or a typed base URL settling on a new value), and
  // once a key first becomes available (`hasApiKey`).
  //
  // Still deliberately NOT keyed on `apiKey`'s VALUE or on `model` — refetching
  // on every keystroke would spam the provider (and this catalog's own
  // discovery has been observed tripping Gemini's per-minute "Model operations"
  // rate limit, which then presents as an ordinary discovery failure).
  //
  // `hasApiKey` is what makes this effect self-healing. Before it, a discovery
  // attempt that ran before any key existed left its error on screen forever —
  // typing or saving a key changes none of `protocol`/`baseUrl`/`providerId`,
  // so nothing re-triggered it, and the Model field silently fell back to the
  // preset's short static `preferredModels` list while the operator's key could
  // actually see far more. Reported live: the field defaulted to a stale
  // `gemini-2.5-flash` even though `Test Key` — the one control that did force
  // a fresh attempt, see `ByokProviderForm`'s `onTestConnection` below —
  // returned 42 models.
  //
  // `canDiscoverModels` is read here but is deliberately not a dependency — see that prop's doc for why
  // its turning `true` on its own must never probe.
  useEffect(() => {
    if (config.mode !== 'byok' || typeof port.listModels !== 'function' || !canDiscoverModels) return;
    loadModels(config.byok);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.mode, port, loadModels, config.byok.protocol, config.byok.baseUrl, config.byok.providerId, hasApiKey]);

  // All a turn to "cannot discover" does: drop the current result and any response still in flight —
  // e.g. one started before the host learned that its stored key belongs to another endpoint.
  useEffect(() => {
    if (!canDiscoverModels) resetModelDiscovery();
  }, [canDiscoverModels, resetModelDiscovery]);
  // No "local-cli while unavailable" guard here: `ExecutionModeSwitch` renders that tab `disabled`
  // whenever `localCliUnavailableReason` is set, and React never dispatches `onClick` for a disabled
  // button, so `setMode('local-cli')` cannot be reached in that state.
  const setMode = (mode: ExecutionMode) => {
    onConfigChange(nextConfigForModeChange(config, mode));
  };

  const modes: ReadonlyArray<{ id: ExecutionMode; title: string; meta: string }> = [
    { id: 'local-cli', title: t('Local CLI'), meta: t('Run an agent installed on this machine') },
    { id: 'byok', title: t('BYOK'), meta: t('Use your own API credentials') },
  ];

  return (
    <div className="jini-settings-execution" aria-label={ariaLabel ?? t('Execution mode')}>
      <ExecutionModeSwitch
        modes={modes}
        activeMode={config.mode}
        localCliUnavailableReason={localCliUnavailableReason}
        onSelect={setMode}
        agentHandle={agentHandle}
      />

      {config.mode === 'local-cli' ? (
        <LocalCliPane
          config={config}
          onConfigChange={onConfigChange}
          tab={tab}
          cliEnvFields={cliEnvFields}
          renderAgentIcon={renderAgentIcon}
          localCliScopeLabel={localCliScopeLabel}
          agentHandle={agentHandle}
        />
      ) : (
        <ByokPane
          config={config}
          onConfigChange={onConfigChange}
          presets={presets}
          selectedPreset={selectedPreset}
          tab={tab}
          canDiscoverModels={canDiscoverModels}
          canListModels={typeof port.listModels === 'function'}
          formProps={{ apiKeyFooter, formFooter, apiKeyStoredExternally, apiKeyPlaceholder }}
          agentHandle={agentHandle}
        />
      )}
    </div>
  );
}

/** The Local CLI ↔ BYOK segmented control. Local CLI is disabled, with the host's reason as its
 *  tooltip and caption, while the host says it is unavailable. */
function ExecutionModeSwitch({ modes, activeMode, localCliUnavailableReason, onSelect, agentHandle }: {
  modes: ReadonlyArray<{ id: ExecutionMode; title: string; meta: string }>;
  activeMode: ExecutionMode;
  localCliUnavailableReason: string | undefined;
  onSelect: (mode: ExecutionMode) => void;
  agentHandle: string | undefined;
}) {
  const t = useT();
  const localCliDisabled = Boolean(localCliUnavailableReason);
  return (
    <div
      className="jini-seg-control"
      role="tablist"
      aria-label={t('Execution mode')}
      style={{ '--seg-cols': modes.length } as CSSProperties}
    >
      {modes.map((mode) => {
        const disabled = mode.id === 'local-cli' && localCliDisabled;
        return (
          <button
            key={mode.id}
            type="button"
            role="tab"
            aria-selected={activeMode === mode.id}
            disabled={disabled}
            title={disabled ? localCliUnavailableReason : undefined}
            className={'jini-seg-btn' + (activeMode === mode.id ? ' active' : '')}
            onClick={() => onSelect(mode.id)}
            {...agentHandleProps({}, { base: agentHandle, ...({ action: `mode-${mode.id}`, role: 'button', label: mode.title }) })}
          >
            <span className="jini-seg-title">{mode.title}</span>
            <span className="jini-seg-meta">
              {disabled ? localCliUnavailableReason : mode.meta}
            </span>
          </button>
        );
      })}
    </div>
  );
}

/** The BYOK half of the tab: protocol and gateway chip rows over the credential card. */
function ByokPane({
  config, onConfigChange, presets, selectedPreset, tab, canDiscoverModels, canListModels, formProps, agentHandle,
}: {
  config: ExecutionConfig;
  onConfigChange: (config: ExecutionConfig) => void;
  presets: readonly ProviderPreset[];
  selectedPreset: ProviderPreset | null;
  tab: ReturnType<typeof useExecutionTab>;
  canDiscoverModels: boolean;
  canListModels: boolean;
  formProps: {
    apiKeyFooter: ReactNode;
    formFooter: ReactNode;
    apiKeyStoredExternally: boolean | undefined;
    apiKeyPlaceholder: string | undefined;
  };
  agentHandle: string | undefined;
}) {
  const t = useT();
  const { protocols, gateways } = groupPresets(presets);
  const configuredPresetIds = new Set(
    presets.filter((preset) => isProviderConfigured(config.byok, preset)).map((preset) => preset.id),
  );
  const selectPreset = (preset: ProviderPreset) =>
    onConfigChange({ ...config, byok: nextConfigForPresetSelect(config.byok, preset) });
  const selectedPresetId = selectedPreset?.id ?? null;
  return (
    <section className="jini-settings-section jini-settings-byok">
      <ProviderChipGroup
        label={t('Protocols')}
        presets={protocols}
        selectedPresetId={selectedPresetId}
        configuredPresetIds={configuredPresetIds}
        onSelect={selectPreset}
        configuredLabel={t('Configured')}
        unsetLabel={t('Not configured')}
        {...subHandleProps(agentHandle, 'protocol')}
      />
      <ProviderChipGroup
        label={t('Gateways')}
        presets={gateways}
        selectedPresetId={selectedPresetId}
        configuredPresetIds={configuredPresetIds}
        onSelect={selectPreset}
        configuredLabel={t('Configured')}
        unsetLabel={t('Not configured')}
        {...subHandleProps(agentHandle, 'gateway')}
      />
      <ByokProviderForm
        config={config.byok}
        onConfigChange={(byok) => onConfigChange({ ...config, byok })}
        preset={selectedPreset}
        {...subHandleProps(agentHandle, 'byok')}
        // The WHOLE catalog, not the `protocols`/`gateways` halves the chip rows take: the card
        // only reads it to recognise a pasted key as some other row's, and a key pasted from a
        // gateway into a protocol field is exactly the mistake worth naming.
        presets={presets}
        modelDiscovery={tab.modelDiscovery}
        connectionTest={tab.connectionTest}
        // Also re-runs discovery with the CURRENT byok config, not just the
        // connectivity probe — see this file's model-discovery effect above
        // for why that matters: a stale "could not load live models" error
        // from before this key existed (or from any earlier transient
        // failure) would otherwise never clear, even once Test Connection
        // itself goes green with the same config.
        onTestConnection={() => {
          tab.testConnection(config.byok);
          if (canDiscoverModels && canListModels) tab.loadModels(config.byok);
        }}
        {...(formProps.apiKeyFooter !== undefined ? { apiKeyFooter: formProps.apiKeyFooter } : {})}
        {...(formProps.formFooter !== undefined ? { formFooter: formProps.formFooter } : {})}
        {...(formProps.apiKeyStoredExternally !== undefined ? { apiKeyStoredExternally: formProps.apiKeyStoredExternally } : {})}
        {...(formProps.apiKeyPlaceholder !== undefined ? { apiKeyPlaceholder: formProps.apiKeyPlaceholder } : {})}
      />
    </section>
  );
}

/** The Local CLI half of the tab: detected agents, wired to the config's next-state rules. */
function LocalCliPane({ config, onConfigChange, tab, cliEnvFields, renderAgentIcon, localCliScopeLabel, agentHandle }: {
  config: ExecutionConfig;
  onConfigChange: (config: ExecutionConfig) => void;
  tab: ReturnType<typeof useExecutionTab>;
  cliEnvFields: readonly AgentCliEnvFieldSpec[];
  renderAgentIcon: ExecutionTabProps['renderAgentIcon'];
  localCliScopeLabel: ExecutionTabProps['localCliScopeLabel'];
  agentHandle: string | undefined;
}) {
  return (
    <LocalCliAgentList
      agents={tab.agents}
      config={config.localCli}
      scan={tab.scan}
      agentTest={tab.agentTest}
      onSelect={(agentId) => onConfigChange(nextConfigForAgentSelect(config, agentId))}
      onModelChange={(agentId, model) =>
        onConfigChange(nextConfigForAgentModel(config, agentId, model))
      }
      onReasoningChange={(agentId, reasoning) =>
        onConfigChange(nextConfigForAgentReasoning(config, agentId, reasoning))
      }
      onEnvChange={(agentId, envKey, value) =>
        onConfigChange(nextConfigForAgentCliEnvChange(config, agentId, envKey, value))
      }
      cliEnvFields={cliEnvFields}
      onRescan={tab.canRescan ? tab.rescan : undefined}
      onTest={
        tab.canTestAgent
          ? (agent) => tab.testAgent(agent.id, selectedAgentModel(config.localCli, agent) || undefined)
          : undefined
      }
      renderAgentIcon={renderAgentIcon}
      scopeLabel={localCliScopeLabel}
      {...subHandleProps(agentHandle, 'local-cli')}
    />
  );
}

/** `{ agentHandle }` for a child's sub-handle under this tab's base, or nothing when no base is set. */
function subHandleProps(agentHandle: string | undefined, action: string): { agentHandle?: string } {
  return agentHandle ? { agentHandle: agentSubHandle({ base: agentHandle, action }) } : {};
}

import type { ReactNode } from 'react';
import { Icon } from '../../../../react/components/Icon.js';
import { Lightbox } from '../../../admin-widgets/components/Lightbox/Lightbox.js';
import { useT } from '../../../i18n/index.js';
import type { TranslationVars } from '../../../i18n/index.js';
import { FILE_DROPZONE_FONT_PANGRAM, FILE_DROPZONE_FONT_SPECIMEN, FILE_DROPZONE_GLYPH_ICON } from '../../constants.js';
import { fileDropzoneExtensionLabel, fileDropzoneKind, fileDropzoneSizeLabel } from '../../rules.js';
import type { FileDropzoneKind, FileDropzonePreviewState } from '../../types.js';

export interface FileDropzoneLightboxProps {
  file: File;
  previews: FileDropzonePreviewState;
  onClose: () => void;
}

type Translate = (key: string, vars?: TranslationVars) => string;

interface StageInput {
  t: Translate;
  file: File;
  previews: FileDropzonePreviewState;
}

type StageRenderer = (input: StageInput) => ReactNode;

/** Renders `render(url)` once the file's object URL has resolved, `null` (→ fallback card) until then. */
function withUrl(render: (url: string, file: File) => ReactNode): StageRenderer {
  return ({ file, previews }) => {
    const url = previews.previewUrls.get(file);
    return url ? render(url, file) : null;
  };
}

/**
 * Per-kind stage renderers. Each returns `null` while its preview source is
 * not available yet (no object URL, no loaded font family, no text snippet),
 * so `renderStage` shows the name/size fallback card. Kinds with no entry
 * (slides/other) always render the fallback card.
 */
const STAGE_RENDERERS: Partial<Record<FileDropzoneKind, StageRenderer>> = {
  image: withUrl((url, file) => <img src={url} alt={file.name} className="jini-file-dropzone__lightbox-img" />),
  video: withUrl((url) => <video src={url} className="jini-file-dropzone__lightbox-video" controls autoPlay playsInline />),
  audio: withUrl((url) => (
    <div className="jini-file-dropzone__lightbox-audio">
      <span className="jini-file-dropzone__lightbox-audio-icon">
        <Icon name="volume" size={34} />
      </span>
      <audio src={url} controls className="jini-file-dropzone__lightbox-audio-player" />
    </div>
  )),
  pdf: withUrl((url, file) => <iframe src={url} className="jini-file-dropzone__lightbox-frame" title={file.name} />),
  html: withUrl((url, file) => (
    <iframe
      src={url}
      className="jini-file-dropzone__lightbox-frame"
      title={file.name}
      sandbox="allow-scripts allow-popups"
    />
  )),
  font: ({ file, previews }) => {
    const family = previews.fontFamilies.get(file);
    if (!family) return null;
    return (
      <div className="jini-file-dropzone__lightbox-font" style={{ fontFamily: `'${family}'` }}>
        <div className="jini-file-dropzone__lightbox-font-hero">{FILE_DROPZONE_FONT_SPECIMEN}Bb Cc</div>
        <div className="jini-file-dropzone__lightbox-font-pangram">{FILE_DROPZONE_FONT_PANGRAM}</div>
        <div className="jini-file-dropzone__lightbox-font-scale">
          <span style={{ fontSize: 13 }}>{FILE_DROPZONE_FONT_PANGRAM}</span>
          <span style={{ fontSize: 18 }}>{FILE_DROPZONE_FONT_PANGRAM}</span>
          <span style={{ fontSize: 26 }}>{FILE_DROPZONE_FONT_PANGRAM}</span>
        </div>
      </div>
    );
  },
  text: ({ t, file, previews }) => {
    const snippet = previews.textSnippets.get(file);
    return snippet != null ? <pre className="jini-file-dropzone__lightbox-text">{snippet || t('(empty file)')}</pre> : null;
  },
};

function renderFallback({ t, file, kind }: { t: Translate; file: File; kind: FileDropzoneKind }) {
  return (
    <div className="jini-file-dropzone__lightbox-fallback">
      <span className="jini-file-dropzone__lightbox-fallback-glyph" data-kind={kind}>
        <Icon name={FILE_DROPZONE_GLYPH_ICON[kind]} size={40} />
      </span>
      <p className="jini-file-dropzone__lightbox-fallback-name">{file.name}</p>
      <p className="jini-file-dropzone__lightbox-fallback-meta">
        {fileDropzoneExtensionLabel(file)} · {fileDropzoneSizeLabel(file.size) || '—'}
      </p>
      <p className="jini-file-dropzone__lightbox-fallback-hint">{t('No inline preview for this file type.')}</p>
    </div>
  );
}

function renderStage({ t, file, kind, previews }: StageInput & { kind: FileDropzoneKind }) {
  return STAGE_RENDERERS[kind]?.({ t, file, previews }) ?? renderFallback({ t, file, kind });
}

/** Click-to-enlarge, kind-aware preview for one staged file — image, PDF embed, HTML mini-render, video/audio player, font specimen, or a text snippet, with a name/size fallback card for everything else. Rendered in the shared `Lightbox` (a top-layer native dialog, so no portal is needed). Ported from `DesignSystemAssetDropzone.tsx`'s lightbox. */
export function FileDropzoneLightbox({ file, previews, onClose }: FileDropzoneLightboxProps) {
  const t = useT();
  const kind = fileDropzoneKind(file);
  return (
    <Lightbox
      open
      title={file.name}
      onClose={onClose}
      className="jini-file-dropzone__lightbox"
      labels={{ close: t('Close preview') }}
      actions={<span className="jini-file-dropzone__lightbox-meta">{fileDropzoneSizeLabel(file.size)}</span>}
    >
      <div className="jini-file-dropzone__lightbox-stage" data-kind={kind}>
        {renderStage({ t, file, kind, previews })}
      </div>
    </Lightbox>
  );
}

import type { ReactNode } from 'react';
import { Icon } from '../../../../react/components/Icon.js';
import { useT } from '../../../i18n/index.js';
import { FILE_DROPZONE_FONT_SPECIMEN, FILE_DROPZONE_GLYPH_ICON, FILE_DROPZONE_TEXT_THUMB_CHARS } from '../../constants.js';
import { fileDropzoneExtensionLabel, fileDropzoneKind, fileDropzoneStagingKey } from '../../rules.js';
import type { FileDropzoneKind, FileDropzonePreviewState } from '../../types.js';

export interface FileDropzoneThumbnailGridProps {
  files: readonly File[];
  previews: FileDropzonePreviewState;
  onSelect: (file: File) => void;
  onRemove?: ((file: File) => void) | undefined;
}

function renderGlyph({ file, kind }: { file: File; kind: FileDropzoneKind }) {
  return (
    <span className="jini-file-dropzone__glyph" data-kind={kind}>
      <Icon name={FILE_DROPZONE_GLYPH_ICON[kind]} size={20} />
      <span className="jini-file-dropzone__glyph-ext">{fileDropzoneExtensionLabel(file)}</span>
    </span>
  );
}

type ThumbRenderer = (input: { file: File; previews: FileDropzonePreviewState }) => ReactNode;

/**
 * Per-kind thumbnail renderers. Each returns `null` while its preview source
 * (object URL, loaded font family, non-blank text snippet) is not available
 * yet, so `renderThumb` falls back to the extension glyph. Kinds with no entry
 * (pdf/audio/slides/other) always render the glyph.
 */
const THUMB_RENDERERS: Partial<Record<FileDropzoneKind, ThumbRenderer>> = {
  image: ({ file, previews }) => {
    const url = previews.previewUrls.get(file);
    return url ? <img src={url} alt="" className="jini-file-dropzone__thumb" loading="lazy" /> : null;
  },
  video: ({ file, previews }) => {
    const url = previews.previewUrls.get(file);
    return url ? (
      <video className="jini-file-dropzone__thumb" src={url} muted playsInline preload="metadata" tabIndex={-1} />
    ) : null;
  },
  font: ({ file, previews }) => {
    const family = previews.fontFamilies.get(file);
    return family ? (
      <span className="jini-file-dropzone__font-thumb" style={{ fontFamily: `'${family}'` }} aria-hidden>
        {FILE_DROPZONE_FONT_SPECIMEN}
      </span>
    ) : null;
  },
  html: ({ file, previews }) => {
    const url = previews.previewUrls.get(file);
    return url ? (
      <span className="jini-file-dropzone__frame-thumb" aria-hidden>
        <iframe className="jini-file-dropzone__html-thumb" src={url} title="" sandbox="" tabIndex={-1} />
      </span>
    ) : null;
  },
  text: ({ file, previews }) => {
    const snippet = previews.textSnippets.get(file);
    return snippet?.trim() ? (
      <span className="jini-file-dropzone__text-thumb" aria-hidden>
        {snippet.slice(0, FILE_DROPZONE_TEXT_THUMB_CHARS)}
      </span>
    ) : null;
  },
};

function renderThumb({ file, kind, previews }: { file: File; kind: FileDropzoneKind; previews: FileDropzonePreviewState }) {
  return THUMB_RENDERERS[kind]?.({ file, previews }) ?? renderGlyph({ file, kind });
}

/** Kind-aware thumbnail grid over staged files, with remove tiles and click-to-select (the host renders the lightbox — see `FileDropzoneLightbox`). Ported from `DesignSystemAssetDropzone.tsx`'s staged-asset grid. */
export function FileDropzoneThumbnailGrid({ files, previews, onSelect, onRemove }: FileDropzoneThumbnailGridProps) {
  const t = useT();
  if (files.length === 0) return null;
  return (
    <ul className="jini-file-dropzone__grid" aria-label={t('Staged files')}>
      {files.map((file) => {
        const kind = fileDropzoneKind(file);
        return (
          <li key={fileDropzoneStagingKey(file)} className="jini-file-dropzone__tile">
            <button
              type="button"
              className="jini-file-dropzone__tile-main"
              onClick={() => onSelect(file)}
              title={file.name}
            >
              {renderThumb({ file, kind, previews })}
            </button>
            {onRemove ? (
              <button
                type="button"
                className="jini-file-dropzone__remove"
                aria-label={t('Remove {name}', { name: file.name })}
                onClick={() => onRemove(file)}
              >
                <Icon name="close" size={12} />
              </button>
            ) : null}
            <span className="jini-file-dropzone__caption" title={file.name}>
              {file.name}
            </span>
          </li>
        );
      })}
    </ul>
  );
}

import {
  forwardRef,
  useLayoutEffect,
  useRef,
  useSyncExternalStore,
} from 'react';
import { useIframeKeepAlivePool } from '../hooks/useIframeKeepAlivePool.js';
import { setForwardedRef, syncIframeProps, type PooledIframeProps } from '../dom-sync.js';

const subscribeToNoopStore = () => () => {};
const getClientSnapshot = () => false;
const getServerSnapshot = () => true;

/**
 * Which attributes/style keys are currently applied to a given pooled iframe,
 * tracked against the ELEMENT rather than the component.
 *
 * `syncIframeProps` removes a stale attribute by iterating the set it is handed.
 * That set used to be a `useRef` on the component — but the element is owned by
 * the pool, keyed by `cacheKey`, and deliberately SURVIVES unmount. So a remount
 * got a fresh empty set, the removal loop iterated nothing, and a `sandbox` or
 * `allow` applied by the previous mount stayed on the element while it was
 * reused for a different `src`. Security attributes silently persisting onto
 * different content is the whole hazard; keying the record to the element makes
 * the record live exactly as long as the thing it describes.
 *
 * A `WeakMap` so a genuinely evicted iframe's record is collected with it.
 */
const appliedByFrame = new WeakMap<HTMLIFrameElement, { attributes: Set<string>; styleKeys: Set<string> }>();

function appliedFor(frame: HTMLIFrameElement): { attributes: Set<string>; styleKeys: Set<string> } {
  let record = appliedByFrame.get(frame);
  if (!record) {
    record = { attributes: new Set<string>(), styleKeys: new Set<string>() };
    appliedByFrame.set(frame, record);
  }
  return record;
}

function useIsServerRender() {
  return useSyncExternalStore(subscribeToNoopStore, getClientSnapshot, getServerSnapshot);
}

/**
 * An `<iframe>` whose element is kept alive in the nearest
 * `IframeKeepAlivePoolProvider` (or a local single-entry fallback pool if
 * none is mounted) across unmount/remount under the same `cacheKey`,
 * instead of reloading. Renders a plain `<iframe>` during SSR, since the
 * pool is a client-only concept.
 */
export const PooledIframe = forwardRef<HTMLIFrameElement, PooledIframeProps>(function PooledIframe({
  cacheKey,
  src,
  ...props
}, forwardedRef) {
  const isServerRender = useIsServerRender();
  if (isServerRender) return <iframe {...props} src={src} />;
  return (
    <ClientPooledIframe
      ref={forwardedRef}
      cacheKey={cacheKey}
      src={src}
      {...props}
    />
  );
});

const ClientPooledIframe = forwardRef<HTMLIFrameElement, PooledIframeProps>(function ClientPooledIframe({
  cacheKey,
  src,
  ...props
}, forwardedRef) {
  const pool = useIframeKeepAlivePool();
  const hostRef = useRef<HTMLDivElement | null>(null);
  const iframeRef = useRef<HTMLIFrameElement | null>(null);
  const propsRef = useRef<PooledIframeProps>({ cacheKey, src, ...props });
  propsRef.current = { cacheKey, src, ...props };

  useLayoutEffect(() => {
    // `hostRef` attaches to the unconditionally-rendered `<span>` below during
    // the same commit, before any layout effect runs — it's always set here.
    const frame = pool.attach(cacheKey, hostRef.current!, () => document.createElement('iframe'));
    iframeRef.current = frame;
    return () => {
      setForwardedRef(forwardedRef, null);
      iframeRef.current = null;
      pool.release(cacheKey);
    };
  }, [cacheKey, pool, forwardedRef]);

  useLayoutEffect(() => {
    // The effect above always runs first (declared earlier in the same
    // component, same commit) and sets `iframeRef.current` before this one
    // ever runs, so it's always populated here.
    const frame = iframeRef.current!;
    // Keyed to the ELEMENT, not this component — see `appliedByFrame`.
    const applied = appliedFor(frame);
    syncIframeProps(frame, propsRef.current, applied.attributes, applied.styleKeys);
    setForwardedRef(forwardedRef, frame);
  });

  return <span ref={hostRef} className="pooled-iframe-host" />;
});

'use client';
import { formatErrorForLog } from '@jini-ai/core';

import { forwardRef, useImperativeHandle, useRef, type ForwardedRef } from 'react';
import { LexicalComposer } from '@lexical/react/LexicalComposer';
import type { InitialConfigType } from '@lexical/react/LexicalComposer';
import { PlainTextPlugin } from '@lexical/react/LexicalPlainTextPlugin';
import { ContentEditable } from '@lexical/react/LexicalContentEditable';
import { LexicalErrorBoundary } from '@lexical/react/LexicalErrorBoundary';
import { HistoryPlugin } from '@lexical/react/LexicalHistoryPlugin';
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { $getRoot, $getSelection, $isRangeSelection, type RangeSelection } from 'lexical';
import { DEFAULT_TEST_ID, DEFAULT_TRIGGERS, EDITOR_THEME } from '../../constants.js';
import { setRichTextFromPlainText } from '../../deserialize.js';
import { $createMentionNode, MentionNode } from '../../mention-node.js';
import {
  buildAnyTriggerDeletionRegex,
  buildTriggerDeletionRegex,
  deleteActiveTrigger,
} from '../../rules.js';
import { serializeRichText } from '../../serialize.js';
import type {
  MentionEntity,
  MentionInsert,
  PopoverNavigationKey,
  RichTextInputHandle,
  RichTextTriggerConfig,
  RichTextTriggerMatch,
} from '../../types.js';
import { useKeyboardCommands } from '../hooks/useKeyboardCommands.js';
import { useMentionAtomicNavigation } from '../hooks/useMentionAtomicNavigation.js';
import { useMentionColorStamping } from '../hooks/useMentionColorStamping.js';
import { usePasteFiles } from '../hooks/usePasteFiles.js';
import { useSeededValue } from '../hooks/useSeededValue.js';
import { useSyncedOnChange } from '../hooks/useSyncedOnChange.js';
import { useTriggerDetection } from '../hooks/useTriggerDetection.js';

const DEFAULT_MENTION_TRIGGER_ID = 'mention';

export interface RichTextInputProps {
  placeholder: string;
  /** Host-controlled value. Reseeded into the editor only when it changes
   *  for a reason other than the user's own typing — see `useSeededValue`. */
  value: string;
  /** Rendered as pills (via `setText`/seeding) and used to fold plain-text
   *  `@token`s into the reported mention list. */
  knownMentions: MentionEntity[];
  /** Fires on every real text change with the serialized plain text + the
   *  mentions currently referenced by it (atomic nodes + matched plain
   *  `@token`s). */
  onChange(text: string, mentions: MentionEntity[]): void;
  /** The trigger (if any) active at the caret, e.g. to drive a popover. */
  onTriggerChange(match: RichTextTriggerMatch | null): void;
  /** Plain Enter with no popover open and no IME composition in progress. */
  onSubmit(): void;
  /** Pasted files/images — omit to fall back to plain-text paste only. */
  onPasteFiles?: ((files: File[]) => void) | undefined;
  /** Whether a popover is open; gates the arrow/tab/enter/escape routing. */
  popoverOpen: boolean;
  /** Routes a popover key to the host; returns true when the host consumed it. */
  onPopoverKey(key: PopoverNavigationKey): boolean;
  /** Optional combobox a11y: announces the active row of a portaled listbox
   *  without moving DOM focus. */
  comboboxAria?: { activeId: string | null; expanded: boolean } | undefined;
  title?: string | undefined;
  testId?: string | undefined;
  /** `aria-controls` target — must match the host's portaled listbox id. */
  mentionListboxId?: string | undefined;
  namespace?: string | undefined;
  /** Which trigger characters are recognized at the caret. Defaults to an
   *  inline `@mention` + a line-start-anchored `/command`, matching the
   *  origin. Pass `[]` to disable trigger detection entirely. */
  triggers?: readonly RichTextTriggerConfig[] | undefined;
  /** Which `triggers` entry's character `insertMention` deletes before
   *  splicing in the picked mention node. Defaults to `'mention'`. */
  mentionTriggerId?: string | undefined;
  /** Resolves a per-mention color, applied as a CSS custom property on that
   *  mention's DOM element — see `useMentionColorStamping`. Omit for
   *  CSS-only (className-driven) mention styling. */
  resolveMentionColor?: ((mention: MentionEntity) => string | undefined) | undefined;
}

function EditorSurface(props: RichTextInputProps, ref: ForwardedRef<RichTextInputHandle>) {
  const {
    placeholder,
    value,
    knownMentions,
    onChange,
    onTriggerChange,
    onSubmit,
    onPasteFiles,
    popoverOpen,
    onPopoverKey,
    comboboxAria,
    title,
    testId = DEFAULT_TEST_ID,
    mentionListboxId = 'rich-text-mention-listbox',
    triggers = DEFAULT_TRIGGERS,
    mentionTriggerId = DEFAULT_MENTION_TRIGGER_ID,
    resolveMentionColor,
  } = props;

  const [editor] = useLexicalComposerContext();

  // `knownMentions`/`triggers`/`mentionTriggerId` can change between renders;
  // the imperative handle below is created once (stable identity, deps
  // `[editor]`) and always reads the latest values through these refs,
  // mirroring the origin's `knownEntitiesRef` pattern.
  const knownMentionsRef = useRef(knownMentions);
  knownMentionsRef.current = knownMentions;
  const triggersRef = useRef(triggers);
  triggersRef.current = triggers;
  const mentionTriggerIdRef = useRef(mentionTriggerId);
  mentionTriggerIdRef.current = mentionTriggerId;

  useSyncedOnChange(knownMentions, onChange);
  useTriggerDetection(triggers, onTriggerChange);
  useMentionAtomicNavigation();
  useKeyboardCommands(popoverOpen, onSubmit, onPopoverKey);
  usePasteFiles(onPasteFiles);
  useSeededValue(value, knownMentions);
  useMentionColorStamping(resolveMentionColor);

  useImperativeHandle(
    ref,
    (): RichTextInputHandle => ({
      getText() {
        // Belt-and-suspenders: collapse any stray \n\n the single-paragraph
        // model should never produce, so the wire format stays byte-stable.
        return serializeRichText(editor.getEditorState()).text.replace(/\n{2,}/g, '\n');
      },
      setText(text: string) {
        setRichTextFromPlainText(editor, text, knownMentionsRef.current);
      },
      clear() {
        setRichTextFromPlainText(editor, '', knownMentionsRef.current);
      },
      focus() {
        editor.focus();
      },
      insertText(text: string) {
        editor.update(
          () => {
            let sel = $getSelection();
            if (!$isRangeSelection(sel)) {
              $getRoot().selectEnd();
              sel = $getSelection();
            }
            if ($isRangeSelection(sel)) sel.insertText(text);
          },
          { discrete: true },
        );
      },
      insertMention(insert: MentionInsert) {
        const isActiveTrigger = (trigger: RichTextTriggerConfig) => trigger.id === mentionTriggerIdRef.current;
        editor.update(
          () => {
            let sel = $getSelection();
            if (!$isRangeSelection(sel)) {
              $getRoot().selectEnd();
              sel = $getSelection();
            }
            // `$getRoot().selectEnd()` always establishes a collapsed
            // RangeSelection — even an empty root selects at its own
            // boundary — so `sel` is guaranteed to be one by this point.
            // The cast documents that instead of an unreachable
            // early-return branch no real document state can trigger.
            const rangeSel = sel as RangeSelection;
            const mentionTrigger =
              triggersRef.current.find(isActiveTrigger) ??
              triggersRef.current[0];
            if (mentionTrigger) {
              deleteActiveTrigger(rangeSel, buildTriggerDeletionRegex(mentionTrigger));
            }
            const node = $createMentionNode({
              mentionId: insert.entity.id,
              mentionKind: insert.entity.kind,
              token: insert.token,
              label: insert.entity.label,
              title: insert.entity.title,
            });
            const active = $getSelection();
            if ($isRangeSelection(active)) {
              active.insertNodes([node]);
              const after = $getSelection();
              if ($isRangeSelection(after)) after.insertText(' ');
            }
          },
          { discrete: true },
        );
      },
      replaceActiveTrigger(text: string) {
        editor.update(
          () => {
            let sel = $getSelection();
            if (!$isRangeSelection(sel)) {
              $getRoot().selectEnd();
              sel = $getSelection();
            }
            // See the identical `selectEnd()` guarantee noted in
            // `insertMention` above.
            const rangeSel = sel as RangeSelection;
            // Drop whichever trigger's query is active, then insert the
            // plain text (e.g. a Tab-completed slash command's own text).
            deleteActiveTrigger(rangeSel, buildAnyTriggerDeletionRegex(triggersRef.current));
            const active = $getSelection();
            if ($isRangeSelection(active)) active.insertText(text);
          },
          { discrete: true },
        );
      },
    }),
    [editor],
  );

  return (
    <>
      <PlainTextPlugin
        contentEditable={
          <ContentEditable
            data-testid={testId}
            className="rich-text-input-editable"
            aria-placeholder={placeholder}
            title={title ?? placeholder}
            role="combobox"
            aria-expanded={comboboxAria?.expanded ? 'true' : 'false'}
            aria-controls={mentionListboxId}
            {...(comboboxAria?.activeId ? { 'aria-activedescendant': comboboxAria.activeId } : {})}
            placeholder={<div className="rich-text-input-placeholder">{placeholder}</div>}
          />
        }
        placeholder={<div className="rich-text-input-placeholder">{placeholder}</div>}
        ErrorBoundary={LexicalErrorBoundary}
      />
      <HistoryPlugin />
    </>
  );
}

const EditorSurfaceWithRef = forwardRef<RichTextInputHandle, RichTextInputProps>(EditorSurface);

/**
 * Origin: `apps/web/src/components/composer/LexicalComposerInput.tsx` (OD's
 * chat composer input). A plain-text Lexical editor (not a full block/marks
 * rich text editor) with atomic `@mention`/`/command` trigger tokens, a
 * single-paragraph model (Enter submits, Shift+Enter soft-breaks), and an
 * imperative handle mirroring a controlled `<textarea>`'s usual operations.
 *
 * The origin's `EditorRefPlugin` (a ref-bridging plugin needed because its
 * `forwardRef` component lived OUTSIDE the `LexicalComposer` context) is
 * dropped: `EditorSurface` above is itself inside that context, so its
 * `useImperativeHandle` reads `editor` directly from
 * `useLexicalComposerContext()`.
 */
export const RichTextInput = forwardRef<RichTextInputHandle, RichTextInputProps>(
  function RichTextInput(props, ref) {
    const initialConfig: InitialConfigType = {
      namespace: props.namespace ?? 'rich-text-input',
      editable: true,
      nodes: [MentionNode],
      theme: EDITOR_THEME,
      onError(err) {
        if (process.env.NODE_ENV !== 'production') {
          console.error('[rich-text-input]', formatErrorForLog({ error: err }));
        }
      },
      // editorState intentionally omitted → empty on first paint (SSR-safe).
    };

    return (
      <div className="rich-text-input">
        <LexicalComposer initialConfig={initialConfig}>
          <EditorSurfaceWithRef {...props} ref={ref} />
        </LexicalComposer>
      </div>
    );
  },
);

// Dumb "Advanced" modal: the raw MEMORY.md index editor plus the technical
// memory-tree view. Rendered into `modalHost` via a portal (a host resolves
// `document.body` and passes it, so this file stays DOM-free). All state +
// transport live in the entries hook; this is props-in / JSX-out.
import { createPortal } from 'react-dom';
import { Icon } from '../../../../react/components/Icon.js';
import { useT } from '../../../i18n/index.js';
import type { MemoryTreeNode } from '../../types.js';

export function MemoryAdvancedModal({
  open,
  modalHost,
  onClose,
  index,
  indexDraft,
  onIndexDraftChange,
  onSaveIndex,
  busy,
  memoryTree,
  treeFolders,
  treeChildren,
  onStartEdit,
}: {
  open: boolean;
  modalHost: HTMLElement | null;
  onClose: () => void;
  index: string;
  indexDraft: string | null;
  onIndexDraftChange: (value: string | null) => void;
  onSaveIndex: () => void;
  busy: boolean;
  memoryTree: MemoryTreeNode[];
  treeFolders: MemoryTreeNode[];
  treeChildren: Map<string, MemoryTreeNode[]>;
  onStartEdit: (id: string) => void;
}) {
  const t = useT();
  if (!open || !modalHost) return null;
  return createPortal(
    <div
      className="memory-action-modal-backdrop"
      role="presentation"
      // The dialog below stops propagation, so any mouse-down that reaches the
      // backdrop must have originated on the backdrop itself.
      onMouseDown={onClose}
    >
      <div
        className="memory-action-modal memory-action-modal--advanced"
        role="dialog"
        aria-modal="true"
        aria-labelledby="memory-advanced-modal-title"
        onMouseDown={(event) => event.stopPropagation()}
      >
        <div className="memory-action-modal-head">
          <div>
            <h3 id="memory-advanced-modal-title">{t('Advanced')}</h3>
            <p>{t('Inspect or edit the underlying memory index.')}</p>
          </div>
          <button type="button" className="memory-action-modal-close" onClick={onClose} aria-label={t('Close')} title={t('Close')}>
            <Icon name="close" size={16} />
          </button>
        </div>
        <div className="memory-action-modal-body memory-advanced-modal-body">
          <p className="memory-advanced-hint">{t('Inspect or edit the underlying memory index.')}</p>
          <div className="memory-advanced-stack">
            <details className="library-group memory-advanced-card">
              <summary className="memory-details-summary">
                <span className="memory-details-title">{t('MEMORY.md index')}</span>
              </summary>
              <textarea
                value={indexDraft ?? index}
                onChange={(e) => onIndexDraftChange(e.target.value)}
                rows={8}
                style={{
                  width: '100%',
                  marginTop: 8,
                  fontFamily: 'var(--jini-font-mono)',
                }}
              />
              <div
                style={{
                  display: 'flex',
                  gap: 8,
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  marginTop: 6,
                  flexWrap: 'wrap',
                }}
              >
                <span
                  className="hint"
                  style={{
                    fontSize: 11,
                    margin: 0,
                    color: indexDraft !== null ? 'var(--jini-warning)' : 'var(--jini-text-muted)',
                    fontWeight: indexDraft !== null ? 600 : 400,
                  }}
                >
                  {indexDraft !== null
                    ? `● ${t('Unsaved changes')} — ${t('Edits here change how memories are indexed.')}`
                    : t('Edits here change how memories are indexed.')}
                </span>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button type="button" className="ghost" onClick={() => onIndexDraftChange(null)} disabled={indexDraft === null}>
                    {t('Reset')}
                  </button>
                  <button type="button" className="primary" onClick={onSaveIndex} disabled={busy || indexDraft === null}>
                    {t('Save index')}
                  </button>
                </div>
              </div>
            </details>
            {treeFolders.length > 0 ? (
              <details className="library-group memory-advanced-card">
                <summary className="memory-details-summary">
                  <span className="memory-details-title">{t('Memory tree')}</span>
                  <span className="filter-pill-count">{memoryTree.length}</span>
                </summary>
                <p className="memory-advanced-hint">
                  {t('Technical view of the same saved memories. Most users only need the saved-memory list above.')}
                </p>
                <div className="memory-tree-advanced">
                  {treeFolders.map((folder) => {
                    const children = treeChildren.get(folder.id) ?? [];
                    return (
                      <div key={folder.id} className="library-card" style={{ alignItems: 'stretch' }}>
                        <div className="library-card-info" style={{ width: '100%' }}>
                          <div className="library-card-title-row">
                            <span className="library-card-name">{folder.name}</span>
                            <span className="library-card-badge">{folder.path}</span>
                          </div>
                          <div className="library-card-desc">
                            {children.length} {children.length === 1 ? t('node') : t('nodes')}
                          </div>
                          {children.length > 0 ? (
                            <ul
                              style={{
                                display: 'grid',
                                gap: 6,
                                margin: '8px 0 0',
                                padding: 0,
                                listStyle: 'none',
                              }}
                            >
                              {children.map((child) => (
                                <li key={child.id} className="memory-tree-child-row">
                                  <span style={{ minWidth: 0 }}>
                                    <span className="library-card-name">{child.name}</span>{' '}
                                    <span className="library-card-badge">{child.id}</span>
                                    {child.description ? (
                                      <span className="library-card-desc" style={{ display: 'block' }}>
                                        {child.description}
                                      </span>
                                    ) : null}
                                  </span>
                                  <div className="memory-card-actions">
                                    <button
                                      type="button"
                                      className="ghost library-card-action"
                                      onClick={() => onStartEdit(child.id)}
                                      title={t('Edit')}
                                    >
                                      <Icon name="edit" size={14} />
                                    </button>
                                  </div>
                                </li>
                              ))}
                            </ul>
                          ) : null}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </details>
            ) : null}
          </div>
        </div>
      </div>
    </div>,
    modalHost,
  );
}

// Minimal Markdown → safe HTML renderer for a saved memory entry's preview
// body. OD's real `runtime/markdown.tsx` (2,881 lines) is chat/artifact
// rendering territory, explicitly deferred to `@jini-ai/chat`'s `./react` subpath (formerly
// this package's own `./chat` export, extracted 2026-08-03)/this package's own `./renderers`
// subpath (see `packages/ui/source-map.md`) — this is a
// scoped-down local reimplementation covering just this slice's one need:
// render a memory body's GFM Markdown as read-only preview text. Built on
// `micromark`, already a real dependency of this package (see
// `src/utils/markdown-scroll-sync.ts`). `micromark` escapes raw HTML in the
// input by default (no `allowDangerousHtml`), so this is XSS-safe without
// an extra sanitizer pass.
import { micromark } from 'micromark';
import { gfm, gfmHtml } from 'micromark-extension-gfm';

export function renderMarkdown(body: string) {
  const html = micromark(body, {
    extensions: [gfm()],
    htmlExtensions: [gfmHtml()],
  });
  // eslint-disable-next-line react/no-danger -- `html` is micromark's own
  // escaped output (raw HTML in the source is neutralized, not passed
  // through), so this is not an unsanitized-input XSS risk.
  return <div className="memory-markdown-body" dangerouslySetInnerHTML={{ __html: html }} />;
}

import type { ReactNode } from 'react';
import { useT } from '../../../i18n/index.js';
import { useMentionAutocomplete } from '../hooks/useMentionAutocomplete.js';
import { MentionCategoryTabs } from './MentionCategoryTabs.js';
import { MentionResultsList } from './MentionResultsList.js';
import { SelectedMentionChips } from './SelectedMentionChips.js';
import type { MentionCategory, MentionItem } from '../../types.js';

export interface MentionAutocompleteProps<T extends MentionItem<ReactNode>> {
  value: string;
  onValueChange: (next: string) => void;
  items: T[];
  categories: MentionCategory[];
  onSelectionChange?: ((selected: T[]) => void) | undefined;
  triggerChar?: string | undefined;
  getSearchText?: ((item: T) => string) | undefined;
  maxResultsPerCategory?: number | undefined;
  placeholder?: string | undefined;
  rows?: number | undefined;
  disabled?: boolean | undefined;
  /** Rendered instead of an item's own icon while it's selected in the
   *  results list (typically a check icon). */
  selectedIcon?: ReactNode | undefined;
  /** Rendered at the end of every removable chip (typically a close icon). */
  chipRemoveIcon?: ReactNode | undefined;
  /** Plain-English placeholder shown in the results panel while the query
   *  is empty (before the "no results" state can apply). */
  emptyResultsPlaceholder?: string | undefined;
  /** Accessible label for the results listbox. */
  resultsAriaLabel?: string | undefined;
  /** Custom hook override for dependency injection / testing. */
  useMentionAutocomplete?: typeof useMentionAutocomplete;
}

/**
 * A self-contained "type a trigger character, get a filtered picker" mention
 * autocomplete: a textarea that detects an in-progress `@token`, expanding
 * into a tabbed, multi-category filtered result list, plus a row of
 * removable chips for everything already picked.
 *
 * Origin: the inline `@`-mention/capability-picker from the vendored
 * schedule/mention god-component (recon r6 §1.19) — "directly analogous to
 * the `QuickSwitcher.tsx` precedent." OD-specific only via the capability
 * data types (`SkillSummary`/`InstalledPluginRecord`/`McpServerConfig`/
 * `ConnectorDetail`), replaced here by the generic `MentionItem` shape (see
 * `types.ts`). The form/REST-submission wiring the original component sat
 * inside stays behind in the host, per r6 §1.19's own "OD-specific" list.
 */
export function MentionAutocomplete<T extends MentionItem<ReactNode>>({
  value,
  onValueChange,
  items,
  categories,
  onSelectionChange,
  triggerChar,
  getSearchText,
  maxResultsPerCategory,
  placeholder,
  rows = 8,
  disabled = false,
  selectedIcon,
  chipRemoveIcon,
  emptyResultsPlaceholder,
  resultsAriaLabel,
  useMentionAutocomplete: useMentionAutocompleteHook = useMentionAutocomplete,
}: MentionAutocompleteProps<T>) {
  const t = useT();
  const mention = useMentionAutocompleteHook<T>({
    value,
    onValueChange,
    items,
    categories,
    onSelectionChange,
    triggerChar,
    getSearchText,
    maxResultsPerCategory,
  });

  return (
    <div ref={mention.containerRef} className="jini-mention-autocomplete">
      <div className={`jini-mention-autocomplete__field${mention.isOpen ? ' is-mentioning' : ''}`}>
        <textarea
          ref={mention.textareaRef}
          className="jini-mention-autocomplete__textarea"
          placeholder={placeholder ? t(placeholder) : undefined}
          value={value}
          onChange={mention.onTextareaChange}
          onClick={mention.onTextareaClick}
          onFocus={mention.onTextareaFocus}
          onKeyDown={mention.onTextareaKeyDown}
          onKeyUp={mention.onTextareaKeyUp}
          rows={rows}
          disabled={disabled}
          aria-controls={mention.isOpen ? 'jini-mention-autocomplete-results' : undefined}
          aria-expanded={mention.isOpen}
        />
      </div>

      {mention.isOpen ? (
        <div
          id="jini-mention-autocomplete-results"
          className="jini-mention-autocomplete__popover"
          role="listbox"
          aria-label={resultsAriaLabel ? t(resultsAriaLabel) : t('Autocomplete results')}
          onMouseDown={(e) => e.preventDefault()}
        >
          <MentionCategoryTabs categories={categories} active={mention.activeCategory} onChange={mention.setActiveCategory} />
          <MentionResultsList<T>
            groups={mention.groups}
            hasResults={mention.hasResults}
            query={mention.query}
            selectedIds={mention.selectedKeys}
            onPick={mention.pickItem}
            selectedIcon={selectedIcon}
            emptyPlaceholder={emptyResultsPlaceholder}
          />
        </div>
      ) : null}

      <SelectedMentionChips<T> items={mention.selectedItems} onRemove={mention.removeItem} removeIcon={chipRemoveIcon} />
    </div>
  );
}

import type { KeyboardEvent, RefObject } from 'react';
import { StatusPill } from './StatusPill.js';
import type { ResourceBoardItem, ResourceMenuActionSpec, ResourceStatusToneMap } from '../../types.js';

/** The card's own class list: `is-selected` and `select-mode` modifiers on top of the base class. */
export function resourceCardClassName({ selected, selectMode }: { selected: boolean; selectMode: boolean }): string {
  return `resource-board-card${selected ? ' is-selected' : ''}${selectMode ? ' select-mode' : ''}`;
}

/** Enter/Space activate the card (open, or toggle selection in select-mode), matching a native button. */
export function isCardActivationKey(event: KeyboardEvent): boolean {
  return event.key === 'Enter' || event.key === ' ';
}

/** The open kebab menu's items — clicks and keydowns inside it never bubble to the card. */
export function ResourceCardMenuItems({
  menuActions,
  busy,
  menuActionLabel,
  onAction,
}: {
  menuActions: ResourceMenuActionSpec[];
  busy: boolean;
  menuActionLabel: ((kind: string, fallback: string) => string) | undefined;
  onAction: (kind: string) => void;
}) {
  return (
    <div
      className="resource-board-card-menu"
      role="menu"
      onClick={(event) => event.stopPropagation()}
      onKeyDown={(event) => event.stopPropagation()}
    >
      {menuActions.map((action) => (
        <button
          key={action.kind}
          type="button"
          role="menuitem"
          className={action.danger ? 'danger' : undefined}
          disabled={busy}
          onClick={() => onAction(action.kind)}
        >
          {menuActionLabel ? menuActionLabel(action.kind, action.label) : action.label}
        </button>
      ))}
    </div>
  );
}

/** The kebab "more" button plus, while `menuOpen`, its menu — `menuContainerRef` is attached only while open (see `ResourceCardProps.menuContainerRef`). */
export function ResourceCardMenu({
  menuActions,
  menuOpen,
  busy,
  moreLabel,
  menuContainerRef,
  menuActionLabel,
  onToggleMenu,
  onAction,
}: {
  menuActions: ResourceMenuActionSpec[];
  menuOpen: boolean;
  busy: boolean;
  moreLabel: string;
  menuContainerRef: RefObject<HTMLDivElement | null> | undefined;
  menuActionLabel: ((kind: string, fallback: string) => string) | undefined;
  onToggleMenu: () => void;
  onAction: (kind: string) => void;
}) {
  return (
    <div className="resource-board-card-menu-anchor" ref={menuOpen ? menuContainerRef : undefined}>
      <button
        type="button"
        className="resource-board-card-more"
        aria-label={moreLabel}
        aria-haspopup="menu"
        aria-expanded={menuOpen}
        onClick={(event) => {
          event.stopPropagation();
          onToggleMenu();
        }}
        // `stopPropagation` on `onClick` above only stops the CLICK the
        // browser synthesizes from an Enter/Space keydown — the raw
        // keydown event itself still bubbles to the outer card's own
        // `onKeyDown` (a separate event), which would otherwise ALSO
        // treat that same keypress as "activate the card" and open/
        // toggle-select it at the same time this button's own action
        // runs. Stop it here too.
        onKeyDown={(event) => event.stopPropagation()}
      >
        {moreLabel}
      </button>
      {menuOpen ? <ResourceCardMenuItems menuActions={menuActions} busy={busy} menuActionLabel={menuActionLabel} onAction={onAction} /> : null}
    </div>
  );
}

/** Title, optional subtitle, and the status badge (only when the item has a status AND a pre-translated label). */
export function ResourceCardMeta<TBody>({
  item,
  statusLabel,
  toneMap,
}: {
  item: ResourceBoardItem<TBody>;
  statusLabel: string | undefined;
  toneMap: ResourceStatusToneMap | undefined;
}) {
  const toneMapProps = toneMap ? { toneMap } : {};
  return (
    <div className="resource-board-card-meta">
      <div className="resource-board-card-title" title={item.title}>
        {item.title}
      </div>
      {item.subtitle ? <div className="resource-board-card-subtitle">{item.subtitle}</div> : null}
      {item.status && statusLabel ? <StatusPill status={item.status} label={statusLabel} {...toneMapProps} /> : null}
    </div>
  );
}

import { useRef } from 'react';
import { useI18n } from '../../../i18n/index.js';
import { Toast } from '../../../../react/components/Toast.js';
import { defaultSketchEditorDependencies } from '../../dependencies.js';
import { defaultExcalidrawLangCode, sketchSceneHasContent, validateSketchEmbeddableUrl } from '../../rules.js';
import type { ExcalidrawInitialDataState, SketchEditorDependencies } from '../../ports.js';
import type {
  SketchDomTextOverrides,
  SketchExportImageResult,
  SketchScene,
  SketchSceneChangeOptions,
  SketchTooltipTarget,
  SketchTranslate,
} from '../../types.js';
import { useSketchDomEnhancements } from '../hooks/useSketchDomEnhancements.js';
import { useSketchSaveWorkflow } from '../hooks/useSketchSaveWorkflow.js';
import { useSketchScene } from '../hooks/useSketchScene.js';
import { useSketchTheme } from '../hooks/useSketchTheme.js';
import { SketchMainMenu } from './SketchMainMenu.js';
import { SketchSaveStateBadge, type SketchSaveStateBadgeProps } from './SketchSaveStateBadge.js';

export interface SketchEditorProps {
  scene: SketchScene;
  onSceneChange: (scene: SketchScene, options?: SketchSceneChangeOptions) => void;
  onClear?: () => void;
  onSave: (scene?: SketchScene) => Promise<boolean | void> | boolean | void;
  onExportImage?: (
    base64: string,
    fileName: string,
    scene: SketchScene,
  ) => Promise<SketchExportImageResult> | SketchExportImageResult;
  onOpenExportedImage?: (fileName: string) => void;
  saving?: boolean;
  dirty?: boolean;
  savedAt?: number;
  fileName: string;
  /** Overrides the default locale → Excalidraw `langCode` mapping. */
  excalidrawLangCode?: (locale: string) => string;
  /** Host translations for Excalidraw's own baked-in English UI text — no
   *  default translated copy ships (see `packages/ui/source-map.md`). */
  domTextOverrides?: SketchDomTextOverrides;
  tooltipTargets?: readonly SketchTooltipTarget[];
  contextMenuActionOrder?: readonly string[];
  contextMenuRecognizedActions?: readonly string[];
  /** Locale-specific phrasings of Excalidraw's "can't embed this URL" toast a
   *  host has already translated via `domTextOverrides`. */
  embedUnavailableAdditionalPhrases?: readonly string[];
  /**
   * Matches the Mermaid-dialog "Insert" button's rendered label, so
   * Command/Ctrl+Enter can submit it. Defaults to English-only
   * (`/^(Insert)(\s|$|→)/i`); a host running Excalidraw in a locale where
   * its own bundled i18n renders this button's label differently (e.g. the
   * source product matched `/^(Insert|插入)/i`) should pass a pattern
   * covering that translation too.
   */
  mermaidInsertLabelPattern?: RegExp;
  /** Suffix stripped from `fileName` before appending `.png` on export.
   *  Defaults to stripping the last extension present. */
  sourceFileExtension?: string;
  /** Swap the bound Excalidraw engine — a host's tests can inject a fake. */
  dependencies?: SketchEditorDependencies;
  /** Custom hook override for dependency injection / testing. */
  useSketchTheme?: typeof useSketchTheme;
}

const EXCALIDRAW_UI_OPTIONS = {
  canvasActions: {
    saveToActiveFile: false,
    loadScene: false,
    toggleTheme: false,
    saveAsImage: false,
    export: false,
  },
  tools: { image: true },
} as const;

/** `saving` wins over `dirty`; only the active label is translated. */
function resolveSaveStatus({ saving, dirty, t }: { saving: boolean; dirty: boolean; t: SketchTranslate }): SketchSaveStateBadgeProps {
  if (saving) return { state: 'saving', label: t('Saving…') };
  if (dirty) return { state: 'dirty', label: t('Unsaved changes') };
  return { state: 'saved', label: t('Saved') };
}

/** An export toast carries a file to open: it lingers longer and offers an
 *  "Open file" action; every other toast is a short-lived notice. */
function sketchToastActionProps({
  actionFileName,
  t,
  onAction,
}: {
  actionFileName: string | undefined;
  t: SketchTranslate;
  onAction: () => void;
}): { ttlMs: number; actionLabel?: string; onAction?: () => void } {
  return actionFileName ? { ttlMs: 5000, actionLabel: t('Open file'), onAction } : { ttlMs: 2200 };
}

/**
 * An Excalidraw-backed sketch surface: theme sync, dirty/save/export
 * orchestration with content-signature deduping, and a DOM-enhancement
 * toolkit (tooltips, simplified context menu, DOM text overrides, portal
 * polish) that makes embedding a third-party editor with no extension
 * hooks feel native. See `packages/ui/source-map.md` for what stayed
 * behind (the source product's legacy pre-Excalidraw item migration, its
 * `.sketch.json` naming convention, and its own translated copy).
 */
export function SketchEditor({
  scene,
  onSceneChange,
  onClear,
  onSave,
  onExportImage,
  onOpenExportedImage,
  saving = false,
  dirty = false,
  savedAt,
  fileName,
  excalidrawLangCode = defaultExcalidrawLangCode,
  domTextOverrides,
  tooltipTargets,
  contextMenuActionOrder,
  contextMenuRecognizedActions,
  embedUnavailableAdditionalPhrases,
  mermaidInsertLabelPattern,
  sourceFileExtension,
  dependencies = defaultSketchEditorDependencies,
  useSketchTheme: useSketchThemeHook = useSketchTheme,
}: SketchEditorProps) {
  const { t, locale } = useI18n();
  const { engine } = dependencies;
  const canvasWrapRef = useRef<HTMLDivElement | null>(null);
  const theme = useSketchThemeHook();

  const {
    initialData,
    editorInstanceKey,
    handleChange,
    currentScene,
    handleClear,
    handleExcalidrawAPI,
    closeActiveDialog,
  } = useSketchScene({ scene, fileName, onSceneChange, onClear });

  // Calls the raw hook (not `useWiredSketchSaveWorkflow`) and threads `engine`
  // explicitly: `SketchEditor` itself accepts a swappable `dependencies` prop
  // (see `SketchEditorProps.dependencies` above) so hosts/tests can inject a
  // fake engine, and the wired hook would bypass that override.
  const { showSaved, exporting, toast, handleSave, handleExportImage, dismissToast, handleToastAction } = useSketchSaveWorkflow({
    dirty,
    saving,
    savedAt,
    fileName,
    currentScene,
    onSave,
    onExportImage,
    onOpenExportedImage,
    engine,
    t,
    sourceFileExtension,
  });

  useSketchDomEnhancements({
    containerRef: canvasWrapRef,
    t,
    domTextOverrides,
    tooltipTargets,
    contextMenuActionOrder,
    contextMenuRecognizedActions,
    embedUnavailableAdditionalPhrases,
    mermaidInsertLabelPattern,
    onCloseActiveDialog: closeActiveDialog,
  });

  const hasContent = sketchSceneHasContent(scene);
  const canSave = dirty || hasContent;
  const saveStatus = resolveSaveStatus({ saving, dirty, t });

  const { Excalidraw, MainMenu } = engine;

  return (
    <div className="sketch-editor">
      <div ref={canvasWrapRef} className="sketch-canvas-wrap sketch-excalidraw-wrap" data-testid="sketch-excalidraw-editor">
        <Excalidraw
          key={editorInstanceKey}
          initialData={initialData as unknown as ExcalidrawInitialDataState}
          excalidrawAPI={handleExcalidrawAPI}
          onChange={handleChange}
          langCode={excalidrawLangCode(locale)}
          theme={theme}
          detectScroll={false}
          handleKeyboardGlobally={false}
          autoFocus
          name={fileName}
          UIOptions={EXCALIDRAW_UI_OPTIONS}
          renderTopRightUI={() => <SketchSaveStateBadge {...saveStatus} />}
          validateEmbeddable={validateSketchEmbeddableUrl}
        >
          <SketchMainMenu
            MainMenu={MainMenu}
            t={t}
            saving={saving}
            showSaved={showSaved}
            canSave={canSave}
            onSave={() => void handleSave()}
            exportAvailable={Boolean(onExportImage)}
            exporting={exporting}
            canExport={hasContent}
            onExportImage={() => void handleExportImage()}
            canClear={hasContent}
            onClear={handleClear}
          />
        </Excalidraw>
      </div>
      {toast ? (
        <Toast
          message={toast.message}
          details={toast.details ?? null}
          tone={toast.tone}
          onDismiss={dismissToast}
          {...sketchToastActionProps({ actionFileName: toast.actionFileName, t, onAction: handleToastAction })}
        />
      ) : null}
    </div>
  );
}

/**
 * A lightweight, non-canvas React stand-in for `@excalidraw/excalidraw`,
 * used by this feature's own tests (and available to a host's tests too).
 * Real Excalidraw is a canvas-heavy third-party library — mounting it in
 * jsdom to test *our* dirty/save/export/DOM-shim logic would be slow and
 * largely untestable anyway (jsdom has no real canvas). This fake renders
 * just enough DOM (matching toolbar `data-testid`s, a menu-trigger, a
 * top-right-UI slot, and the `children` MainMenu) to exercise every hook
 * and the DOM-enhancement toolkit end-to-end.
 *
 * Lives under `react/` rather than at the feature's top-level
 * `dependencies.ts` (a deliberate exception to the "dependencies.ts has zero
 * React import" convention): the thing being faked is *itself* a React
 * component, so its fake unavoidably needs JSX too.
 */
import { useEffect, useRef } from 'react';
import type { ReactNode } from 'react';
import type { SketchEditorDependencies, SketchEditorEnginePort, SketchMainMenuComponent } from '../ports.js';

let fakeElementCounter = 0;

interface FakeExcalidrawInitialData {
  elements?: unknown[];
  appState?: Record<string, unknown>;
  files?: Record<string, unknown>;
}

interface FakeExcalidrawProps {
  initialData?: FakeExcalidrawInitialData;
  excalidrawAPI?: (api: unknown) => void;
  onChange?: (elements: unknown[], appState: Record<string, unknown>, files: Record<string, unknown>) => void;
  renderTopRightUI?: () => ReactNode;
  name?: string;
  /** Real Excalidraw re-themes its own canvas off this prop with nothing
   *  else in the DOM to observe — surfaced here as `data-theme` so a test
   *  driving `theme` through (e.g. via a `useSketchTheme` override) has
   *  something to actually assert on. */
  theme?: string;
  children?: ReactNode;
}

function FakeExcalidraw({ initialData, excalidrawAPI, onChange, renderTopRightUI, name, theme, children }: FakeExcalidrawProps) {
  const elementsRef = useRef<unknown[]>((initialData?.elements ?? []).slice());
  const appStateRef = useRef<Record<string, unknown>>({ ...(initialData?.appState ?? {}) });
  const filesRef = useRef<Record<string, unknown>>({ ...(initialData?.files ?? {}) });

  useEffect(() => {
    excalidrawAPI?.({
      updateScene: (partial: { appState?: Record<string, unknown> } | undefined) => {
        if (partial?.appState) appStateRef.current = { ...appStateRef.current, ...partial.appState };
      },
      getSceneElementsIncludingDeleted: () => elementsRef.current,
      getAppState: () => appStateRef.current,
      getFiles: () => filesRef.current,
    });
    // Mount-once, matching real Excalidraw's own imperative-handle-once contract.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fireChange = () => {
    fakeElementCounter += 1;
    const nextElements = [
      ...elementsRef.current,
      { id: `fake-element-${fakeElementCounter}`, version: fakeElementCounter, versionNonce: fakeElementCounter, isDeleted: false, type: 'rectangle' },
    ];
    elementsRef.current = nextElements;
    onChange?.(nextElements, appStateRef.current, filesRef.current);
  };

  return (
    <div data-testid="fake-excalidraw" aria-label={name} data-theme={theme}>
      <button type="button" data-testid="main-menu-trigger">
        Menu
      </button>
      <button type="button" data-testid="toolbar-selection">
        Selection
      </button>
      <button type="button" data-testid="toolbar-rectangle">
        Rectangle
      </button>
      <button type="button" data-testid="fake-excalidraw-draw" onClick={fireChange}>
        Draw
      </button>
      {renderTopRightUI ? renderTopRightUI() : null}
      {children}
    </div>
  );
}

interface FakeMainMenuItemProps {
  onClick: () => void;
  disabled?: boolean;
  icon?: ReactNode;
  children?: ReactNode;
  [key: string]: unknown;
}

function FakeMainMenuItem({ onClick, disabled, icon, children, ...rest }: FakeMainMenuItemProps) {
  return (
    <button type="button" onClick={onClick} disabled={disabled} {...rest}>
      {icon}
      {children}
    </button>
  );
}

function FakeMainMenuSeparator() {
  return <hr />;
}

function FakeMainMenuBase({ children }: { children?: ReactNode }) {
  return (
    <div data-testid="fake-main-menu" role="menu">
      {children}
    </div>
  );
}

const FakeMainMenu = Object.assign(FakeMainMenuBase, {
  Item: FakeMainMenuItem,
  Separator: FakeMainMenuSeparator,
  DefaultItems: {
    SearchMenu: () => <div data-testid="fake-search-menu" />,
