import { useEffect, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { useT } from '../../../i18n/index.js';
import { ALL_KIND_FILTER } from '../../constants.js';
import { useTabLauncherMenu, type UseTabLauncherMenuOptions } from '../hooks/useTabLauncherMenu.js';
import { TabLauncherActionRow } from './TabLauncherActionRow.js';
import { TabLauncherResultRow, type TabLauncherResultRowProps } from './TabLauncherResultRow.js';

export interface TabLauncherMenuProps<TActionCtx = void> extends UseTabLauncherMenuOptions<TActionCtx> {
  searchPlaceholder?: string;
  renderIcon?: (iconName: string | undefined) => ReactNode;
  renderSearchIcon?: () => ReactNode;
  /** Custom hook override for dependency injection / testing. */
  useTabLauncherMenu?: typeof useTabLauncherMenu;
}

function renderResultSection(
  { items, renderLabel, startIndex, selected, ...rowProps }: Pick<TabLauncherResultRowProps, 'openLabel' | 'onHover' | 'onSelect'> & {
    items: readonly TabLauncherResultRowProps['item'][];
    renderLabel: () => string;
    startIndex: number;
    selected: number;
  },
  { renderIcon }: Pick<TabLauncherResultRowProps, 'renderIcon'> = {},
) {
  if (items.length === 0) return null;
  return (
    <section className="jini-tab-launcher-menu__section">
      <div className="jini-tab-launcher-menu__section-header">{renderLabel()}</div>
      <ul className="jini-tab-launcher-menu__list">
        {items.map((item, index) => {
          const selectableIndex = startIndex + index;
          return (
            <TabLauncherResultRow
              key={item.id}
              item={item}
              selectableIndex={selectableIndex}
              selected={selectableIndex === selected}
              renderIcon={renderIcon}
              {...rowProps}
            />
          );
        })}
      </ul>
    </section>
  );
}

/**
 * An anchored, portal-rendered command-palette dropdown for a tab strip's
 * "+" button: viewport-clamped fixed positioning off an anchor element,
 * outside-click/Escape dismiss, text search + kind-filter chips over file
 * results, a separate "open tabs" search, and a "create new" action list —
 * all as one flat keyboard-navigable selection.
 *
 * Origin: `TabLauncherMenu.tsx` (`apps/web/src/components/workspace/`). Its
 * `ProjectFile`/`WorkspaceContextItem` split collapses into one generic
 * `TabLauncherResultItem`; `LauncherAction`/`LauncherContext` become
 * `TabLauncherAction<TActionCtx>` generic over whatever context the host's
 * actions need; the OD analytics contract (`TabLauncherClickProps`) becomes
 * a generic `TabLauncherTrackEvent` union. See `packages/ui/source-map.md`
 * for the full genericization writeup, including why this is a distinct
 * primitive from `features/command-palette/`.
 */
export function TabLauncherMenu<TActionCtx = void>({
  searchPlaceholder,
  renderIcon,
  renderSearchIcon,
  useTabLauncherMenu: useTabLauncherMenuHook = useTabLauncherMenu,
  ...options
}: TabLauncherMenuProps<TActionCtx>) {
  const t = useT();
  const menu = useTabLauncherMenuHook(options);

  useEffect(() => {
    const el = menu.containerRef.current?.querySelector<HTMLElement>(`[data-selectable-idx="${menu.selected}"]`);
    el?.scrollIntoView({ block: 'nearest' });
  }, [menu.selected, menu.containerRef]);

  // `position` only becomes non-null once the anchored-positioning effect
  // runs against a real `anchor`, which requires a real DOM — so this alone
  // already keeps the portal (and its `document.body` reference) from ever
  // running during SSR, with no separate `typeof document` check needed.
  if (!menu.position) return null;

  const openLabel = t('Open');
  const hasResults = menu.fileResults.length > 0 || menu.tabResults.length > 0;

  return createPortal(
    <div
      ref={menu.containerRef}
      className="jini-tab-launcher-menu"
      style={{ top: menu.position.top, left: menu.position.left }}
      role="dialog"
      aria-label={t('New tab')}
    >
      <div className="jini-tab-launcher-menu__search-row">
        {renderSearchIcon ? <span className="jini-tab-launcher-menu__search-icon" aria-hidden="true">{renderSearchIcon()}</span> : null}
        <input
          autoFocus
          className="jini-tab-launcher-menu__search-input"
          type="text"
          value={menu.query}
          placeholder={searchPlaceholder ?? t('Search files…')}
          onChange={(event) => menu.setQuery(event.target.value)}
          onKeyDown={menu.handleInputKeyDown}
        />
      </div>

      {menu.presentKinds.length > 0 ? (
        <div className="jini-tab-launcher-menu__chips">
          <button
            type="button"
            className={`jini-tab-launcher-menu__chip${menu.kindFilter === ALL_KIND_FILTER ? ' jini-tab-launcher-menu__chip--active' : ''}`}
            onClick={() => menu.setKindFilter(ALL_KIND_FILTER)}
          >
            {t('All files')}
          </button>
          {menu.presentKinds.map((kind) => (
            <button
              key={kind}
              type="button"
              className={`jini-tab-launcher-menu__chip${menu.kindFilter === kind ? ' jini-tab-launcher-menu__chip--active' : ''}`}
              onClick={() => menu.setKindFilter(kind)}
            >
              {kind}
            </button>
          ))}
        </div>
      ) : null}

      <div className="jini-tab-launcher-menu__scroll-body">
        {menu.actions.length > 0 ? (
          <section className="jini-tab-launcher-menu__section">
            <div className="jini-tab-launcher-menu__section-header">{t('Create new')}</div>
            <ul className="jini-tab-launcher-menu__list">
              {menu.actions.map((action) => (
                <TabLauncherActionRow key={action.id} action={action} onSelect={menu.runAction} renderIcon={renderIcon} />
              ))}
            </ul>
          </section>
        ) : null}

        {renderResultSection({
          items: menu.fileResults,
          renderLabel: () => t('Open file'),
          startIndex: 0,
          selected: menu.selected,
          openLabel,
          onHover: menu.setSelected,
          onSelect: menu.selectFile,
        }, { renderIcon })}

        {renderResultSection({
          items: menu.tabResults,
          renderLabel: () => t('Open tabs'),
          startIndex: menu.fileResults.length,
          selected: menu.selected,
          openLabel,
          onHover: menu.setSelected,
          onSelect: menu.selectTab,
        }, { renderIcon })}

        {!hasResults ? <div className="jini-tab-launcher-menu__empty">{t('No files match')}</div> : null}
      </div>
    </div>,
    document.body,
  );
}

import type { ReactNode } from 'react';
import { useT } from '../../../i18n/index.js';
import { findActiveTab } from '../../rules.js';
import type { TabbedDialogChromeLabels, TabbedDialogTabMeta } from '../../types.js';
import { useTabbedDialog } from '../hooks/useTabbedDialog.js';
import { TabbedDialogChrome } from './TabbedDialogChrome.js';
import { TabbedDialogHeader } from './TabbedDialogHeader.js';
import { TabbedDialogSidebar } from './TabbedDialogSidebar.js';
import {
  buildTabbedDialogClassName,
  dialogRootRoleProps,
  resolveIsModal,
  resolveTabbedDialogLabels,
} from './tabbedDialogView.js';

/** One sidebar-nav entry + its rendered panel. Extends the pure
 *  `TabbedDialogTabMeta` shape with the render-specific fields
 *  (`icon`/`panel`) that only make sense in the React layer. */
export interface TabbedDialogTab<TId extends string = string> extends TabbedDialogTabMeta<TId> {
  icon?: ReactNode;
  panel: ReactNode;
}

export interface TabbedDialogProps<T extends TabbedDialogTab = TabbedDialogTab> {
  tabs: readonly T[];
  initialActiveTabId?: string;
  activeTabId?: string;
  onActiveTabIdChange?: (tabId: string) => void;
  /** Closes the dialog (backdrop click, close button, Escape). Omit to
   *  render the shell without a close affordance — e.g. embedded inline
   *  rather than as a modal overlay. */
  onClose?: () => void;
  /**
   * Whether to render as a floating modal (backdrop, `aria-modal`,
   * click-outside-to-close) or inline in the host's own layout.
   *
   * Defaults to `'modal'` when `onClose` is supplied and `'inline'` when it is
   * not, so the common cases need no prop. Set it explicitly for the ones that
   * don't follow that rule — a modal whose only dismissal is Escape (`'modal'`
   * with no `onClose`), or an embedded panel that still offers a close/hide
   * button (`'inline'` with an `onClose`).
   *
   * Inline is not cosmetic: a fixed-position backdrop over an embedded panel
   * covers the host's own navigation, and `aria-modal` on a non-modal region
   * hides the rest of the page from assistive tech.
   */
  presentation?: 'modal' | 'inline';
  /** Renders the tall centered hero (kicker/title/subtitle) instead of the
   *  normal per-tab header — e.g. a first-run "Welcome" variant. */
  welcome?: boolean;
  defaultSidebarCollapsed?: boolean;
  /** Shows the fullscreen toggle button and applies its expanded state as a
   *  modifier class. Defaults to `true`; a host with no use for fullscreen
   *  can turn it off. */
  fullscreenEnabled?: boolean;
  defaultFullscreen?: boolean;
  labels?: TabbedDialogChromeLabels;
  /** Extra chrome rendered in the top-right strip, alongside the fullscreen
   *  toggle and close button — e.g. a host's own autosave-status indicator.
   *  Fully host-owned; the shell renders it as-is. */
  chromeExtra?: ReactNode;
  dialogAriaLabelledBy?: string;
  className?: string;
}

/**
 * Generic tabbed-dialog chrome: modal backdrop + sidebar nav + active-panel
 * switching + fullscreen/collapse/close affordances. Carries no opinion
 * about what any tab contains, or about which product mounts it — a host
 * supplies `tabs`, each with its own `panel` (any `ReactNode`).
 *
 * Extracted (2026-08-13) out of `SettingsDialogShell` (`../../settings/dialog/`), which
 * had accreted five non-Settings hosts in a downstream consumer (`AgentPlugins.tsx`, `AiAssistant.tsx`,
 * `Authentication.tsx`, `PlaceholderTabs.tsx`, plus the original `SettingsUi.tsx`) while
 * still being named — and CSS-classed — after only one of them. `SettingsDialogShell` is
 * now a thin wrapper that renders this component with its own settings-flavoured label
 * defaults (`t('Settings')` kicker, `t('Settings sections')` sidebar aria-label, …); treat
 * it as the reference host, not a special case this component needs to know about.
 *
 * Proof this is separable from any one tab's content: in the origin `SettingsDialog.tsx`
 * (the 8,538-line vendored OD reference — see `packages/ui/source-map.md`), 8 of its 17
 * real tabs were already separate files the original component merely mounted — the shell
 * itself never reached into a tab's internals.
 */
export function TabbedDialog<T extends TabbedDialogTab>({
  tabs,
  initialActiveTabId,
  activeTabId: controlledActiveTabId,
  onActiveTabIdChange,
  onClose,
  presentation,
  welcome = false,
  defaultSidebarCollapsed = false,
  fullscreenEnabled = true,
  defaultFullscreen = false,
  labels,
  chromeExtra,
  dialogAriaLabelledBy = 'tabbed-dialog-title',
  className,
}: TabbedDialogProps<T>) {
  const isModal = resolveIsModal({ hasOnClose: Boolean(onClose) }, { presentation });
  const t = useT();
  const shell = useTabbedDialog({
    tabs,
    initialActiveTabId,
    activeTabId: controlledActiveTabId,
    onActiveTabIdChange,
    onClose,
    defaultSidebarCollapsed,
    defaultFullscreen,
  });

  const activeTab = findActiveTab(tabs, shell.activeTabId);
  const resolvedLabels = resolveTabbedDialogLabels({ t }, { labels });

  const body = (
    <div
      className={buildTabbedDialogClassName(shell, { className })}
      {...dialogRootRoleProps({ isModal })}
      aria-labelledby={dialogAriaLabelledBy}
    >
      <TabbedDialogChrome
        chromeExtra={chromeExtra}
        fullscreenEnabled={fullscreenEnabled}
        fullscreen={shell.fullscreen}
        onToggleFullscreen={shell.toggleFullscreen}
        onClose={onClose}
        labels={resolvedLabels}
      />

      <TabbedDialogHeader id={dialogAriaLabelledBy} welcome={welcome} activeTab={activeTab} labels={resolvedLabels} />

      <div className="jini-tabbed-dialog-body">
        <TabbedDialogSidebar
          tabs={tabs}
          activeTabId={shell.activeTabId}
          isModal={isModal}
          collapsed={shell.sidebarCollapsed}
          onToggleCollapsed={shell.toggleSidebarCollapsed}
          onSelect={shell.setActiveTabId}
          labels={resolvedLabels}
        />

        <div className="jini-tabbed-dialog-content" ref={shell.contentRef}>
          {activeTab?.panel}
        </div>
      </div>
    </div>
  );

  // Inline presentation returns the panel bare: no fixed-position backdrop, no
  // `aria-modal`, no click-outside handler. Wrapping it anyway is what made an
  // embedded shell paint a full-viewport overlay over its own host's chrome.
  if (!isModal) return body;

  return (
    <div
      className="jini-tabbed-dialog-backdrop"
      onClick={onClose}
      // `settings-dialog-backdrop`, not `tabbed-dialog-backdrop` — same reasoning as the
      // nav-item testid in `TabbedDialogSidebar.tsx`: kept unchanged so a downstream consumer's existing Playwright specs and unit
      // tests keep matching it.
      data-testid="settings-dialog-backdrop"
    >
      {body}
    </div>
  );
}

import { useId, useRef, useState } from 'react';
import { useDismissOnOutsideOrEscape } from '../../../../browser/index.js';
import { useT } from '../../../i18n/index.js';

export interface VersionPromptPopoverProps {
  /** The generating prompt for the selected version, already trimmed.
   *  Empty string when the selected version has none. */
  prompt: string;
  /** Disable the toggle entirely (no version selected). */
  disabled: boolean;
  /** True for a short window after a successful copy. Owned by the parent
   *  (a `useCopyToClipboard` hook, e.g. `features/viewer-shell/`'s) rather
   *  than by this component — this component stays props-in/JSX-out for
   *  its business logic, only the open/close disclosure state is local. */
  copied: boolean;
  onCopy: (text: string) => void;
  /** Notified whenever this popover's own open/close disclosure state
   *  changes, so a host (e.g. `VersionManagerModal`) can gate its own
   *  Escape handling while this popover is showing — without lifting the
   *  disclosure state itself out of this component. */
  onOpenChange?: (open: boolean) => void;
}

/** Disclosure showing the AI-generation prompt behind the selected version,
 *  with a copy button. Open/close is small local UI state (acceptable per
 *  this package's hook-ownership discipline); copy-to-clipboard itself is
 *  injected, not reimplemented here. */
export function VersionPromptPopover({ prompt, disabled, copied, onCopy, onOpenChange }: VersionPromptPopoverProps) {
  const t = useT();
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const popoverId = useId();

  useDismissOnOutsideOrEscape({
    onDismiss: () => {
      setOpen(false);
      onOpenChange?.(false);
    },
  }, { enabled: open, containerRef: wrapRef });

  return (
    <div className="jini-version-prompt-popover-wrap" ref={wrapRef}>
      <button
        type="button"
        className={`jini-version-prompt-toggle${open ? ' active' : ''}`}
        aria-expanded={open}
        aria-controls={open ? popoverId : undefined}
        disabled={disabled}
        onClick={() => {
          const next = !open;
          setOpen(next);
          onOpenChange?.(next);
        }}
      >
        {t('Prompt')}
      </button>
      {open ? (
        <section className="jini-version-prompt-popover" id={popoverId} role="region" aria-label={t('Prompt')}>
          <div className="jini-version-prompt-head">
            <h3>{t('Prompt')}</h3>
            <button type="button" className="jini-viewer-action" disabled={!prompt} onClick={() => onCopy(prompt)}>
              {copied ? t('Copied') : t('Copy')}
            </button>
          </div>
          <p>{prompt || t('This version has no recorded prompt.')}</p>
        </section>
      ) : null}
    </div>
  );
}

