import { useRef, type MouseEvent as ReactMouseEvent, type ReactNode, type RefObject } from 'react';
import { useT } from '../../../i18n/index.js';
import { SegmentedToggle } from './SegmentedToggle.js';
import { ViewerShell } from './ViewerShell.js';
import { useMarkdownScrollSync, type UseMarkdownScrollSyncResult } from '../hooks/useMarkdownScrollSync.js';
import type { MarkdownSplitPaneMode } from '../../types.js';

export interface MarkdownSplitPaneProps {
  mode: MarkdownSplitPaneMode;
  onModeChange: (mode: MarkdownSplitPaneMode) => void;
  sourceText: string;
  onSourceChange: (text: string) => void;
  /** Host-rendered markdown HTML (`renderMarkdownToSafeHtml`-shaped — the
   *  actual renderer, shiki highlighting, and image-src-rewriting are all
   *  genuinely OD/product-specific and were not ported; see
   *  `packages/ui/source-map.md`). `null` while loading. */
  previewHtml: string | null;
  /** CSS selector for the rendered preview's root element, forwarded to the
   *  scroll-sync measurement (default `.markdown-rendered`). */
  previewSelector?: string;
  loading?: boolean;
  loadingLabel?: string;
  sourceLabel?: string;
  splitLabel?: string;
  previewLabel?: string;
  editorAriaLabel?: string;
  previewAriaLabel?: string;
  modeAriaLabel?: string;
  /** Extra left-of-tabs toolbar content (e.g. a host's streaming/error
   *  status label). */
  toolbarLeftExtra?: ReactNode;
  /** Right-aligned toolbar content — a host's save-status indicator,
   *  copy/download buttons, etc. (all genuinely host-specific). */
  toolbarActions?: ReactNode;
  /** Extra props spread onto the editor `<textarea>` (e.g. `onPaste`/
   *  `onDrop` handlers a host wires for image upload — not implemented
   *  here, since that's a product-specific upload pipeline). */
  editorTextareaProps?: Record<string, unknown>;
  /** Click handler on the rendered preview `<article>` — a host uses this
   *  to delegate code-block "copy" button clicks, etc. */
  onPreviewClick?: (event: ReactMouseEvent<HTMLElement>) => void;
}

/**
 * The generic core of the source component's `MarkdownViewer`: a
 * source/split/preview mode toggle plus a two-pane layout whose scroll
 * positions stay aligned via block-anchored scroll-sync
 * (`useMarkdownScrollSync`). Ported without the artifact-status gate that
 * the extraction plan called out — and, per a closer read than the plan's
 * one-line description, also without the autosave/debounce-write pipeline,
 * image paste/drop upload, and shiki-based code-block syntax highlighting,
 * all of which are genuinely product/daemon-specific (see
 * `packages/ui/source-map.md` for the full disclosure). A host renders its
 * own markdown-to-HTML pipeline and passes the result as `previewHtml`.
 */
export function MarkdownSplitPane({
  mode,
  onModeChange,
  sourceText,
  onSourceChange,
  previewHtml,
  previewSelector,
  loading = false,
  loadingLabel,
  sourceLabel,
  splitLabel,
  previewLabel,
  editorAriaLabel,
  previewAriaLabel,
  modeAriaLabel,
  toolbarLeftExtra,
  toolbarActions,
  editorTextareaProps,
  onPreviewClick,
}: MarkdownSplitPaneProps) {
  const t = useT();
  const editorRef = useRef<HTMLTextAreaElement | null>(null);
  const previewRef = useRef<HTMLElement | null>(null);

  const { handleEditorScroll, handlePreviewScroll, activatePane } = useMarkdownScrollSync({
    mode,
    sourceText,
    editorRef,
    previewRef,
    previewSelector,
    resyncKey: previewHtml,
  });

  const showEditor = mode === 'source' || mode === 'split';
  const showPreview = mode === 'preview' || mode === 'split';
  const isLoading = loading || previewHtml === null;

  return (
    <ViewerShell
      kindClassName="markdown-split-viewer"
      bodyClassName={`markdown-workbench markdown-workbench-${mode}`}
      toolbarLeft={
        <>
          {toolbarLeftExtra}
          <MarkdownModeTabs
            mode={mode}
            onModeChange={onModeChange}
            sourceLabel={sourceLabel}
            splitLabel={splitLabel}
            previewLabel={previewLabel}
            modeAriaLabel={modeAriaLabel}
          />
        </>
      }
      toolbarActions={toolbarActions}
    >
      {isLoading ? (
        <div className="viewer-empty">{loadingLabel ?? t('Loading…')}</div>
      ) : (
        <>
          {showEditor ? (
            <MarkdownEditorPane
              editorRef={editorRef}
              sourceText={sourceText}
              onSourceChange={onSourceChange}
              ariaLabel={editorAriaLabel}
              onScroll={handleEditorScroll}
              activatePane={activatePane}
              textareaProps={editorTextareaProps}
            />
          ) : null}
          {showPreview ? (
            <MarkdownPreviewPane
              previewRef={previewRef}
              // Non-null assertion: `isLoading` (above) is true whenever
              // `previewHtml === null`, and this JSX only renders in the
              // `!isLoading` branch — so `previewHtml` is always a string
              // here. TypeScript can't follow that indirect invariant
              // through the derived `isLoading` boolean, hence the `!`.
              html={previewHtml!}
              ariaLabel={previewAriaLabel}
              onScroll={handlePreviewScroll}
              activatePane={activatePane}
              onPreviewClick={onPreviewClick}
            />
          ) : null}
        </>
      )}
    </ViewerShell>
  );
}

type ActivatePane = UseMarkdownScrollSyncResult['activatePane'];
type PaneScrollHandler = UseMarkdownScrollSyncResult['handleEditorScroll'];

function MarkdownModeTabs({
  mode,
  onModeChange,
  sourceLabel,
  splitLabel,
  previewLabel,
  modeAriaLabel,
}: {
  mode: MarkdownSplitPaneMode;
  onModeChange: (mode: MarkdownSplitPaneMode) => void;
  sourceLabel: string | undefined;
  splitLabel: string | undefined;
  previewLabel: string | undefined;
  modeAriaLabel: string | undefined;
}) {
  const t = useT();
  return (
    <SegmentedToggle
      className="markdown-mode-tabs"
      ariaLabel={modeAriaLabel ?? t('Markdown view mode')}
      value={mode}
      onChange={onModeChange}
      options={[
        { value: 'source', label: sourceLabel ?? t('Source') },
        { value: 'split', label: splitLabel ?? t('Split') },
        { value: 'preview', label: previewLabel ?? t('Preview') },
      ]}
    />
  );
}

function MarkdownEditorPane({
  editorRef,
  sourceText,
  onSourceChange,
  ariaLabel,
  onScroll,
  activatePane,
  textareaProps,
}: {
  editorRef: RefObject<HTMLTextAreaElement | null>;
  sourceText: string;
  onSourceChange: (text: string) => void;
  ariaLabel: string | undefined;
  onScroll: PaneScrollHandler;
  activatePane: ActivatePane;
  textareaProps: Record<string, unknown> | undefined;
}) {
  const t = useT();
  const label = ariaLabel ?? t('Markdown editor');
  return (
    <section className="markdown-editor-pane" aria-label={label}>
      <textarea
        ref={editorRef}
        className="markdown-editor"
        value={sourceText}
        aria-label={label}
        spellCheck
        onFocus={() => activatePane('editor')}
        onChange={(event) => {
          activatePane('editor');
          onSourceChange(event.currentTarget.value);
        }}
        onScroll={onScroll}
        {...textareaProps}
      />
    </section>
  );
}

function MarkdownPreviewPane({
  previewRef,
  html,
  ariaLabel,
  onScroll,
  activatePane,
  onPreviewClick,
}: {
  previewRef: RefObject<HTMLElement | null>;
  html: string;
  ariaLabel: string | undefined;
  onScroll: PaneScrollHandler;
  activatePane: ActivatePane;
  onPreviewClick: MarkdownSplitPaneProps['onPreviewClick'];
}) {
  const t = useT();
  const activatePreview = () => activatePane('preview');
  return (
    <div className="markdown-preview-pane-wrap">
      <section
        ref={previewRef}
        className="markdown-preview-pane"
        aria-label={ariaLabel ?? t('Markdown preview')}
        onPointerDown={activatePreview}
        onWheel={activatePreview}
        onTouchStart={activatePreview}
        onKeyDown={activatePreview}
        onFocus={activatePreview}
        onScroll={onScroll}
      >
        {/* Trusting `previewHtml` is the host's responsibility — this
            component renders whatever HTML string it's given. */}
        <article className="markdown-rendered" onClick={onPreviewClick} dangerouslySetInnerHTML={{ __html: html }} />
      </section>
    </div>
  );
}

export interface VideoViewerBodyProps {
  src: string;
}

/** Plain `<video>` body — generalizes the source component's
 *  `VideoViewer` once the daemon-specific URL-building is stripped out. */
export function VideoViewerBody({ src }: VideoViewerBodyProps) {
  return <video src={src} controls playsInline preload="metadata" />;
}

// NOTE: verified zero real consumers in the vendored source snapshot before
// porting (see packages/ui/source-map.md) — shipped anyway since it's small,
// self-contained, and correct; a host may still find it useful as a select
// primitive with grouped options and optional portal-rendered menu.
//
// Shape: this file follows the "dumb component + co-located testable hook(s)"
// pattern (see TooltipLayer.tsx). Every seam is exported: pure helpers, the
// `useCustomSelect` hook that owns all state/refs/effects/handlers, the
// `CustomSelectOptionButton` leaf, and the dumb `CustomSelect` render.

import { useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent, MutableRefObject, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { useOverlayContainer } from '@jini-ai/ui-kit/react';
import { useSelectPopover, isSelectEventInside, openSelectOnKey, applySelectNavigationKey, resolveSelectPortalContainer, resolveSelectOriginPage } from './select-popover.js';
import { Icon } from './Icon.js';
import { agentHandleProps, agentHandleSegment } from '@jini-ai/agentic';
import { useAgentHandle, type AgentControlProps } from '../hooks/useAgentHandle.js';

export interface CustomSelectOption {
  value: string;
  label: string;
  disabled?: boolean;
}

export interface CustomSelectGroup {
  label: string;
  options: CustomSelectOption[];
}

export type CustomSelectItem = CustomSelectOption | CustomSelectGroup;

export interface CustomSelectProps extends AgentControlProps {
  value: string;
  options: CustomSelectItem[];
  onChange: (value: string) => void;
  ariaLabel: string;
  labelledBy?: string;
  // `| undefined` (not just `?`) so a caller under `exactOptionalPropertyTypes`
  // can forward its OWN optional `className` prop straight through without
  // needing a conditional-spread — see `SearchableModelSelect`, this
  // component's first real consumer.
  className?: string | undefined;
  triggerClassName?: string;
  menuClassName?: string;
  disabled?: boolean;
  placeholder?: string;
  portal?: boolean;
  /** Host-owned portal destination; otherwise the nearest native dialog keeps the menu in its top layer.
   * Keep this container outside clipping regions and transformed fixed-position containing blocks.
   */
  portalContainer?: Element | DocumentFragment | null | undefined;
  title?: string;
  onFocus?: () => void;
  /** Extra content rendered inside the menu, above the option list — the seam
   *  `SearchableModelSelect` uses to place a search input inside the popover
   *  without this component needing to know search exists. `undefined`
   *  renders nothing extra, so every existing caller is unaffected. */
  menuHeader?: ReactNode;
  /** Fires whenever the menu's open state changes. Optional: a plain select
   *  has nothing to do with this; `SearchableModelSelect` uses it to focus
   *  its search input and reset the query exactly when the menu opens. */
  onOpenChange?: (open: boolean) => void;
  /** Custom hook override for dependency injection / testing. */
  useCustomSelect?: typeof useCustomSelect;
}

/** A single option after grouped items are flattened; `group` records the
 * originating group label (absent for top-level options). */
export interface CustomSelectFlatOption extends CustomSelectOption {
  group?: string;
}

/** Portal-menu geometry, in viewport pixels. */
export interface CustomSelectMenuPosition {
  top: number;
  left: number;
  width: number;
  maxHeight: number;
}

/** Space between the trigger and the menu. */
export const CUSTOM_SELECT_MENU_GAP = 4;
/** Minimum distance the menu keeps from any viewport edge. */
export const CUSTOM_SELECT_VIEWPORT_PAD = 12;
/** Floor for the menu's computed max-height. */
export const CUSTOM_SELECT_MIN_MENU_HEIGHT = 160;
/** Ceiling for the menu's computed max-height. */
export const CUSTOM_SELECT_MAX_MENU_HEIGHT = 300;
/** When the space below the trigger is under this, the menu may flip above. */
export const CUSTOM_SELECT_FLIP_THRESHOLD = 180;

/** Type guard: is this item a group (has nested `options`) rather than a leaf? */
export function isCustomSelectGroup(item: CustomSelectItem): item is CustomSelectGroup {
  return 'options' in item;
}

/** Flatten grouped/ungrouped items into a single ordered list, tagging each
 * option that came from a group with its group label. */
export function flattenCustomSelectOptions(items: CustomSelectItem[]): CustomSelectFlatOption[] {
  return items.flatMap((item) =>
    isCustomSelectGroup(item)
      ? item.options.map((option) => ({ ...option, group: item.label }))
      : [item],
  );
}

/** Pure geometry: given the trigger's rect and the viewport, compute where the
 * portal menu should sit (flipping above the trigger when space below is
 * tight). Extracted from the hook so the branching math is unit-testable. */
export function computeCustomSelectMenuPosition(
  rect: { top: number; bottom: number; left: number; width: number },
  viewport: { width: number; height: number },
): CustomSelectMenuPosition {
  const gap = CUSTOM_SELECT_MENU_GAP;
  const viewportPad = CUSTOM_SELECT_VIEWPORT_PAD;
  const below = viewport.height - rect.bottom - viewportPad;
  const above = rect.top - viewportPad;
  const maxHeight = Math.max(
    CUSTOM_SELECT_MIN_MENU_HEIGHT,
    Math.min(CUSTOM_SELECT_MAX_MENU_HEIGHT, Math.max(below, above) - gap),
  );
  const openAbove = below < CUSTOM_SELECT_FLIP_THRESHOLD && above > below;
  return {
    top: openAbove ? Math.max(viewportPad, rect.top - maxHeight - gap) : rect.bottom + gap,
    left: Math.min(
      Math.max(viewportPad, rect.left),
      Math.max(viewportPad, viewport.width - rect.width - viewportPad),
    ),
    width: rect.width,
    maxHeight,
  };
}

/** Pure keyboard-nav math: the value the active option should move to when the
 * user presses Down (`1`) or Up (`-1`), wrapping around the enabled options.
 * Returns `null` when there is nothing enabled to move to. */
export function nextCustomSelectActiveValue(
  enabledOptions: CustomSelectFlatOption[],
  activeValue: string,
  direction: 1 | -1,
): string | null {
  if (!enabledOptions.length) return null;
  const currentIndex = enabledOptions.findIndex((option) => option.value === activeValue);
  const nextIndex =
    currentIndex < 0
      ? 0
      : (currentIndex + direction + enabledOptions.length) % enabledOptions.length;
  return enabledOptions[nextIndex]!.value;
}

/** Pure: which option should be active when the menu opens — the current value
 * if it maps to an enabled option, else the first enabled option, else none. */
export function resolveInitialCustomSelectActiveValue(
  flatOptions: CustomSelectFlatOption[],
  enabledOptions: CustomSelectFlatOption[],
  value: string,
): string {
  const selectedOption = flatOptions.find((option) => option.value === value && !option.disabled);
  return selectedOption?.value ?? enabledOptions[0]?.value ?? '';
}

export interface CustomSelectActiveReconcileInput {
  open: boolean;
  value: string;
  wasOpen: boolean;
  activeSourceValue: string;
  flatOptions: CustomSelectFlatOption[];
  enabledOptions: CustomSelectFlatOption[];
}

export interface CustomSelectActiveReconcileResult {
  /** New value for the `wasOpen` ref. */
  wasOpen: boolean;
  /** New value for the `activeSourceValue` ref. */
  activeSourceValue: string;
  /** When defined, the active value should be set to this; when `undefined`,
   * the active value is left untouched. */
  nextActiveValue?: string;
}

/** Pure decision for the open/value effect: how to reconcile the active option
 * (and the two tracking refs) when `open` or `value` changes. Kept out of the
 * effect so its "already reconciled" guard is directly unit-testable — that
 * branch is unreachable through the effect's `[open, value]` dependency flow. */
export function reconcileCustomSelectActiveValue(
  input: CustomSelectActiveReconcileInput,
): CustomSelectActiveReconcileResult {
  const { open, value, wasOpen, activeSourceValue, flatOptions, enabledOptions } = input;
  if (!open) {
    return { wasOpen: false, activeSourceValue: value };
  }
  if (wasOpen && activeSourceValue === value) {
    return { wasOpen, activeSourceValue };
  }
  return {
    wasOpen: true,
    activeSourceValue: value,
    nextActiveValue: resolveInitialCustomSelectActiveValue(flatOptions, enabledOptions, value),
  };
}

/** Pure: is a pointerdown target inside the trigger or the (possibly absent)
 * menu? Used to decide whether an outside click should close the menu. */
export function isCustomSelectEventInside(
  target: Node,
  button: HTMLElement | null,
  menu: HTMLElement | null,
): boolean {
  return isSelectEventInside({ target, trigger: button, panel: menu });
}

export interface UseCustomSelectParams {
  value: string;
  options: CustomSelectItem[];
  onChange: (value: string) => void;
  portal: boolean;
  placeholder?: string | undefined;
  /** See `CustomSelectProps.onOpenChange`. */
  onOpenChange?: ((open: boolean) => void) | undefined;
}

export interface UseCustomSelectResult {
  /** Colon-free id prefix for the trigger/menu/option ids. */
  idBase: string;
  buttonRef: MutableRefObject<HTMLButtonElement | null>;
  menuRef: MutableRefObject<HTMLDivElement | null>;
  open: boolean;
  activeValue: string;
  position: CustomSelectMenuPosition | null;
  /** Label to show on the trigger (selected option, else placeholder, else value). */
  selectedLabel: string;
  /** Maps each option value to its stable DOM id. */
  optionIdByValue: Map<string, string>;
  /** `aria-activedescendant` for the trigger, or `undefined` when none. */
  activeOptionId: string | undefined;
  /** Recompute the portal menu position from the live trigger rect. */
  updatePosition: () => void;
  /** Commit a value (ignoring missing/disabled), close, and refocus the trigger. */
  choose: (nextValue: string) => void;
  /** Set the active (highlighted) option value. */
  setActiveValue: (value: string) => void;
  /** Toggle the menu open/closed. */
  toggleOpen: () => void;
  /** Full keyboard handler for the trigger button. */
  onButtonKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  /** Escape handler for the menu container — closes even when focus is inside
   *  custom `menuHeader` content. See this function's definition for why
   *  `onButtonKeyDown` alone is not enough. */
  onMenuKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void;
}

/**
 * All of CustomSelect's behavior — ids, refs, open/active/position state, the
 * portal-positioning effect, the open/value active-option reconciliation
 * effect, the outside-click + scroll/resize effect, and the choose/keyboard
 * handlers — with no rendering. Exported (with the pure helpers above) so the
 * logic is testable in isolation from the DOM; `CustomSelect` is the dumb
 * consumer.
 */
export function useCustomSelect({
  value,
  options,
  onChange,
  portal,
  placeholder,
  onOpenChange,
}: UseCustomSelectParams, _optional: Record<string, never> = {}): UseCustomSelectResult {
  const reactId = useId();
  const idBase = reactId.replace(/:/g, '');
  const wasOpenRef = useRef(false);
  const activeSourceValueRef = useRef(value);
  const [activeValue, setActiveValue] = useState(value);
  const popover = useSelectPopover({ measurePosition: ({ trigger }) => computeCustomSelectMenuPosition(
    trigger.getBoundingClientRect(), { width: window.innerWidth, height: window.innerHeight },
  ) }, { portal, onOpenChange });
  const { open, position, triggerRef: buttonRef, panelRef: menuRef, updatePosition } = popover;

  const flatOptions = useMemo(() => flattenCustomSelectOptions(options), [options]);
  const selected = flatOptions.find((option) => option.value === value);
  const selectedLabel = selected?.label ?? placeholder ?? value;
  const enabledOptions = useMemo(
    () => flatOptions.filter((option) => !option.disabled),
    [flatOptions],
  );
  const flatOptionsRef = useRef(flatOptions);
  const enabledOptionsRef = useRef(enabledOptions);
  flatOptionsRef.current = flatOptions;
  enabledOptionsRef.current = enabledOptions;
  const optionIdByValue = useMemo(
    () => new Map(flatOptions.map((option, index) => [option.value, `${idBase}-option-${index}`])),
    [flatOptions, idBase],
  );
  const activeOptionId = open && activeValue ? optionIdByValue.get(activeValue) : undefined;

  useEffect(() => {
    const result = reconcileCustomSelectActiveValue({
      open,
      value,
      wasOpen: wasOpenRef.current,
      activeSourceValue: activeSourceValueRef.current,
      flatOptions: flatOptionsRef.current,
      enabledOptions: enabledOptionsRef.current,
    });
    wasOpenRef.current = result.wasOpen;
    activeSourceValueRef.current = result.activeSourceValue;
    if (result.nextActiveValue !== undefined) setActiveValue(result.nextActiveValue);
  }, [open, value]);

  const choose = (nextValue: string) => {
    const next = flatOptions.find((option) => option.value === nextValue);
    if (!next || next.disabled) return;
    onChange(next.value);
    popover.closePanel({ refocusTrigger: true });
  };

  const moveActive = (direction: 1 | -1) => {
    const next = nextCustomSelectActiveValue(enabledOptions, activeValue, direction);
    if (next !== null) setActiveValue(next);
  };

  const toggleOpen = () => open ? popover.closePanel({ refocusTrigger: false }) : popover.openPanel();

  const onButtonKeyDown = (event: KeyboardEvent<HTMLButtonElement>) => {
    if (popover.handleDismissKey(event)) return;
    if (openSelectOnKey({ event, open, openPanel: popover.openPanel })) return;
    if (!open) return;
    applySelectNavigationKey({ key: event.key, actions: {
      preventDefault: () => event.preventDefault(), move: moveActive,
      edge: (edge) => setActiveValue((edge === 'first' ? enabledOptions[0] : enabledOptions.at(-1))?.value ?? ''),
      choose: () => choose(activeValue || value),
    } }, { spaceChooses: true });
  };

  // Escape closes even when focus has moved into custom `menuHeader` content
  // (e.g. `SearchableModelSelect`'s search input) — `onButtonKeyDown` alone
  // only fires while the TRIGGER itself has focus, which no longer holds once
  // the operator tabs or clicks into menu content that can actually receive
  // focus (unlike the option buttons, which are `tabIndex={-1}` and never
  // take real focus). Attached to the menu container, not the document, so it
  // never fires for an unrelated Escape press elsewhere on the page.
  const onMenuKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    popover.handleDismissKey(event);
  };

  return {
    idBase,
    buttonRef,
    menuRef,
    open,
    activeValue,
    position,
    selectedLabel,
    optionIdByValue,
    activeOptionId,
    updatePosition,
    choose,
    setActiveValue,
    toggleOpen,
    onButtonKeyDown,
    onMenuKeyDown,
  };
}

export interface CustomSelectOriginTheme {
  'data-admin-theme'?: string;
  'data-color-scheme'?: string;
  'data-theme'?: string;
}

/** Scheme attributes from one boundary node: canonical `data-color-scheme` wins; a legacy
 * `data-theme` supplies the scheme only when it is `light`/`dark`, but is always mirrored. */
function resolveCustomSelectSchemeAttributes({ canonical, legacy }: {
  canonical: string | null | undefined; legacy: string | null | undefined;
}): Pick<CustomSelectOriginTheme, 'data-color-scheme' | 'data-theme'> {
  const scheme = canonical ?? (legacy === 'light' || legacy === 'dark' ? legacy : undefined);
  return {
    ...(scheme ? { 'data-color-scheme': scheme } : {}),
    ...(canonical || legacy ? { 'data-theme': canonical ?? legacy! } : {}),
  };
}

/** Resolve theme identity and the nearest scheme separately, so a local light pin beats a dark root.
 * @complexity O(d) time, O(1) space for d DOM ancestors. No host-specific theme ids are needed. */
export function resolveCustomSelectOriginTheme({ trigger }: { trigger: HTMLElement | null }, _optional: Record<string, never> = {}): CustomSelectOriginTheme {
  const identity = trigger?.closest('[data-admin-theme]')?.getAttribute('data-admin-theme');
  const boundary = trigger?.closest('[data-color-scheme], [data-theme]');
  return {
    ...(identity ? { 'data-admin-theme': identity } : {}),
    ...resolveCustomSelectSchemeAttributes({
      canonical: boundary?.getAttribute('data-color-scheme'),
      legacy: boundary?.getAttribute('data-theme'),
    }),
  };
}

/**
 * The theme of the place this menu was opened FROM.
 *
 * A portalled menu is a child of `document.body`, so it escapes any `data-theme` set on an ancestor
 * of the trigger — and this package's theming works precisely by declaring `--jini-*` tokens on
 * `[data-theme='light']` / `[data-theme='dark']`. A host that pins a theme on a WRAPPER rather than
 * on `document.documentElement` therefore gets a correctly-themed control and a menu themed by
 * whatever the document happens to be.
 *
 * Measured in a host admin that is light-only and pins `data-theme="light"` on its panel wrapper:
 * on a machine set to dark, the trigger rendered light and its own dropdown rendered dark — one
 * control, two themes, four pixels apart. The host cannot fix that from CSS either, because the
 * tokens resolve on the portal node's ancestors, which it has no way to select.
 *
 * So the menu carries its origin's theme with it. The nearest scheme boundary wins, with
 * canonical `data-color-scheme` taking precedence over legacy `data-theme` on the same node.
 * Theme identity is independent of scheme. Observe the trigger's ancestors while open so a
 * host's live theme/scheme change updates an existing portal too. With neither attribute, leave
 * document-level theming untouched. Only applied when portalling — an inline menu is still
 * inside the subtree and inherits correctly on its own.
 * @complexity O(d) time/observer storage for d ancestors; disposed on close or unmount.
 */
export function useCustomSelectOriginTheme({ buttonRef, open, portal }: {
  buttonRef: MutableRefObject<HTMLButtonElement | null>; open: boolean; portal: boolean;
}, _optional: Record<string, never> = {}): CustomSelectOriginTheme {
  const [attributes, setAttributes] = useState<CustomSelectOriginTheme>({});
  useLayoutEffect(() => {
    if (!open || !portal) return undefined;
    const update = () => {
      const next = resolveCustomSelectOriginTheme({ trigger: buttonRef.current });
      setAttributes((current) => current['data-admin-theme'] === next['data-admin-theme']
        && current['data-color-scheme'] === next['data-color-scheme']
        && current['data-theme'] === next['data-theme'] ? current : next);
    };
    update();
    const observer = new MutationObserver(update);
    // Observe only the origin chain, not portal nodes: copying attributes must not retrigger itself.
    for (let node: HTMLElement | null = buttonRef.current; node; node = node.parentElement) {
      observer.observe(node, { attributes: true, attributeFilter: ['data-admin-theme', 'data-color-scheme', 'data-theme'] });
    }
    return () => observer.disconnect();
  }, [buttonRef, open, portal]);
  return portal ? attributes : {};
}

/** Inline geometry for a portalled menu once it has been measured; an inline menu is laid out by CSS. */
function customSelectMenuStyle({ portal, position }: {
  portal: boolean; position: CustomSelectMenuPosition | null;
}): CSSProperties | undefined {
  return portal && position
    ? {
        top: position.top,
        left: position.left,
        width: position.width,
        maxHeight: position.maxHeight,
      }
    : undefined;
}

/** Where an open menu renders: inline, or portalled only after its first measurement. */
function mountCustomSelectMenu({ menu, portal, position, trigger }: {
  menu: ReactNode; portal: boolean; position: CustomSelectMenuPosition | null; trigger: HTMLElement | null;
}, { container, fallbackContainer }: { container?: Element | DocumentFragment | null | undefined; fallbackContainer?: Element | DocumentFragment | null | undefined } = {}): ReactNode {
  if (!portal) return menu;
  return position ? createPortal(menu, resolveSelectPortalContainer({ trigger }, { container, fallbackContainer })) : null;
}

/** The listbox rows: groups render a labelled block of option buttons, flat options render directly. */
function CustomSelectMenuOptions({ options, value, activeValue, optionIdByValue, onChoose, onActive, base }: {
  base: string | undefined;
  options: CustomSelectProps['options'];
  value: string;
  activeValue: string;
  optionIdByValue: Map<string, string>;
  onChoose: (value: string) => void;
  onActive: (value: string) => void;
}) {
  const renderOption = (option: CustomSelectOption) => (
    <CustomSelectOptionButton
      key={option.value}
      option={option}
      agentHandle={base ? `${base}-option-${agentHandleSegment({ value: option.value })}` : false}
      selected={option.value === value}
      active={option.value === activeValue}
      id={optionIdByValue.get(option.value)}
      onChoose={onChoose}
      onActive={onActive}
    />
  );
  return (
    <>
      {options.map((item) => (isCustomSelectGroup(item) ? (
        <div className="jini-select-group" key={`group:${item.label}`}>
          <div className="jini-select-group-label">{item.label}</div>
          {item.options.map(renderOption)}
        </div>
      ) : renderOption(item)))}
    </>
  );
}

/**
 * Accessible custom `<select>` replacement with grouped options, full keyboard
 * navigation, and an optional portal-rendered menu. All behavior lives in
 * {@link useCustomSelect}; this component only wires the hook's state to the
 * trigger button and the listbox menu.
 */
export function CustomSelect({
  value,
  options,
  onChange,
  ariaLabel,
  labelledBy,
  className,
  triggerClassName,
  menuClassName,
  disabled = false,
  placeholder,
  portal = true,
  portalContainer,
  title,
  onFocus,
  menuHeader,
  onOpenChange,
  useCustomSelect: useCustomSelectHook = useCustomSelect,
  ...agentProps
}: CustomSelectProps) {
  const {
    idBase,
    buttonRef,
    menuRef,
    open,
    activeValue,
    position,
    selectedLabel,
    optionIdByValue,
    activeOptionId,
    choose,
    setActiveValue,
    toggleOpen,
    onButtonKeyDown,
    onMenuKeyDown,
  } = useCustomSelectHook({ value, options, onChange, portal, placeholder, onOpenChange });

  const base = useAgentHandle(agentProps);
  const overlayContainer = useOverlayContainer({});
  const originPage = agentProps['data-agent-page'] ?? resolveSelectOriginPage({ trigger: buttonRef.current });
  const originTheme = useCustomSelectOriginTheme({ buttonRef, open, portal });

  const menu = (
    <div
      ref={menuRef}
      id={`${idBase}-menu`}
      onKeyDown={onMenuKeyDown}
      {...originTheme}
      data-agent-page={originPage}
      data-agent-private={agentProps['data-agent-private']}
      className={[
        'jini-select-menu',
        portal ? 'portal' : 'inline',
        menuClassName,
      ].filter(Boolean).join(' ')}
      role="listbox"
      aria-label={ariaLabel}
      style={customSelectMenuStyle({ portal, position })}
    >
      {menuHeader}
      <CustomSelectMenuOptions
        base={base}
        options={options}
        value={value}
        activeValue={activeValue}
        optionIdByValue={optionIdByValue}
        onChoose={choose}
        onActive={setActiveValue}
      />
    </div>
  );

  return (
    <div className={['jini-select', className].filter(Boolean).join(' ')}>
      <button
        ref={buttonRef}
        {...agentHandleProps({}, { base, role: 'field', label: ariaLabel })}
        data-agent-private={agentProps['data-agent-private']}
        data-agent-page={agentProps['data-agent-page']}
        type="button"
        className={['jini-select-trigger', triggerClassName].filter(Boolean).join(' ')}
        role="combobox"
        value={value}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${idBase}-menu`}
        aria-activedescendant={activeOptionId}
        aria-describedby={labelledBy}
        aria-label={`${ariaLabel}: ${selectedLabel}`}
        disabled={disabled}
        title={title}
        onClick={toggleOpen}
        onKeyDown={onButtonKeyDown}
        onFocus={onFocus}
      >
        <span id={`${idBase}-value`} className="jini-select-value">
          {selectedLabel}
        </span>
        <Icon name="chevron-down" size={14} />
      </button>
      {open ? mountCustomSelectMenu({ menu, portal, position, trigger: buttonRef.current }, { container: portalContainer, fallbackContainer: overlayContainer }) : null}
    </div>
  );
}

/** One row in the listbox: a selectable option button that reports hover
 * (activation) and click (choice) back to {@link CustomSelect}. */
export function CustomSelectOptionButton({
  option,
  selected,
  active,
  id,
  onChoose,
  onActive,
  agentHandle,
}: {
  agentHandle?: string | false | undefined;
  option: CustomSelectOption;
  selected: boolean;
  active: boolean;
  id: string | undefined;
  onChoose: (value: string) => void;
  onActive: (value: string) => void;
}) {
  const base = useAgentHandle({ agentHandle });
  return (
    <button
      {...agentHandleProps({}, { base, role: 'button', label: option.label })}
      id={id}
      type="button"
      className={[
        'jini-select-option',
        selected ? 'selected' : '',
        active ? 'active' : '',
      ].filter(Boolean).join(' ')}
      role="option"
      aria-selected={selected}
      tabIndex={-1}
      disabled={option.disabled}
      onMouseEnter={() => onActive(option.value)}
      onClick={() => onChoose(option.value)}
    >
      <span className="jini-select-option-label">{option.label}</span>
      <span className="jini-select-option-check" aria-hidden>
        <Icon name="check" size={13} />
      </span>
    </button>
  );
}

// Searchable/multi-select dropdown with viewport-aware flip placement,
// click-outside/Escape dismiss, and single-open-at-a-time coordination
// across multiple mounted instances (via a broadcast `window` event).
// Origin: `OnboardingDropdown` in `EntryShell.tsx` (OD). Only the
// `options` shape's optional `meta`/`tag` fields were OD-flavored in the
// recon read; this port keeps the plain `{ value, label }` shape actually
// used by the component. Genericized:
//  - The peer-coordination event name was a product-identity string
//    (`'open-design:onboarding-dropdown-open'`); renamed to
//    `'jini-ui:onboarding-dropdown-open'`.
//  - The two hardcoded empty-state i18n keys
//    (`'homeHero.footer.noMatches'` / `'settings.fetchModelsEmpty'`, OD's
//    own dictionary keys) are replaced with plain-English strings routed
//    through this package's own `useT()` — `'No matches'` for a searchable
//    field with no query hits, and a new, non-model-specific `'No options
//    available'` for an empty non-searchable field (the origin's fallback
//    text talked about "text models", which was itself a leftover from the
//    one call site it happened to serve, not a generic empty state).
// See packages/ui/source-map.md.
//
// Shape: this module follows the package's "dumb component + co-located
// testable hooks" pattern (see `TooltipLayer.tsx`). All state, refs,
// effects, and DOM measurement live in exported hooks
// ({@link useOnboardingDropdown}, {@link useOnboardingDropdownPlacement});
// all branchy derivations live in exported pure helpers
// ({@link resolveOnboardingSelectedValues}, {@link resolveOnboardingTriggerLabel},
// {@link filterOnboardingOptions}, {@link resolveOnboardingMenuMetrics},
// {@link onboardingEmptyMessageKey}). `OnboardingDropdown` is the dumb
// consumer that only renders.

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { CSSProperties, RefObject } from 'react';
import { useT } from '../../features/i18n/index.js';
import { Icon } from './Icon.js';

export const ONBOARDING_DROPDOWN_OPEN_EVENT = 'jini-ui:onboarding-dropdown-open';

/** Vertical space (px) below the trigger under which the menu prefers to flip up. */
export const ONBOARDING_MENU_FLIP_THRESHOLD = 260;
/** Menu height (px) clamp: never taller than this. */
export const ONBOARDING_MENU_MAX_HEIGHT = 240;
/** Menu height (px) clamp: never shorter than this. */
export const ONBOARDING_MENU_MIN_HEIGHT = 48;
/** Padding (px) subtracted from the available space when sizing the menu. */
export const ONBOARDING_MENU_VIEWPORT_PADDING = 16;
/** Viewport height (px) assumed when neither `innerHeight` nor `clientHeight` is available. */
export const ONBOARDING_MENU_FALLBACK_VIEWPORT = 720;

export type OnboardingDropdownPlacement = 'bottom' | 'top';

export interface OnboardingDropdownOption {
  value: string;
  label: string;
}

interface OnboardingDropdownBaseProps {
  label: string;
  placeholder: string;
  options: OnboardingDropdownOption[];
  placement?: OnboardingDropdownPlacement;
  searchable?: boolean;
  searchPlaceholder?: string;
  sourceTone?: string;
  className?: string;
  /** Custom hook override for dependency injection / testing. */
  useOnboardingDropdown?: typeof useOnboardingDropdown;
}

export type OnboardingDropdownProps =
  | (OnboardingDropdownBaseProps & {
      value: string;
      onChange: (value: string) => void;
      multiple?: false;
    })
  | (OnboardingDropdownBaseProps & {
      value: string[];
      onChange: (value: string[]) => void;
      multiple: true;
    });

// ---------------------------------------------------------------------------
// Pure helpers (module-level, no React) — each isolates one branchy decision.
// ---------------------------------------------------------------------------

/**
 * Normalize the polymorphic `value` prop into a flat array of selected values.
 * An array passes through; a non-empty string becomes a singleton; an empty
 * string (or otherwise falsy value) becomes an empty selection.
 */
export function resolveOnboardingSelectedValues(value: string | string[]): string[] {
  if (Array.isArray(value)) return value;
  return value ? [value] : [];
}

/**
 * Compute the trigger's visible label. In multiple mode it joins every
 * selected option's label; in single mode it uses the first selected label.
 * Falls back to `placeholder` when nothing resolves.
 */
export function resolveOnboardingTriggerLabel(
  selectedOptions: OnboardingDropdownOption[],
  multiple: boolean,
  placeholder: string,
): string {
  const selectedLabel = multiple
    ? selectedOptions.map((option) => option.label).join(', ')
    : selectedOptions[0]?.label;
  return selectedLabel || placeholder;
}

/**
 * Filter the option list for the menu. When not searchable, or when the query
 * is blank, every option is returned. Otherwise options are matched
 * case-insensitively against their `label` and `value`.
 */
export function filterOnboardingOptions(
  options: OnboardingDropdownOption[],
  query: string,
  searchable: boolean,
): OnboardingDropdownOption[] {
  const normalizedQuery = query.trim().toLowerCase();
  if (!searchable || !normalizedQuery) return options;
  return options.filter((option) =>
    `${option.label} ${option.value}`.toLowerCase().includes(normalizedQuery),
  );
}

/** The (untranslated) empty-state key for the current field mode. */
export function onboardingEmptyMessageKey(searchable: boolean): string {
  return searchable ? 'No matches' : 'No options available';
}

export interface OnboardingDropdownMenuMetrics {
  placement: OnboardingDropdownPlacement;
  maxHeight: number;
}

/**
 * Decide where the menu opens and how tall it may be, given the trigger's
 * bounding rect and the viewport height. Prefers the caller's requested
 * placement, but flips to `top` when the space below the trigger is tight
 * (< {@link ONBOARDING_MENU_FLIP_THRESHOLD}) and there is more room above.
 * The height is clamped to
 * [{@link ONBOARDING_MENU_MIN_HEIGHT}, {@link ONBOARDING_MENU_MAX_HEIGHT}].
 */
export function resolveOnboardingMenuMetrics(
  rect: { top: number; bottom: number },
  viewportHeight: number,
  requestedPlacement: OnboardingDropdownPlacement,
): OnboardingDropdownMenuMetrics {
  const spaceBelow = viewportHeight - rect.bottom;
  const spaceAbove = rect.top;
  const placement =
    requestedPlacement === 'top' || (spaceBelow < ONBOARDING_MENU_FLIP_THRESHOLD && spaceAbove > spaceBelow)
      ? 'top'
      : 'bottom';
  const availableSpace = placement === 'top' ? spaceAbove : spaceBelow;
  const maxHeight = Math.max(
    ONBOARDING_MENU_MIN_HEIGHT,
    Math.min(ONBOARDING_MENU_MAX_HEIGHT, availableSpace - ONBOARDING_MENU_VIEWPORT_PADDING),
  );
  return { placement, maxHeight };
}

/** Read the current viewport height with progressive fallbacks. */
export function readOnboardingViewportHeight(): number {
  return (
    window.innerHeight ||
    document.documentElement.clientHeight ||
    ONBOARDING_MENU_FALLBACK_VIEWPORT
  );
}

// ---------------------------------------------------------------------------
// Hooks
// ---------------------------------------------------------------------------

/**
 * Measure the trigger and derive the menu's resolved placement + max height
 * whenever the menu is open, keeping it in sync with `resize`/`scroll`. All
 * arithmetic is delegated to {@link resolveOnboardingMenuMetrics}; this hook
 * only owns the DOM measurement and the listener lifecycle. Measurement is a
 * no-op until the ref is attached, so consumers that open before the field
 * mounts (or exercise the hook in isolation) never dereference a null node.
 */
export function useOnboardingDropdownPlacement(
  rootRef: RefObject<HTMLDivElement | null>,
  open: boolean,
  placement: OnboardingDropdownPlacement,
  optionCount: number,
): OnboardingDropdownMenuMetrics {
  const [metrics, setMetrics] = useState<OnboardingDropdownMenuMetrics>({
    placement,
    maxHeight: ONBOARDING_MENU_MAX_HEIGHT,
  });

  useLayoutEffect(() => {
    if (!open) return undefined;

    function measureMenu() {
      const node = rootRef.current;
      if (!node) return;
      const rect = node.getBoundingClientRect();
      setMetrics(resolveOnboardingMenuMetrics(rect, readOnboardingViewportHeight(), placement));
    }

    measureMenu();
    window.addEventListener('resize', measureMenu);
    window.addEventListener('scroll', measureMenu, true);
    return () => {
      window.removeEventListener('resize', measureMenu);
      window.removeEventListener('scroll', measureMenu, true);
    };
  }, [open, placement, optionCount, rootRef]);

  return metrics;
}

export interface UseOnboardingDropdownResult {
  /** Whether the menu is currently open. */
  open: boolean;
  /** Current search query (only meaningful when `searchable`). */
  query: string;
  /** Update the search query. */
  setQuery: (value: string) => void;
  /** Toggle the menu; opening broadcasts the single-open peer event. */
  toggleOpen: () => void;
  /** Attach to the field root; used for click-outside detection + measurement. */
  rootRef: RefObject<HTMLDivElement | null>;
  /** Placement after viewport-aware flip. */
  resolvedPlacement: OnboardingDropdownPlacement;
  /** Menu max height (px) after clamping to available space. */
  menuMaxHeight: number;
  /** Flat list of currently selected values. */
  selectedValues: string[];
  /** Whether any option is selected. */
  hasValue: boolean;
  /** The label shown on the trigger button. */
  triggerLabel: string;
  /** Options to render in the menu (query-filtered when searchable). */
  visibleOptions: OnboardingDropdownOption[];
  /** Translated empty-state copy for the current mode. */
  emptyMessage: string;
  /**
   * Apply an option click: in multiple mode this toggles the value (staying
   * open); in single mode it selects and closes.
   */
  selectOption: (option: OnboardingDropdownOption, selected: boolean) => void;
}

/**
 * All of the dropdown's behavior — open/query state, the field ref, the
 * viewport-aware placement, the click-outside/Escape dismissal, the query
 * reset on close, the single-open-at-a-time peer coordination, and the
 * select/toggle logic — with no rendering. Exported (with the pure helpers
 * above) so the logic is testable in isolation; `OnboardingDropdown` is the
 * dumb consumer.
 */
export function useOnboardingDropdown(props: OnboardingDropdownProps): UseOnboardingDropdownResult {
  const t = useT();
  const {
    placeholder,
    value,
    options,
    placement = 'bottom',
    multiple = false,
    searchable = false,
  } = props;

  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const rootRef = useRef<HTMLDivElement | null>(null);
  const dropdownIdRef = useRef(`onboarding-dropdown-${globalThis.crypto.getRandomValues(new Uint32Array(1))[0]!.toString(36)}`);

  const { placement: resolvedPlacement, maxHeight: menuMaxHeight } = useOnboardingDropdownPlacement(
    rootRef,
    open,
    placement,
    options.length,
  );

  useEffect(() => {
    if (!open) return undefined;

    function handlePointerDown(event: PointerEvent) {
      if (!rootRef.current?.contains(event.target as Node)) {
        setOpen(false);
      }
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setOpen(false);
      }
    }

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('pointerdown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [open]);

  useEffect(() => {
    if (!open) {
      setQuery('');
    }
  }, [open]);

  useEffect(() => {
    function handlePeerOpen(event: Event) {
      if ((event as CustomEvent<string>).detail !== dropdownIdRef.current) {
        setOpen(false);
      }
    }

    window.addEventListener(ONBOARDING_DROPDOWN_OPEN_EVENT, handlePeerOpen);
    return () => {
      window.removeEventListener(ONBOARDING_DROPDOWN_OPEN_EVENT, handlePeerOpen);
    };
  }, []);

  const toggleOpen = useCallback(() => {
    setOpen((current) => {
      const nextOpen = !current;
      if (nextOpen) {
        window.dispatchEvent(
          new CustomEvent(ONBOARDING_DROPDOWN_OPEN_EVENT, {
            detail: dropdownIdRef.current,
          }),
        );
      }
      return nextOpen;
    });
  }, []);

  const selectedValues = resolveOnboardingSelectedValues(value);
  const selectedOptions = options.filter((option) => selectedValues.includes(option.value));
  const hasValue = selectedOptions.length > 0;
  const triggerLabel = resolveOnboardingTriggerLabel(selectedOptions, multiple, placeholder);
  const visibleOptions = filterOnboardingOptions(options, query, searchable);
  const emptyMessage = t(onboardingEmptyMessageKey(searchable));

  function selectOption(option: OnboardingDropdownOption, selected: boolean) {
    if (props.multiple) {
      props.onChange(
        selected
          ? selectedValues.filter((selectedValue) => selectedValue !== option.value)
          : [...selectedValues, option.value],
      );
      return;
    }
    props.onChange(option.value);
    setOpen(false);
  }

  return {
    open,
    query,
    setQuery,
    toggleOpen,
    rootRef,
    resolvedPlacement,
    menuMaxHeight,
    selectedValues,
    hasValue,
    triggerLabel,
    visibleOptions,
    emptyMessage,
    selectOption,
  };
}

// ---------------------------------------------------------------------------
// Dumb component
// ---------------------------------------------------------------------------

function OnboardingDropdownSearch({ query, setQuery, placeholder, label }: {
  query: string;
  setQuery: (value: string) => void;
  placeholder: string;
  label: string;
}) {
  return (
    <label
      className="onboarding-view__select-search"
      onClick={(event) => event.stopPropagation()}
    >
      <Icon name="search" size={14} />
      <input
        type="search"
        value={query}
        placeholder={placeholder}
        aria-label={label}
        autoFocus
        onChange={(event) => setQuery(event.target.value)}
        onKeyDown={(event) => {
          if (event.key !== 'Escape') {
            event.stopPropagation();
          }
        }}
      />
    </label>
  );
}

function OnboardingDropdownOptionButton({ option, selected, selectOption }: {
  option: OnboardingDropdownOption;
  selected: boolean;
  selectOption: UseOnboardingDropdownResult['selectOption'];
}) {
  return (
    <button
      type="button"
      className={`onboarding-view__select-option${selected ? ' is-selected' : ''}`}
      role="option"
      aria-selected={selected}
      onClick={() => selectOption(option, selected)}
    >
      <span>{option.label}</span>
      {selected ? <Icon name="check" size={15} /> : null}
    </button>
  );
}

function OnboardingDropdownOptions({ label, multiple, visibleOptions, selectedValues, emptyMessage, selectOption }: {
  label: string;
  multiple: boolean;
} & Pick<UseOnboardingDropdownResult, 'visibleOptions' | 'selectedValues' | 'emptyMessage' | 'selectOption'>) {
  return (
    <div
      className="onboarding-view__select-options"
      role="listbox"
      aria-label={label}
      aria-multiselectable={multiple || undefined}
    >
      {visibleOptions.map((option) => (
        <OnboardingDropdownOptionButton
          key={option.value}
          option={option}
          selected={selectedValues.includes(option.value)}
          selectOption={selectOption}
        />
      ))}
      {visibleOptions.length === 0 ? (
        <div className="onboarding-view__select-empty">{emptyMessage}</div>
      ) : null}
    </div>
  );
}

function OnboardingDropdownTrigger({ open, hasValue, triggerLabel, toggleOpen }: Pick<UseOnboardingDropdownResult, 'open' | 'hasValue' | 'triggerLabel' | 'toggleOpen'>) {
  return (
    <button
      type="button"
      className={`onboarding-view__select-trigger${open ? ' is-open' : ''}${
        hasValue ? ' has-value' : ''
      }`}
      aria-haspopup="listbox"
      aria-expanded={open}
      title={triggerLabel}
      onClick={toggleOpen}
    >
      <span>{triggerLabel}</span>
      <Icon name="chevron-down" size={16} />
    </button>
  );
}

function OnboardingDropdownMenu({ label, placeholder, multiple, searchable, searchPlaceholder, query, setQuery, menuMaxHeight, ...listProps }: {
  label: string;
  placeholder: string;
  multiple: boolean;
  searchable: boolean;
  searchPlaceholder: string | undefined;
} & Pick<UseOnboardingDropdownResult, 'query' | 'setQuery' | 'menuMaxHeight' | 'visibleOptions' | 'selectedValues' | 'emptyMessage' | 'selectOption'>) {
  return (
    <div
      className="onboarding-view__select-menu"
      data-searchable={searchable || undefined}
      style={{ '--onboarding-select-menu-max-height': `${menuMaxHeight}px` } as CSSProperties}
    >
      {searchable ? (
        <OnboardingDropdownSearch
          query={query}
          setQuery={setQuery}
          placeholder={searchPlaceholder || placeholder}
          label={searchPlaceholder || label}
        />
      ) : null}
      <OnboardingDropdownOptions label={label} multiple={multiple} {...listProps} />
    </div>
  );
}

/**
 * Searchable/multi-select onboarding dropdown. All behavior lives in
 * {@link useOnboardingDropdown}; this component only renders the field,
 * trigger, and (when open) the menu.
 */
export function OnboardingDropdown(props: OnboardingDropdownProps) {
  const {
    label,
    placeholder,
    multiple = false,
    searchable = false,
    searchPlaceholder,
    sourceTone,
    className,
    useOnboardingDropdown: useOnboardingDropdownHook = useOnboardingDropdown,
  } = props;

  const {
    open,
    query,
    setQuery,
    toggleOpen,
    rootRef,
    resolvedPlacement,
    menuMaxHeight,
    selectedValues,
    hasValue,
    triggerLabel,
    visibleOptions,
    emptyMessage,
    selectOption,
  } = useOnboardingDropdownHook(props);

  return (
    <div
      className={['onboarding-view__select-field', className].filter(Boolean).join(' ')}
      data-placement={resolvedPlacement}
      data-open={open || undefined}
      ref={rootRef}
    >
      <span
        className="onboarding-view__select-label"
        data-source-tone={sourceTone || undefined}
      >
        {label}
      </span>
      <OnboardingDropdownTrigger open={open} hasValue={hasValue} triggerLabel={triggerLabel} toggleOpen={toggleOpen} />
      {open ? (
        <OnboardingDropdownMenu
          label={label}
          placeholder={placeholder}
          multiple={multiple}
          searchable={searchable}
          searchPlaceholder={searchPlaceholder}
          query={query}
          setQuery={setQuery}
          menuMaxHeight={menuMaxHeight}
          visibleOptions={visibleOptions}
          selectedValues={selectedValues}
          emptyMessage={emptyMessage}
          selectOption={selectOption}
        />
      ) : null}
    </div>
  );
}

// NOTE: verified zero real consumers in the vendored source snapshot before
// porting (see packages/ui/source-map.md) — shipped anyway since it's small,
// self-contained, and correct.
//
// Structure follows the "dumb component + co-located testable hook(s)"
// pattern (see TooltipLayer.tsx): pure derivations are module-level helpers,
// all state/effects/callbacks live in exported hooks, and `PaletteTweaks`
// itself is a pure render. Everything is exported so each seam is unit- or
// hook-testable in isolation.

import { useCallback, useEffect, useRef, useState, type MutableRefObject } from 'react';
import { Icon } from './Icon.js';

export type PaletteId =
  | 'coral'
  | 'electric'
  | 'acid-forest'
  | 'risograph'
  | 'mono-noir';

/** A hover target inside the picker: a palette, the "original" row, or none. */
export type PaletteHoverTarget = PaletteId | 'original' | null;

export interface PaletteSwatch {
  id: PaletteId;
  label: string;
  stripe: string[];
}

const PRIMARY = 'var(--jini-primary)';

export const PALETTE_TWEAKS_SWATCHES: PaletteSwatch[] = [
  { id: 'coral',       label: 'Coral - default', stripe: [PRIMARY, PRIMARY, PRIMARY, PRIMARY] },
  { id: 'electric',    label: 'Electric',        stripe: [PRIMARY, PRIMARY, PRIMARY, PRIMARY] },
  { id: 'acid-forest', label: 'Acid forest',     stripe: [PRIMARY, PRIMARY, PRIMARY, PRIMARY] },
  { id: 'risograph',   label: 'Risograph',       stripe: [PRIMARY, PRIMARY, PRIMARY, PRIMARY] },
  { id: 'mono-noir',   label: 'Mono noir',       stripe: ['var(--jini-text)', PRIMARY, PRIMARY, PRIMARY] },
];

export interface PaletteTweaksProps {
  open: boolean;
  selected: PaletteId | null;
  onChange: (id: PaletteId | null) => void;
  onPreview: (id: PaletteId | null) => void;
  onClose: () => void;
}

// --- Pure derivations (module-level, directly unit-testable) --------------

/**
 * The palette to preview for a given hover target: the "original" row previews
 * nothing (`null`), leaving the row (target `null`) restores the current
 * `selected` preview, and hovering a palette previews that palette.
 */
export function resolvePalettePreview(
  target: PaletteHoverTarget,
  selected: PaletteId | null,
): PaletteId | null {
  if (target === 'original') return null;
  if (target === null) return selected;
  return target;
}

/**
 * The next selection when a palette row is clicked: clicking the already
 * selected palette deselects it (back to `null`), otherwise it selects it.
 */
export function nextPaletteSelection(
  selected: PaletteId | null,
  id: PaletteId,
): PaletteId | null {
  return selected === id ? null : id;
}

/** The `className` for a picker row, given its selected/hovered state. */
export function paletteItemClassName(state: {
  selected: boolean;
  hovered: boolean;
}): string {
  return `palette-tweaks-item${state.selected ? ' selected' : ''}${state.hovered ? ' hovered' : ''}`;
}

// --- Hooks (co-located, exported) -----------------------------------------

export interface UsePaletteHoverResult {
  /** The currently hovered target, or `null` when nothing is hovered. */
  hovered: PaletteHoverTarget;
  /** Set the hovered target and emit the corresponding preview. */
  setHover: (target: PaletteHoverTarget) => void;
}

/**
 * Owns the picker's hover state and the preview side effect. Setting a hover
 * target emits the resolved preview; closing the picker (`open` -> false)
 * clears the hover and cancels any active preview.
 */
export function usePaletteHover(options: {
  open: boolean;
  selected: PaletteId | null;
  onPreview: (id: PaletteId | null) => void;
}): UsePaletteHoverResult {
  const { open, selected, onPreview } = options;
  const [hovered, setHovered] = useState<PaletteHoverTarget>(null);

  const setHover = useCallback(
    (target: PaletteHoverTarget) => {
      setHovered(target);
      onPreview(resolvePalettePreview(target, selected));
    },
    [onPreview, selected],
  );

  useEffect(() => {
    if (!open) {
      setHovered(null);
      onPreview(null);
    }
  }, [open, onPreview]);

  return { hovered, setHover };
}

/**
 * Wires up dismiss behavior while the picker is `open`: a `mousedown` outside
 * the returned `rootRef` element, or pressing `Escape`, calls `onClose`.
 * Returns the ref to attach to the picker's root element.
 */
export function usePaletteDismiss(options: {
  open: boolean;
  onClose: () => void;
}): MutableRefObject<HTMLDivElement | null> {
  const { open, onClose } = options;
  const rootRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!open) return undefined;
    function onDoc(ev: MouseEvent) {
      if (!rootRef.current) return;
      if (rootRef.current.contains(ev.target as Node)) return;
      onClose();
    }
    function onKey(ev: KeyboardEvent) {
      if (ev.key === 'Escape') onClose();
    }
    document.addEventListener('mousedown', onDoc);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDoc);
      document.removeEventListener('keydown', onKey);
    };
  }, [open, onClose]);

  return rootRef;
}

// --- Dumb component --------------------------------------------------------

/**
 * Curated theme-palette picker. All state/effects live in
 * {@link usePaletteHover} and {@link usePaletteDismiss}; the row derivations
 * are module-level helpers. This component is a pure render.
 */
export function PaletteTweaks({ open, selected, onChange, onPreview, onClose }: PaletteTweaksProps) {
  const rootRef = usePaletteDismiss({ open, onClose });
  const { hovered, setHover } = usePaletteHover({ open, selected, onPreview });

  if (!open) return null;
  const isOriginal = selected === null;

  return (
    <div className="palette-tweaks" ref={rootRef} role="dialog" aria-label="Themes">
      <div className="palette-tweaks-header">
        <span className="palette-tweaks-title">Themes</span>
        <span className="palette-tweaks-sub">5 curated theme palettes</span>
      </div>
      <ul className="palette-tweaks-list" role="listbox">
        <li
          role="option"
          aria-selected={isOriginal}
          className={paletteItemClassName({ selected: isOriginal, hovered: hovered === 'original' })}
          onMouseEnter={() => setHover('original')}
          onMouseLeave={() => setHover(null)}
          onClick={() => { onChange(null); onClose(); }}
        >
          <span className="palette-tweaks-stripe palette-tweaks-stripe-original" aria-hidden>
            <span className="palette-tweaks-chip palette-tweaks-chip-original" />
          </span>
          <span className="palette-tweaks-label">Original</span>
          {isOriginal ? (
            <span className="palette-tweaks-check" aria-hidden>
              <Icon name="check" size={12} />
            </span>
          ) : null}
        </li>
        {PALETTE_TWEAKS_SWATCHES.map((p) => {
          const isSelected = selected === p.id;
          const isHovered = hovered === p.id;
          return (
            <li
              key={p.id}
              role="option"
              aria-selected={isSelected}
              className={paletteItemClassName({ selected: isSelected, hovered: isHovered })}
              onMouseEnter={() => setHover(p.id)}
              onMouseLeave={() => setHover(null)}
              onClick={() => {
                onChange(nextPaletteSelection(selected, p.id));
                onClose();
              }}
            >
              <span className="palette-tweaks-stripe" aria-hidden>
                {p.stripe.map((c, i) => (
                  <span key={i} className="palette-tweaks-chip" style={{ backgroundColor: c }} />
                ))}
              </span>
              <span className="palette-tweaks-label">{p.label}</span>
              {isSelected ? (
                <span className="palette-tweaks-check" aria-hidden>
                  <Icon name="check" size={12} />
                </span>
              ) : null}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type MutableRefObject,
} from 'react';
import { Icon } from './Icon.js';
import { withClassName } from '../../utils/class-names.js';

export type WorkingDirPlacement = 'down' | 'up';

export type WorkingDirLabels = Partial<{
  missing: string;
  hint: string;
  trigger: string;
  replace: string;
  pick: string;
  recent: string;
  recentEmpty: string;
  clear: string;
}>;

export interface WorkingDirPickerProps {
  /**
   * Currently selected local working directory shown inline with a clear
   * button, or null to show only the "select" label (e.g. when the selection
   * is surfaced elsewhere, like a project composer's linked-dir chips).
   */
  workingDir: string | null;
  /** Most-recently-used directories, most-recent-first. */
  recentDirs: string[];
  /** Open the native folder picker. */
  onPickDirectory: () => void;
  /** Re-select a previously used directory. */
  onSelectRecent: (dir: string) => void;
  /** Clear the current selection. Only reachable when `workingDir` is set. */
  onClear?: () => void;
  /** Extra class applied to the outer wrapper, for layout by the host. */
  className?: string;
  /** The selected directory no longer exists on disk — flag it in red. */
  invalid?: boolean;
  /**
   * Panel direction. `'down'` (default) suits a composer with room below;
   * `'up'` suits a composer whose trigger sits at the bottom of the
   * viewport, so a downward panel would be clipped.
   */
  placement?: WorkingDirPlacement;
  /** Fired when the panel opens, so the host can re-validate freshness. */
  onOpen?: () => void;
  /** Copy — all host-supplied, no built-in i18n. */
  labels?: WorkingDirLabels;
  /** Custom hook override for dependency injection / testing. */
  useWorkingDirPicker?: typeof useWorkingDirPicker;
}

export const DEFAULT_WORKING_DIR_LABELS = {
  missing: 'Directory no longer exists',
  hint: 'Select a working directory',
  trigger: 'Working directory',
  replace: 'Change folder',
  pick: 'Choose folder',
  recent: 'Recent folders',
  recentEmpty: 'No recent folders',
  clear: 'Clear',
};

export type ResolvedWorkingDirLabels = typeof DEFAULT_WORKING_DIR_LABELS;

/** Merge host label overrides onto the built-in English defaults. */
export function resolveWorkingDirLabels(labels?: WorkingDirLabels): ResolvedWorkingDirLabels {
  return { ...DEFAULT_WORKING_DIR_LABELS, ...labels };
}

/** Last path segment of a `/`- or `\`-separated dir; the whole input if empty. */
export function basename(dir: string): string {
  return dir.split(/[/\\]/).filter(Boolean).pop() ?? dir;
}

export interface UseDismissablePanelResult {
  /** Whether the panel is currently open. */
  open: boolean;
  /** Attach to the outer wrapper; an outside pointer press dismisses. */
  wrapRef: MutableRefObject<HTMLDivElement | null>;
  /** Flip open/closed; fires `onOpen` only on the closed→open edge. */
  toggle: () => void;
  /** Close the panel. */
  close: () => void;
}

/**
 * Owns the panel's open/closed boolean plus the "click outside or press
 * Escape to dismiss" behavior. While open, it listens on `document` for a
 * pointer press outside `wrapRef` or an Escape keypress and closes.
 * `toggle` flips the state and invokes `onOpen` only on the closed→open
 * transition. Exported so the behavior is testable without a render.
 */
export function useDismissablePanel(onOpen?: () => void): UseDismissablePanelResult {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement | null>(null);

  const close = useCallback(() => setOpen(false), []);
  // Read `open` directly and fire `onOpen` from this handler rather than from
  // inside the `setOpen` updater: an updater must stay a pure function of
  // previous state, and calling a caller-supplied callback there can run it
  // while React is mid-render of a different component (a synchronous
  // setState inside `onOpen` then trips "Cannot update a component while
  // rendering a different component"), and React may invoke an updater more
  // than once (e.g. StrictMode), which would fire `onOpen` twice.
  const toggle = useCallback(() => {
    const next = !open;
    setOpen(next);
    if (next) onOpen?.();
  }, [open, onOpen]);

  useEffect(() => {
    if (!open) return undefined;
    function onPointer(event: MouseEvent) {
      if (wrapRef.current?.contains(event.target as Node)) return;
      setOpen(false);
    }
    function onKey(event: KeyboardEvent) {
      if (event.key === 'Escape') setOpen(false);
    }
    document.addEventListener('mousedown', onPointer);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onPointer);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  return { open, wrapRef, toggle, close };
}

export interface UseRecentFlyoutResult {
  /** Whether the "Recent folders" flyout is expanded. */
  recentOpen: boolean;
  /** Expand the flyout. */
  show: () => void;
  /** Collapse the flyout. */
  hide: () => void;
  /** Toggle the flyout. */
  toggle: () => void;
}

/**
 * Owns the "Recent folders" flyout's open boolean. Auto-collapses whenever the
 * parent panel closes (`panelOpen` goes false), matching the original's
 * single-effect reset. Exported for isolated testing.
 */
export function useRecentFlyout(panelOpen: boolean): UseRecentFlyoutResult {
  const [recentOpen, setRecentOpen] = useState(false);
  useEffect(() => {
    if (!panelOpen) setRecentOpen(false);
  }, [panelOpen]);
  const show = useCallback(() => setRecentOpen(true), []);
  const hide = useCallback(() => setRecentOpen(false), []);
  const toggle = useCallback(() => setRecentOpen((v) => !v), []);
  return { recentOpen, show, hide, toggle };
}

export interface UseWorkingDirPickerInput {
  onPickDirectory: () => void;
  onSelectRecent: (dir: string) => void;
  // `| undefined` (not just `?`) so the component can forward its own optional
  // props straight through under `exactOptionalPropertyTypes`.
  onClear?: (() => void) | undefined;
  onOpen?: (() => void) | undefined;
  labels?: WorkingDirLabels | undefined;
}

export interface UseWorkingDirPickerResult {
  open: boolean;
  recentOpen: boolean;
  wrapRef: MutableRefObject<HTMLDivElement | null>;
  labels: ResolvedWorkingDirLabels;
  toggle: () => void;
  /** Close the panel, then open the native folder picker. */
  pick: () => void;
  /** Forward a recent dir to the host, then close the panel. */
  selectRecent: (dir: string) => void;
  /** Clear the selection (if a handler is supplied), then close the panel. */
  clear: () => void;
  showRecent: () => void;
  hideRecent: () => void;
  toggleRecent: () => void;
}

/**
 * Composes {@link useDismissablePanel} and {@link useRecentFlyout} and builds
 * the picker's action handlers (each closes the panel and forwards to the host
 * callback). `clear` tolerates a missing `onClear` — a defensive guard the
 * dumb component never reaches (it only renders the clear button when
 * `onClear` is set), but reachable directly through this hook.
 * {@link WorkingDirPicker} is the dumb consumer of this result.
 */
export function useWorkingDirPicker(input: UseWorkingDirPickerInput): UseWorkingDirPickerResult {
  const { onPickDirectory, onSelectRecent, onClear, onOpen, labels } = input;
  const panel = useDismissablePanel(onOpen);
  const flyout = useRecentFlyout(panel.open);
  const resolved = resolveWorkingDirLabels(labels);

  const pick = useCallback(() => {
    panel.close();
    onPickDirectory();
  }, [onPickDirectory, panel]);

  const selectRecent = useCallback((dir: string) => {
    onSelectRecent(dir);
    panel.close();
  }, [onSelectRecent, panel]);

  const clear = useCallback(() => {
    onClear?.();
    panel.close();
  }, [onClear, panel]);

  return {
    open: panel.open,
    recentOpen: flyout.recentOpen,
    wrapRef: panel.wrapRef,
    labels: resolved,
    toggle: panel.toggle,
    pick,
    selectRecent,
    clear,
    showRecent: flyout.show,
    hideRecent: flyout.hide,
    toggleRecent: flyout.toggle,
  };
}

const MENU_ITEM_SELECTOR = '[role="menuitem"]:not(:disabled)';
const RECENT_ITEM_SELECTOR = '[data-testid="working-dir-recent"]';
const RECENT_LIST_SELECTOR = '[data-testid="working-dir-recent-list"]';

/**
 * The menu item a navigation key moves focus to, or `null` for any other key. `count` is never 0:
 * the "Choose folder" item is always rendered and never disabled. ArrowUp from `currentIndex` -1
 * (focus on no menu item) yields `count - 2`, pinned as-is by the component tests.
 */
function resolveMenuNavigationIndex({ key, currentIndex, count }: { key: string; currentIndex: number; count: number }): number | null {
  if (key === 'Home') return 0;
  if (key === 'End') return count - 1;
  if (key === 'ArrowDown') return (currentIndex + 1 + count) % count;
  if (key === 'ArrowUp') return (currentIndex - 1 + count) % count;
  return null;
}

/** Arrow/Home/End roving focus across the panel's enabled menu items; true when the key was handled. */
function handleMenuNavigationKey({ event }: { event: ReactKeyboardEvent<HTMLDivElement> }): boolean {
  const menuItems = [...event.currentTarget.querySelectorAll<HTMLElement>(MENU_ITEM_SELECTOR)];
  const currentIndex = menuItems.indexOf(document.activeElement as HTMLElement);
  const nextIndex = resolveMenuNavigationIndex({ key: event.key, currentIndex, count: menuItems.length });
  if (nextIndex === null) return false;
  event.preventDefault();
  menuItems[nextIndex]?.focus();
  return true;
}

/** ArrowRight on "Recent folders" opens its flyout; ArrowLeft inside the flyout closes it again. */
function handleRecentFlyoutKey({ event, showRecent, hideRecent }: {
  event: ReactKeyboardEvent<HTMLDivElement>; showRecent: () => void; hideRecent: () => void;
}): void {
  const panel = event.currentTarget;
  if (event.key === 'ArrowRight' && event.target === panel.querySelector(RECENT_ITEM_SELECTOR)) {
    event.preventDefault();
    showRecent();
    window.setTimeout(() => {
      panel.querySelector<HTMLElement>(`${RECENT_LIST_SELECTOR} [role="menuitem"]`)?.focus();
    }, 0);
    return;
  }
  if (
    event.key === 'ArrowLeft'
    && event.target instanceof HTMLElement
    && event.target.closest(RECENT_LIST_SELECTOR)
  ) {
    event.preventDefault();
    hideRecent();
    panel.querySelector<HTMLElement>(RECENT_ITEM_SELECTOR)?.focus();
  }
}

/** Focus the first menu item on open; return focus to the trigger after the panel closes. */
function useWorkingDirFocusHandoff({ open, triggerRef, panelRef }: {
  open: boolean;
  triggerRef: MutableRefObject<HTMLButtonElement | null>;
  panelRef: MutableRefObject<HTMLDivElement | null>;
}): void {
  const wasOpenRef = useRef(false);
  useEffect(() => {
    if (open) {
      wasOpenRef.current = true;
      panelRef.current?.querySelector<HTMLElement>(MENU_ITEM_SELECTOR)?.focus();
      return undefined;
    }
    if (!wasOpenRef.current) return undefined;
    wasOpenRef.current = false;
    const timeout = window.setTimeout(() => triggerRef.current?.focus(), 0);
    return () => window.clearTimeout(timeout);
  }, [open, panelRef, triggerRef]);
}

function WorkingDirTrigger({ triggerRef, workingDir, invalid, open, panelId, t, toggle }: {
  triggerRef: MutableRefObject<HTMLButtonElement | null>;
  workingDir: string | null;
  invalid: boolean;
  open: boolean;
  panelId: string;
  t: ResolvedWorkingDirLabels;
  toggle: () => void;
}) {
  return (
    <div className="jini-working-dir-trigger-row">
      <button
        ref={triggerRef}
        type="button"
        className={`jini-working-dir-trigger${invalid ? ' invalid' : ''}`}
        data-testid="working-dir-trigger"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={panelId}
        title={invalid ? t.missing : (workingDir ?? t.hint)}
        onClick={toggle}
      >
        <Icon name="folder" size={13} className="jini-working-dir-trigger-icon" />
        <span className="jini-working-dir-trigger-label">
          {workingDir ? basename(workingDir) : t.trigger}
        </span>
        <Icon name="chevron-down" size={11} className="jini-working-dir-trigger-chevron" />
      </button>
    </div>
  );
}

function WorkingDirRecentFlyout({ recentDirs, placement, t, selectRecent }: {
  recentDirs: string[];
  placement: WorkingDirPlacement;
  t: ResolvedWorkingDirLabels;
  selectRecent: (dir: string) => void;
}) {
  return (
    <div
      className={`jini-working-dir-flyout${placement === 'up' ? ' up' : ''}`}
      role="menu"
      data-testid="working-dir-recent-list"
    >
      {recentDirs.length === 0 ? (
        <div className="jini-working-dir-empty">{t.recentEmpty}</div>
      ) : (
        recentDirs.map((dir) => (
          <button
            key={dir}
            type="button"
            role="menuitem"
            className="jini-working-dir-recent-item"
            title={dir}
            onClick={() => selectRecent(dir)}
          >
            <Icon name="folder" size={13} className="jini-working-dir-item-icon" />
            <span className="jini-working-dir-recent-name">{basename(dir)}</span>
            <span className="jini-working-dir-recent-path">{dir}</span>
          </button>
        ))
      )}
    </div>
  );
}

function WorkingDirPanel({ panelRef, panelId, placement, workingDir, recentDirs, canClear, t, picker, onKeyDown }: {
  panelRef: MutableRefObject<HTMLDivElement | null>;
  panelId: string;
  placement: WorkingDirPlacement;
  workingDir: string | null;
  recentDirs: string[];
  canClear: boolean;
  t: ResolvedWorkingDirLabels;
  picker: Pick<UseWorkingDirPickerResult, 'recentOpen' | 'pick' | 'selectRecent' | 'clear' | 'showRecent' | 'hideRecent' | 'toggleRecent'>;
  onKeyDown: (event: ReactKeyboardEvent<HTMLDivElement>) => void;
}) {
  const { recentOpen, pick, selectRecent, clear, showRecent, hideRecent, toggleRecent } = picker;
  return (
    <div
      ref={panelRef}
      id={panelId}
      className={`jini-working-dir-panel${placement === 'up' ? ' up' : ''}`}
      role="menu"
      data-testid="working-dir-panel"
      onKeyDown={onKeyDown}
    >
      <button
        type="button"
        role="menuitem"
        className="jini-working-dir-item"
        data-testid="working-dir-pick"
        onClick={pick}
      >
        <Icon name="folder" size={14} className="jini-working-dir-item-icon" />
        <span>{workingDir ? t.replace : t.pick}</span>
      </button>

      <div
        className="jini-working-dir-submenu-row"
        onMouseEnter={showRecent}
        onMouseLeave={hideRecent}
      >
        <button
          type="button"
          role="menuitem"
          className="jini-working-dir-item"
          aria-haspopup="menu"
          aria-expanded={recentOpen}
          data-testid="working-dir-recent"
          onClick={toggleRecent}
        >
          <Icon name="history" size={14} className="jini-working-dir-item-icon" />
          <span>{t.recent}</span>
          <Icon name="chevron-right" size={12} className="jini-working-dir-item-chevron" />
        </button>
        {recentOpen ? (
          <WorkingDirRecentFlyout recentDirs={recentDirs} placement={placement} t={t} selectRecent={selectRecent} />
        ) : null}
      </div>

      {canClear ? (
        <button
          type="button"
          role="menuitem"
          className="jini-working-dir-item"
          data-testid="working-dir-clear"
          onClick={clear}
        >
          <Icon name="close" size={14} className="jini-working-dir-item-icon" />
          <span>{t.clear}</span>
        </button>
      ) : null}
    </div>
  );
}

/**
 * Working-directory picker: a borderless trigger that opens a panel with
 * "Choose folder" and a "Recent folders" submenu. Layout is left to the host
 * via `className`; all open/close/keyboard state lives in
 * {@link useWorkingDirPicker}. This component is a dumb render.
 */
export function WorkingDirPicker({
  workingDir,
  recentDirs,
  onPickDirectory,
  onSelectRecent,
  onClear,
  className,
  placement = 'down',
  invalid = false,
  onOpen,
  labels,
  useWorkingDirPicker: useWorkingDirPickerHook = useWorkingDirPicker,
}: WorkingDirPickerProps) {
  const panelId = useId();
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const panelRef = useRef<HTMLDivElement | null>(null);
  const picker = useWorkingDirPickerHook({ onPickDirectory, onSelectRecent, onClear, onOpen, labels });
  const { open, wrapRef, labels: t, toggle, showRecent, hideRecent } = picker;
  useWorkingDirFocusHandoff({ open, triggerRef, panelRef });

  const handlePanelKeyDown = useCallback((event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (handleMenuNavigationKey({ event })) return;
    handleRecentFlyoutKey({ event, showRecent, hideRecent });
  }, [hideRecent, showRecent]);

  return (
    <div
      ref={wrapRef}
      className={withClassName('jini-working-dir-picker', className)}
      data-testid="working-dir-picker"
    >
      <WorkingDirTrigger
        triggerRef={triggerRef}
        workingDir={workingDir}
        invalid={invalid}
        open={open}
        panelId={panelId}
        t={t}
        toggle={toggle}
      />

      {open ? (
        <WorkingDirPanel
          panelRef={panelRef}
          panelId={panelId}
          placement={placement}
          workingDir={workingDir}
          recentDirs={recentDirs}
          canClear={Boolean(workingDir && onClear)}
          t={t}
          picker={picker}
          onKeyDown={handlePanelKeyDown}
        />
      ) : null}
    </div>
  );
}

/**
 * `<AnnotationCanvas>` — draws freehand/box/text marks over arbitrary
 * preview content (`children`: an artifact iframe, a webview, anything) and
 * offers a send/draft/queue submit-action picker. All state/interaction
 * logic lives in `useAnnotationCanvas`; this component is the presentational
 * shell.
 *
 * Origin: `apps/web/src/components/PreviewDrawOverlay.tsx`. See
 * `../../source-map.md`.
 */
import { createPortal } from 'react-dom';
import type { ReactElement, ReactNode } from 'react';
import type { AnnotationCanvasPort } from '../../ports.js';
import type { CaptureTarget, DrawToolbarElement, AnnotationAction, MarkTool } from '../../types.js';
import {
  useAnnotationCanvas,
  type AnnotationCanvasController,
  type TextMarkController,
} from '../hooks/useAnnotationCanvas.js';
import { DEFAULT_ANNOTATION_CANVAS_ICONS, type AnnotationCanvasIconName } from './icons.js';
import { useT } from '../../../react/i18n.js';

export interface AnnotationCanvasProps {
  children: ReactNode;
  active: boolean;
  onActiveChange?: ((active: boolean) => void) | undefined;
  captureViewport?: boolean | undefined;
  captureTarget?: CaptureTarget | null | undefined;
  filePath?: string | undefined;
  sendDisabled?: boolean | undefined;
  sendDisabledReason?: string | undefined;
  hideChrome?: boolean | undefined;
  onToolbarClick?: ((element: DrawToolbarElement, submitAction?: AnnotationAction) => void) | undefined;
  port: AnnotationCanvasPort;
  /** Renders the toolbar/dock into this element via a portal instead of inline (useful to escape a clipped, scaled ancestor). Omit to render inline. */
  toolbarHost?: HTMLElement | null | undefined;
  /** Override any of the toolbar's icons; unset ones fall back to a small built-in generic set (see `icons.tsx`). */
  icons?: Partial<Record<AnnotationCanvasIconName, () => ReactElement>> | undefined;
  className?: string | undefined;
}

function maybePortal(node: ReactNode, host: HTMLElement | null | undefined) {
  return host ? createPortal(node, host) : node;
}

/** Crosshair for drawing tools, an I-beam for the text tool, the default pointer while inactive. */
function annotationCursor(active: boolean, markTool: MarkTool): string {
  if (!active) return 'default';
  return markTool === 'text' ? 'text' : 'crosshair';
}

export function AnnotationCanvas(props: AnnotationCanvasProps) {
  const { children, toolbarHost, icons: iconOverrides, className } = props;
  const icons = { ...DEFAULT_ANNOTATION_CANVAS_ICONS, ...iconOverrides };
  const c = useAnnotationCanvas(props);

  // `c.imagePreviews[c.previewIndex]` is a TS-only possibly-undefined lookup
  // (`noUncheckedIndexedAccess`): `previewIndex` is only ever set to a
  // currently-valid index (the thumbnail's own `onClick={() =>
  // c.setPreviewIndex(i)}` closes over the same array it maps over), and
  // every state change that could shrink `imagePreviews` (`removeExtraFile`)
  // unconditionally resets `previewIndex` to `null` in that same update — so
  // this can never actually be `undefined` while `previewIndex !== null`.
  const activePreview = c.previewIndex !== null ? c.imagePreviews[c.previewIndex]! : null;

  return (
    <div
      ref={c.wrapRef}
      className={className}
      data-annotation-canvas-active={props.active ? 'true' : 'false'}
      style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}
    >
      {children}
      {c.showCanvas ? <DrawingCanvas c={c} active={props.active} /> : null}
      {c.textLayerVisible ? <TextLayer c={c} icons={icons} /> : null}
      {props.active
        ? maybePortal(<AnnotationDock c={c} icons={icons} onToolbarClick={props.onToolbarClick} />, toolbarHost)
        : null}
      {activePreview && typeof document !== 'undefined'
        ? createPortal(<ImagePreviewDialog c={c} icons={icons} preview={activePreview} />, document.body)
        : null}
    </div>
  );
}

type CanvasIcons = Record<AnnotationCanvasIconName, () => ReactElement>;
type ImagePreview = AnnotationCanvasController['imagePreviews'][number];

function DrawingCanvas({ c, active }: { c: AnnotationCanvasController; active: boolean }) {
  return (
    <canvas
      ref={c.canvasRef}
      onPointerDown={c.onPointerDown}
      onPointerMove={c.onPointerMove}
      onPointerUp={c.onPointerUp}
      onPointerCancel={c.onPointerUp}
      style={{
        position: 'absolute',
        inset: 0,
        pointerEvents: active ? 'auto' : 'none',
        cursor: annotationCursor(active, c.markTool),
        visibility: c.chromeHidden ? 'hidden' : 'visible',
        touchAction: 'none',
        userSelect: 'none',
      }}
    />
  );
}

function TextLayer({ c, icons }: { c: AnnotationCanvasController; icons: CanvasIcons }) {
  return (
    <div
      style={{ position: 'absolute', inset: 0, pointerEvents: 'none', visibility: c.chromeHidden ? 'hidden' : 'visible' }}
    >
      {c.textMarks.map((mark) => (
        <TextMarkItem key={mark.id} c={c} icons={icons} mark={mark} />
      ))}
    </div>
  );
}

function TextMarkItem({ c, icons, mark }: { c: AnnotationCanvasController; icons: CanvasIcons; mark: TextMarkController }) {
  const t = useT();
  return (
    <div
      onPointerDown={(e) => c.onTextPointerDown(e, mark)}
      onPointerMove={(e) => c.onTextPointerMove(e, mark)}
      onPointerUp={(e) => c.onTextPointerUp(e, mark)}
      onPointerCancel={(e) => c.onTextPointerUp(e, mark)}
      style={{
        position: 'absolute',
        left: `${mark.x * 100}%`,
        top: `${mark.y * 100}%`,
        pointerEvents: c.markTool === 'text' ? 'auto' : 'none',
        cursor: mark.editing ? 'default' : 'move',
        touchAction: 'none',
      }}
    >
      <textarea
        ref={(el) => {
          c.registerTextArea(mark.id, el);
          if (el) c.autosizeTextArea(el);
        }}
        value={mark.text}
        wrap="off"
        rows={1}
        spellCheck={false}
        readOnly={!mark.editing}
        aria-label={t('Text annotation')}
        onChange={(e) => {
          c.updateTextMark(mark.id, e.target.value);
          c.autosizeTextArea(e.currentTarget);
        }}
        onBlur={() => c.handleTextBlur(mark.id)}
        onKeyDown={(e) => {
          if (e.key === 'Escape') {
            e.stopPropagation();
            c.handleTextEscape(mark.id, e.currentTarget);
          }
        }}
        style={{
          display: 'block',
          margin: 0,
          padding: 0,
          border: 'none',
          outline: 'none',
          background: 'transparent',
          resize: 'none',
          overflow: 'hidden',
          whiteSpace: 'pre',
          color: 'var(--jini-danger)',
          caretColor: 'var(--jini-danger)',
          fontWeight: 600,
          fontSize: c.textFontPx,
          lineHeight: 1.25,
          minWidth: Math.max(2, Math.round(c.textFontPx * 0.5)),
          pointerEvents: mark.editing ? 'auto' : 'none',
          userSelect: mark.editing ? 'text' : 'none',
          cursor: mark.editing ? 'text' : 'move',
        }}
      />
      {c.markTool === 'text' ? (
        <button
          type="button"
          onPointerDown={(e) => {
            e.preventDefault();
            e.stopPropagation();
          }}
          onClick={() => c.removeTextMark(mark.id)}
          aria-label={t('Remove text annotation')}
          title={t('Remove text annotation')}
        >
          {icons.close()}
        </button>
      ) : null}
    </div>
  );
}

function AnnotationDock({
  c,
  icons,
  onToolbarClick,
}: {
  c: AnnotationCanvasController;
  icons: CanvasIcons;
  onToolbarClick: AnnotationCanvasProps['onToolbarClick'];
}) {
  const t = useT();
  return (
    <div
      ref={c.dockRef}
      data-annotation-canvas-dock-layout={c.dockPlacement.layout}
      data-annotation-canvas-dock-side={c.dockPlacement.side ?? undefined}
      style={{ position: 'absolute', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8, ...c.dockPlacement.style }}
    >
      {c.captureWarning ? (
        <div role="status" aria-live="polite" style={{ visibility: c.chromeHidden ? 'hidden' : undefined }}>
          <span>{c.captureWarning.message}</span>
        </div>
      ) : null}
      {c.imagePreviews.length > 0 ? <AttachedImages c={c} icons={icons} /> : null}
      <div
        role="toolbar"
        aria-label={t('Annotation tools')}
        style={{ display: 'flex', alignItems: 'center', gap: 6, visibility: c.chromeHidden ? 'hidden' : undefined }}
      >
        <MarkToolPicker c={c} icons={icons} />
        <button type="button" onClick={c.undoStroke} disabled={!c.canUndo} aria-label={t('Undo')} title={t('Undo')}>
          {icons.undo()}
        </button>
        <button type="button" onClick={c.redoStroke} disabled={!c.canRedo} aria-label={t('Redo')} title={t('Redo')}>
          {icons.redo()}
        </button>
        <input
          ref={c.fileInputRef}
          type="file"
          accept="image/*"
          multiple
          style={{ display: 'none' }}
          onChange={c.onFileInputChange}
        />
        <button
          type="button"
          onClick={() => {
            onToolbarClick?.('attach_image');
            c.fileInputRef.current?.click();
          }}
          disabled={c.sending}
          aria-label={t('Attach image')}
          title={t('Attach image')}
        >
          {icons.attach()}
        </button>
        <input
          value={c.note}
          onChange={(e) => c.setNote(e.target.value)}
          onPaste={c.onNotePaste}
          disabled={c.sending}
          placeholder={t('Add a note…')}
          aria-label={t('Annotation note')}
          onCompositionStart={c.onCompositionStart}
          onCompositionEnd={c.onCompositionEnd}
          onKeyDown={c.onNoteKeyDown}
        />
        <SubmitPicker c={c} icons={icons} />
      </div>
      <button
        type="button"
        onClick={() => {
          onToolbarClick?.('exit');
          c.closeOverlay();
        }}
        disabled={c.sending}
        aria-label={t('Close annotation tools')}
        title={t('Close annotation tools')}
      >
        {icons.close()}
      </button>
    </div>
  );
}

function AttachedImages({ c, icons }: { c: AnnotationCanvasController; icons: CanvasIcons }) {
  const t = useT();
  return (
    <div aria-label={t('Attached images')} style={{ display: 'flex', gap: 6, visibility: c.chromeHidden ? 'hidden' : undefined }}>
      {c.imagePreviews.map((item, i) => (
        <div key={item.url} style={{ position: 'relative' }}>
          <button type="button" onClick={() => c.setPreviewIndex(i)} disabled={c.sending} title={item.file.name} aria-label={item.file.name}>
            <img src={item.url} alt="" aria-hidden style={{ width: 44, height: 44, objectFit: 'cover' }} />
          </button>
          <button
            type="button"
            onClick={() => c.removeExtraFile(i)}
            disabled={c.sending}
            aria-label={t('Remove attached image')}
            title={t('Remove attached image')}
          >
            {icons.close()}
          </button>
        </div>
      ))}
    </div>
  );
}

function MarkToolPicker({ c, icons }: { c: AnnotationCanvasController; icons: CanvasIcons }) {
  return (
    <div style={{ position: 'relative' }} ref={c.markToolMenuRef}>
      <button
        type="button"
        onClick={() => c.setMarkToolMenuOpen(!c.markToolMenuOpen)}
        disabled={c.sending}
        aria-haspopup="menu"
        aria-expanded={c.markToolMenuOpen}
        aria-label={c.currentMarkTool.label}
        title={c.currentMarkTool.label}
      >
        {icons[c.currentMarkTool.tool]()}
        {icons['chevron-down']()}
      </button>
      {c.markToolMenuOpen ? (
        <div role="menu" aria-label={c.currentMarkTool.label}>
          {c.markToolOptions.map((item) => {
            const isActive = c.markTool === item.tool;
            return (
              <button
                key={item.tool}
                type="button"
                role="menuitemradio"
                aria-checked={isActive}
                aria-label={item.label}
                disabled={c.sending}
                onClick={() => c.selectMarkTool(item.tool)}
              >
                {icons[item.tool]()}
                <span>{item.label}</span>
                {isActive ? icons.check() : null}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

function SubmitPicker({ c, icons }: { c: AnnotationCanvasController; icons: CanvasIcons }) {
  const t = useT();
  return (
    <div style={{ position: 'relative', display: 'inline-flex' }} ref={c.submitMenuRef}>
      <button
        type="button"
        onClick={() => void c.send(c.submitAction)}
        disabled={c.sending || !c.currentSubmit.enabled}
        aria-label={c.sending ? c.currentSubmit.pendingLabel : c.currentSubmit.label}
        title={c.sending ? c.currentSubmit.pendingLabel : c.currentSubmit.title}
      >
        {c.sending ? icons.spinner() : icons[c.submitAction]()}
        <span>{c.currentSubmit.label}</span>
      </button>
      <button
        type="button"
        onClick={() => c.setSubmitMenuOpen(!c.submitMenuOpen)}
        disabled={c.sending || !c.canSubmit}
        aria-haspopup="menu"
        aria-expanded={c.submitMenuOpen}
        aria-label={t('Submit options')}
        title={t('Submit options')}
      >
        {c.submitMenuOpen ? icons['chevron-down']() : icons['chevron-up']()}
      </button>
      {c.submitMenuOpen ? (
        <div role="menu" aria-label={t('Submit options')}>
          {c.submitOptions.map((opt) => {
            const isActive = c.submitAction === opt.action;
            return (
              <button
                key={opt.action}
                type="button"
                role="menuitemradio"
                aria-checked={isActive}
                aria-label={opt.label}
                disabled={!c.sending && opt.enabled ? undefined : true}
                title={opt.title}
                onClick={() => c.chooseSubmitAction(opt.action)}
              >
                {icons[opt.action]()}
                <span>{opt.label}</span>
                {isActive ? icons.check() : null}
              </button>
            );
          })}
        </div>
      ) : null}
    </div>
  );
}

function ImagePreviewDialog({ c, icons, preview }: { c: AnnotationCanvasController; icons: CanvasIcons; preview: ImagePreview }) {
  const t = useT();
  return (
    <div role="dialog" aria-modal="true" aria-label={preview.file.name} onMouseDown={(e) => {
      if (e.target === e.currentTarget) c.setPreviewIndex(null);
    }}>
      <div>
        <div>
          <span title={preview.file.name}>{preview.file.name}</span>
          <button type="button" onClick={() => c.setPreviewIndex(null)} aria-label={t('Close')} title={t('Close')}>
            {icons.close()}
          </button>
        </div>
        <img src={preview.url} alt={preview.file.name} />
      </div>
    </div>
